INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015960', 'AN1646', 'イヴ', 'Eve is the main protagonist of the BIRDIE WING: Golf Girls'' Story series. She is a survivor who made a living by betting on golf. Her struggling past resulted in a rough and powerful playing style.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253820-yVhieWvjxZNO.png', NULL, NULL, '鬼頭明里', NULL, 253820, 'MAIN', 247) ON CONFLICT DO NOTHING;
