INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015981', 'AN1647', 'プロデューサー', 'The producer responsible for the child idols in the Third Entertainment Section. Despite his childish appearance, he is indeed an adult. He is self-conscious about his small height and childish appearance. He prefers mature idols, but he does his best to help and produce the idols at the Third Entertainment Section. He is voiced by Yuuki Yonai in a drama CDs, and was thus nicknamed YonaiP.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b56795-T7Bg5GXFnvxA.png', NULL, NULL, '米内佑希', NULL, 56795, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015982', 'AN1647', '龍崎薫', 'Hometown: Ehime Prefecture, Japan  Kaoru is one of the youngest idols in Cinderella Girls. She is portrayed to be innocent and very energetic. Kaoru first met the Producer in the park and cheered him up as he picked up some documents that he had dropped. She revealed that she participated in some kids'' television shows and interviews with her mother. When the Producer scouted her, she was hesitant at first as she didn''t know anything about idols. However, when he tells her that it consists of ch', 9, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b75004-vE023IwAqTFW.png', '7月20日', 'O', '春瀬なつみ', 135, 75004, 'MAIN', 41) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015983', 'AN1647', '橘ありす', 'Hometown: Hyogo Prefecture, Japan  Arisu is a studious, responsible young girl. She loves to play games and frequently becomes engrossed in reading mystery novels. Arisu hates her name and prefers to be referred to by her surname because she deems it childish. She says that it sounds like a name out of a fairy-tale, which could be in reference to "Alice in Wonderland"; a story that her parents often read aloud to her. One of Arisu''s favorite food is strawberries, and many of her cards and outfit', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129277-Q8PcGzEmJ31J.png', '7月31日', 'A', '佐藤亜美菜', 141, 129277, 'MAIN', 193) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015984', 'AN1647', '古賀小春', 'Hometown: Saga Prefecture, Japan  In the tie in Cinderella Girls Theater skits, Koharu is shown to be a sweet girl who owns an iguana named Hyou. She wishes to be a princess, and seems to be good at giving compliments. Koharu likes Twister, and hopes to play with the Producer someday. She is the fifth idol to join the "Little Marching Band Girls" unit, and uses a set of hand bells. During her talk battle, she tells about the boys in her class swinging sculpting knives around dangerously. She doe', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139605-uAtvF2P6qup4.png', '4月1日', 'O', '小森結梨', 140, 139605, 'MAIN', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015985', 'AN1647', '櫻井桃華', 'Hometown: Kobe Prefecture, Japan  Momoka is a young, elegant girl from a wealthy family. Due to her princess-like demeanor, she has a lady-like aura surrounding her. While Momoka tries to act older than she is, she is still a just a young girl and enjoys things others her age enjoy. Despite insisting she be treated like a lady, she uses the childish honorific "-chama" when addressing the Producer. Momoka enjoys tea parties and takes them very seriously, inviting many of the idols to partake in t', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129269-bstsl8XVGMMe.png', '4月8日', 'A', '照井春佳', 145, 129269, 'MAIN', 215) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015986', 'AN1647', '赤城みりあ', 'Hometown: Tokyo, Japan  Miria is a young girl who really loves to talk. Possessing boundless energy, a sunny and positive outlook, and enthusiasm for everything she does, Miria became an idol because doing all the cute things seemed fun.', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88635-LJm9OQKMefNZ.png', '4月14日', 'AB', '黒沢ともよ', 140, 88635, 'MAIN', 117) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015987', 'AN1647', '的場梨沙', 'Hometown: Yamaguchi Prefecture, Japan  Risa is a demanding young girl who absolutely adores her father. It seems her father gives her anything she wants. Risa seems to have a cheetah or tiger motif, and usually wears prints of these animals in her clothes. In her S Rare+ she carries a white tiger cub, and in her second S Rare she has a plush like the cub she held in the former card. It is implied her father may be a poacher, as her second S Rare shows she has a rug made out of giraffe skin, and ', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139606-r8cp8W6vufz3.png', '11月19日', 'B', '集貝はな', 143, 139606, 'MAIN', 108) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015988', 'AN1647', '結城晴', 'Hometown: Ehime Prefecture, Japan  Haru is a former rival idol who enjoys soccer. She has a harsh, no holds barred personality. A big tomboy, Haru uses the pronoun "ore", which is barely used by females. She doesn’t like cute clothes and shows extreme displeasure when forced into a bunny costume for an event. Haru has been shown performing with Hiromi Seki and Yuu Ohta during lives. She appears to be good friends with Risa Matoba, to the point where Haru and Risa formed a duo unit named "Beat Sh', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129294-tjLBCtYdSOA2.png', '7月17日', 'A', '小市眞琴', 140, 129294, 'MAIN', 60) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015989', 'AN1647', '佐々木千枝', 'Hometown: Toyama Prefecture, Japan  A shy elementary school student. She is very easily scared of people she doesn’t know. However, once she begins to trust others, Chie becomes very level-headed and mature, even flirty, after idol work. She admits that she doesn’t trust in her idol skills, and has been found out to have developed a crush on Producer by the time she receives her first idol form.  In the tie-in Cinderella Girls Theater skits, Chie shows that she still believes that theme park mas', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129303-eKphLhEDSkZ3.png', '6月7日', 'A', '今井麻夏', 139, 129303, 'MAIN', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015990', 'AN1647', '市原仁奈', 'Hometown: Shizuoka Prefecture, Japan  One of the youngest idols in the Cinderella Cast, Nina is a perky, naive girl who is almost always seen in kigurumi. Despite being hardworking and capable, Nina is still a young girl and often acts her age. She dislikes being alone and wants the producer to stay by her side and look after her.  She also tend to refer to her self in third person and even though she uses polite conjugations, she tends to mispronounce the negative ending and ends up using rude ', 9, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b75002-X3i8oiTu3irk.png', '2月8日', 'B', '久野美咲', 128, 75002, 'MAIN', 93) ON CONFLICT DO NOTHING;
