INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015992', 'AN1647', '川島瑞樹', 'Hometown: Osaka  Previously a newscaster, Mizuki decided instead to pursue the path of becoming an idol. She''s nearing her 30''s and is a bit self-conscious about that, taking very good care of her appearance, and eagerly competing with her younger comrades. Her insecurity about her age stretches into not having a boyfriend or husband.  She acts as a role model for some of the idols. For example, she taught Karin Domyoji how to speak more clearly and smoothly. She is very mature and hard-working ', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129268-EBWrFmXkAV0q.png', '11月25日', 'A', '東山奈央', 159, 129268, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
