INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016002', 'AN1647', '塩見周子', 'Hometown: Kyoto Prefecture, Japan  A footloose and relaxed girl from Kyoto, Syuko used to help watch her parent''s Wagashiya shop until getting kicked out after an argument with them. Needing to fend for herself after being kicked out, Syuko began working as a waitress and had a ''hobby'' of donating blood in order to scrounge up money to live on. The Producer ends up recruiting Syuko and she stays in the production''s dormitories. Syuko reveals that even though her parent''s kicked her out because s', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129293-JXrzPNmq5ats.png', '12月12日', 'B', 'ルゥティン', 163, 129293, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
