INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016004', 'AN1647', '安部菜々', 'An eccentric part-timer maid of dubious age who claims to be an eternally 17 year old alien originating from Planet Usamin. She’s very nice, determined and hardworking, traits which are often overlooked due to her other rather eccentric qualities. She will often communicate with Planet Usamin, while using the sound, "Piipii☆". She''s a huge fan of anime and dreams of becoming a seiyuu, to the point where she practices dubbing over lines when she watches anime.  In her CINDERELLA MASTER CD, Nana g', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120774-dw3NnSfHcrcP.png', '5月15日', 'O', '三宅麻理恵', 146, 120774, 'SUPPORTING', 112) ON CONFLICT DO NOTHING;
