INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016008', 'AN1647', '佐藤心', 'Hometown: Nagano Prefecture, Japan  Shin is a quirky girl with a cute personality who likes making her own idol costumes. Her surname means "sugar", while her given name is written with the character for "heart", and she loves to point out her cuteness and sweetness. She also enjoys being called "Sweetie". She uses sugar and hearts as a stage gimmick and goes as far as throwing hearts at members of her audience in two of her cards. Shin is 26 years old but she claims to looks like a teenager. Sh', 26, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129275-m6xahw6Z82e9.png', '7月22日', 'AB', '花守ゆみり', 166, 129275, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
