INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016010', 'AN1647', '城ヶ崎美嘉', 'Hometown: Saitama Prefecture, Japan  She is the older sister of Rika Jougasaki. Mika Jougasaki is a fan of the gal subculture. Like any older sister, she and Rika don''t always see eye to eye, and squabble on occasion, but most of the time they get along just fine. Mika really cares for her little sister, and serves as a bit of a role-model for her. Her experience as an older sister also shows itself frequently when it comes to interacting with idols younger than her for the Cinderella Radio segm', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b78121-QLKIdJBjSawx.jpg', '11月12日', 'AB', '佳村はるか', 162, 78121, 'SUPPORTING', 174) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016011', 'AN1647', '三船美優', 'Hometown: Iwate Prefecture, Japan  Miyu is a beautiful yet apparently lonely woman. Before becoming an idol, she was an office lady. In the original game, she met the Producer on Christmas Eve, a holiday usually reserved for couples in Japan. She is very shy and nervous, and has trouble smiling or enjoying herself. Miyu had a Golden Retriever in her childhood, but its death is one of the causes she gained her sad and somewhat tragic nature, on top of an implied troubled past. She has a crush on ', 26, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129281-B6g671eAeqAp.png', '2月25日', 'AB', '原田彩楓', 165, 129281, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
