INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016013', 'AN1647', '輿水幸子', 'Hometown: Yamanashi Prefecture, Japan  Sachiko is a girl beaming with astounding confidence, priding herself in being the cutest. She doesn''t consider herself a competitive person. However, she doesn''t like to lose and doesn''t easily admit to failure. When she''s defeated as the boss of the Saitama area, Sachiko gives many excuses such as "I have a lot of homework to do so I''m going home".  From Sachiko''s point of view, the Shining Aurora Traveler''s Journal mobage event is a journey to let her fa', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/89008-yxq2UfQfEan5.png', '11月25日', 'B', '竹達彩奈', 142, 89008, 'SUPPORTING', 108) ON CONFLICT DO NOTHING;
