INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016017', 'AN1647', '高垣楓', 'Hometown: Wakayama Prefecture  Kaede is a mature and mysterious idol. She is very quiet, never saying more than necessary. Her hobbies are visiting and relaxing in onsen. She''s also is a huge fan of lame puns and can continue for hours with this if the Producer can’t stop it. She can instantly smell the difference between body wash and shampoo products, has heterochromia, and has a beauty mark under her right eye.  Once Kaede has had a few drinks, all of her common sense goes out the window. She', 25, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88948-Tdb4KBJNNf7z.png', '6月14日', 'AB', '早見沙織', 171, 88948, 'SUPPORTING', 156) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016018', 'AN1647', '島村卯月', 'Hometown: Tokyo, Japan  An extraordinarily ordinary girl, Uzuki is always positive and bright, showing dedication towards being an idol. Her ordinary personality and her smile are seen as her defining traits. She''s so average in fact that it''s almost bizarre, counting such feats as consistently scoring right in the middle of her school''s exam rankings, or always running around the middle of the pack in sporting events, or having never drawn any fortune but the average Good Luck over the course o', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b70883-DreEmVe3UADs.png', '4月24日', 'O', '大橋彩香', 159, 70883, 'SUPPORTING', 200) ON CONFLICT DO NOTHING;
