INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016028', 'AN1648', 'ラバー・スーツ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297438-TV3L26b9SMw5.jpg', NULL, NULL, '内田雄馬', NULL, 297438, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016029', 'AN1649', '鳳ここな', 'Kokona is a 16-year-old high school sophomore. She has been fascinated by the Sirius theater since she was a child and auditioned to join the company to become a World Dai Star. She has a cheerful and friendly personality who can get along with anyone. She lacks confidence in her performance and skills, and often becomes timid. But she admired and strongly trusts her best friend, Shizuka, who is always so confident.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292903-rWcQ2SFsRmxT.png', '1月20日', NULL, '石見舞菜香', NULL, 292903, 'MAIN', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016030', 'AN1649', '静香', 'Hobbies: Observing people Reason For Acting: "Because I longed for that stage of Sirius that I saw when I was young."  Shizuka is a winsome, confident person with a calm, analytical mind. She has something that Kokona Otori does not have. She is always worried about Kokona, who tends to be weak, and always encourages her and gives her sound advice. The two of them work hard every day to realize their dream of becoming a World Dai Star.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292904-50RspmF2aQJC.png', NULL, NULL, '長谷川育美', 158, 292904, 'MAIN', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016031', 'AN1649', 'カトリナ・グリーベル', 'Reason for Acting: "Naturally, partly due to the influence of those around me."  A 16-year-old from Germany whose parents are both World Dai Stars. After an incident, she left her home country and went to Japan alone to pursue a career in theater. Because she herself has confidence in her skills, she has a high pride and hates to lose.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292905-7liOcFpXW5wz.png', '8月4日', NULL, '天城サリー', 154, 292905, 'MAIN', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016032', 'AN1649', '新妻八恵', 'Reason for Acting: "Hiiragi-san asked me."  An angel-like girl who treats everyone calmly and politely. Although she is only 11-years-old, she boasts overwhelming acting ability that allows her to dominate the stage in an instant, and is currently said to be the only Dai Star candidate in Sirius. On top of that, she is still a mass of improvement power, and is extremely stoic when it comes to acting. She is more indifferent than anyone else when it comes to acting, but she is usually cheerful, k', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292906-CILd00ygpDV9.png', '4月9日', NULL, '長縄まりあ', 146, 292906, 'MAIN', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016033', 'AN1649', '柳場ぱんだ', 'Reason For Acting: "Admiration for Sirius when I saw them at a theater appreciation party."  A 13-year-old who is gaining popularity as a young ace of Sirius. In order to increase her own value, she uses SNS and ego search. Although she is envious of her friendly genius-like intelligence, she continues to make steady efforts every day. She''s friendly, yet a calculating realist. She is a hard-working type of person. She''s envious of the natural ability of other to do anything.', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292907-XtPoEllubcgJ.png', '9月13日', NULL, '大空直美', 157, 292907, 'MAIN', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016034', 'AN1649', '流石知冴', 'Reason For Acting: "Because Panda started."  A kind of genius with a high absorptive ability to quickly make anything her own. She is a childhood friend of Panda, and respects her for her firm ideas. She has a strong presence with her unique sensibility, style and good looks, but she herself is very self-paced. but is a so-called mysterious character who often doesn''t think about anything.', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292908-d9SYd1dzJFBh.png', '3月20日', NULL, '佐々木李子', 165, 292908, 'MAIN', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016035', 'AN1649', '柊望有', 'Reason for Acting: "I admired Shamo and set my sights on the path of acting. My current goal is to produce World Dai Stars from Sirius."  The former No. 1 of Sirius. After her retirement, she turned down invitations from other theater companies and became a behind-the-scenes and vice-president member of Sirius, where her former teacher is. Now mentoring the next generation of performers. She herself is one of the strict and stoic types, and she seems to be leading a dry private life centered on ', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292909-SienGXwJgJFS.png', '2月28日', NULL, '森なな子', 164, 292909, 'MAIN', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016036', 'AN1649', '白丸美兎', 'Reason for Acting: "Because Iroha invited me."  A second-year high school student born and raised in Akihabara. Perhaps because of her complicated family environment, she has a very quiet and passive personality. She has complete trust in her first friend, Iroha, and her hobbies, including cosplay, anime and the entrance exam for Gekidan Denki. During the entrance exam, she showed an amazing quality that makes her possess the role.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292911-zJDioxcvd1sn.png', '5月5日', NULL, '近藤玲奈', 156, 292911, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016037', 'AN1649', '舎人仁花子', 'Reason for Acting: "Because I was scouted."  A first-year high school student from Aogashima. Thanks to the carefree upbringing on an island rich in nature, she has a rich and sharp sensitivity. She joined Eden after being scouted by Hatsumi and others. The most appealing thing about her is her innocent heart, which does not know how to suspect others. Although she has no acting experience, she shows a tremendous possession of the role because of her innocent personality.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292912-sWPwlIoUGb51.png', '6月1日', NULL, '斉藤朱夏', 162, 292912, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016038', 'AN1649', '千寿暦', 'She is the daughter of the Senju family, a prestigious stage family and Iroha''s older sister. She has Dai Star parents. Through tireless efforts, her talent blossomed and she climbed to the rank as the young ace of Gingaza.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318631-huImHwB8S7No.jpg', '10月3日', NULL, '鳥部万里子 ', 159, 318631, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016039', 'AN1649', '連尺野初魅', 'A strong-willed beauty who believes in her own talent and does not doubt it. In fact, her acting is genius and she once passed Gingaza at the top of her class. However, things didn''t go her way and she left Gingaza. She is also a mass of action power that has distinguished herself in Eden when she joined, and has seized the real power.', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318632-2hlMSqPmogmc.png', '5月30日', NULL, '葵井歌菜', 165, 318632, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016040', 'AN1649', '千寿いろは', 'She is the daughter of the stage''s prestigious Senju family, and Koyomi''s younger sister. A second-year high school student who loves anime and manga. Her hobby is cosplay because she can become a specific character, she also has a deep knowledge of makeup. She was drawn to Gekidan Denki''s unique stage performance, which was an extension of that hobby, so she joined the company.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318633-uvNCad4S2n8M.png', '11月30日', NULL, '岡咲美保', 158, 318633, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016041', 'AN1649', 'ラモーナ・ウォルフ', 'Reason for Acting: "It was fun to try."  A third-year high school student who came from Germany. When she was still in Germany, she belonged to the same theater company as Kathrina, and she worries about her coming to Japan alone. The type who is serious and always wants things to be clear. She values ties with people more than anything else, and if someone is in trouble, she immediately lends a helping hand, no matter who it is.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292910-dqvSU0vJBNFi.png', '5月23日', NULL, '田中美海', 163, 292910, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
