INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016048', 'AN1650', 'エリー', 'Serving in BRT5’s central role, she is like a mother figure to the other members. Her proclivity for smiling and gentle way of speaking make her the most amiable of her team.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293785-CnFyvDtDkYBl.jpg', '6月28日', NULL, '吉木悠佳', NULL, 293785, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
