INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016050', 'AN1650', 'サラ', 'A girl who enjoys writing songs. She can play just about any instrument, and is good at sports to boot. She tends to expect others to be as skilled as she is, and as such her choice of words can sometimes be harsh.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293787-WuXOmPaTLNDd.jpg', '11月30日', NULL, '夏目妃菜', NULL, 293787, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
