INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016052', 'AN1650', 'ハル', 'The youngest member in her group, she is quick to laugh and cry, and is a big eater. Though she is treated as the group’s little sister, she is skilled at reading between the lines when communicating. She finds no displeasure in working to help others.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293788-VQTPaI3MUYRo.jpg', '9月17日', NULL, '矢野妃菜喜', NULL, 293788, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016053', 'AN1650', 'ジュア', 'A girl who is capable of being frank with whoever she meets. Her tendency to go all out even when she first meets someone often leaves others feeling overwhelmed. She loves Seia with all her heart.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294390-x2zosPLe6V6j.jpg', '5月5日', NULL, '南雲希美', NULL, 294390, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
