INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016055', 'AN1650', 'セア', 'Though she is a highly skilled virtual artist, she is also a realist who thinks that now is the only time she will ever be in the limelight. Though she would never openly admit it, she adores Jua.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294391-7VGkhBbT1jmD.jpg', '11月14日', NULL, '月乃', NULL, 294391, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
