INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016057', 'AN1650', 'ヒメナ', 'Ximena is super friendly to everyone and is the glue of the group When she is amazed by something she always says ” Un-be-lie-vable!”', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294847-zXeNDdcokp5s.jpg', '8月26日', NULL, '荒井瑠里', NULL, 294847, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016058', 'AN1650', 'ニスカ', 'A virtual artist and virtual designer, she has accomplished much as a designer since entering ADEN. She finds herself wanting to know more about Miracle after their first encounter, and offers her friendly advice in a variety of situations.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293783-UkLxy4TzhbCa.jpg', '2月10日', NULL, '松岡侑李', NULL, 293783, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016059', 'AN1650', 'ゾーイ', 'Zoe’s performances have a great reputation. She also has an amazing voice.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294848-HWKkrTN9KfCl.jpg', '10月22日', NULL, '古畑奈和', NULL, 294848, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
