INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016061', 'AN1650', 'ジェシー', 'Born to a family of opera singers, she was always treated like a princess growing up. She can be selfish, but she wears her heart on her sleeve and is never insincere.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293784-m3nkt1zOCRvv.jpg', '8月7日', NULL, '蘭笛', NULL, 293784, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016062', 'AN1650', 'ソフィア', 'Sofia has been a great programmer since she was very young. She started 3DM8 and is the brains of the group！', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294850-27mTIHevRAc1.jpg', '3月30日', NULL, '北原侑奈', NULL, 294850, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016063', 'AN1650', 'バニティ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '南真由', NULL, 303418, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016064', 'AN1651', '桃宮いちご', 'Ichigo was just a normal 12-year old junior high student who was on a date with Aoyama Masaya until her DNA is mysteriously merged with the DNA of an Iriomote Wildcat. Now she is the ''leader'' of a group of girls, whose DNA were also merged with that of an endangered species, called Tokyo Mew Mew. The Mew Mews have to save the world from Chimera Animas, the aliens, and the alien leader, Deep Blue. Originally, Ichigo wants nothing to do with the "Mew Project", instead wishing to simply spend time ', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2690-1MMNba7QrHDy.jpg', '3月15日', 'O', '天麻ゆうき', 152, 2690, 'MAIN', 544) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016065', 'AN1651', '藤原ざくろ', 'Zakuro Fujiwara is the last of the main Mew Mews introduced. Her DNA is merged with a Grey Wolf.   Zakuro went to a prestigious school and was fully educated. Much of her past isn''t mentioned in the manga but is shown more in the anime. It was mentioned in one episode, that she used to live in America, as she left ''home'' two years before the series started.  In Tokyo Mew Mew, it is shown that someone close to Zakuro died in the form of a flashback. She had to take care of herself when her parent', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2694-krd6JKqyvy0Q.png', '9月6日', 'O', '石井萌々果', 172, 2694, 'MAIN', 273) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016066', 'AN1651', '碧川れたす', 'She is the third member of Tokyo Mew Mew to be introduced and her DNA is merged with a Fin-less Porpoise. She is a shy, second-year junior high student who attends Okumura Junior High (Excalibur High School in the English anime adaptation) and works at Café Mew Mew.  In the anime, Lettuce has a younger brother named Uri. Her parents, Yomogi and Eizaburou Midorikawa, always encouraged her to "Be herself, and someday, she will have real friends.".  Before meeting Ichigo, she still had her ''friends', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2692-WGF3QlF22I13.png', '4月29日', 'B', '十二稜子', 162, 2692, 'MAIN', 122) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016067', 'AN1651', '黄歩鈴', 'She is the fourth Mew Mew to be introduced and her DNA is merged with a Golden Lion Tamarin.  Bu-Ling likes doing acrobatics and is very playful. The other Mew Mews agree that her monkey DNA is a perfect match for her personality, as she is full of energy and loves having fun – to the point where Mint considers her very immature. She is also the most hyperactive member of the team, even more-so than Ichigo. But she can be serious at times.   (Source: Tokyo Mew Mew Wiki)', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2693-Cls8qzeHpzbT.png', '8月7日', 'O', '戸田梨杏', 138, 2693, 'MAIN', 154) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016068', 'AN1651', '藍沢みんと', 'She is the second Mew Mew to be introduced and her D.N.A is merged with the Blue Lorikeet.   When Mint was a child, she would show her dancing to her older brother. But one day, her brother was taken to a prestigious school. They never spoke to one another much afterward. Besides that, Minto had a wonderful childhood. She used to see her parents often inside her home before they became focused on work. Mint was learning Ballet as a little girl and was becoming a very good dancer. She had many re', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2691-1fRDi6x7s8mh.png', '10月3日', 'A', '日向未来', 146, 2691, 'MAIN', 234) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016069', 'AN1651', 'タルト', 'He is the one of the alien antagonists who come to Earth, wishing to "reclaim it."  Tart is kind of a crybaby and hates to be called chibi/chibiko (Japanese for runt, or midget) in Tokyo Mew Mew. He argues a lot with Ichigo and usually resorts to name calling. Overall, he is a rude and childish alien who likes to have fun, and make people cry. He is more prone to laughing out of true amusement (as opposed to Pie''s solemn expression and Quiche''s ''evil smirk''), and throws occasional tantrums when ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b13398-msGQ8raCuWRz.png', NULL, NULL, '山下大輝', NULL, 13398, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016070', 'AN1651', '桃宮さくら', 'Sakura Momomiya is one of the supporting characters in the manga and anime series Tokyo Mew Mew. Sakura has short cherry red hair that frames her face. This, and her large brown eyes and light skin, show that Ichigo&#039;s appearance greatly resembles her mother&#039;s. Sakura&#039;s age is unknown, but she looks very youthful. Sakura is a sweet, young woman. She knows Masaya Aoyama and is happy about Ichigo dating him, unlike her husband Shintaro, and she is also more understanding towards Ichi', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40046-k6gV4enEL5Bb.png', NULL, NULL, '中島沙樹', NULL, 40046, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016071', 'AN1651', 'キッシュ', 'He is the first of the alien antagonists who come to Earth, wishing to "reclaim it." His people were originally from Earth, and were forced to flee their planet. He hates humans for turning Earth into a trash heap so he, Tart, and Pie use Chimera animals to destroy the human race.    He is a carefree, playful, clever, optimistic, and a rather open-minded person, although this is somewhat hidden by his blood-lustful intentions for humans. He enjoys torturing Ichigo Momomiya, his main enemy, whom ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/4289.jpg', '2月14日', NULL, '岡本信彦', NULL, 4289, 'SUPPORTING', 274) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016072', 'AN1651', 'マシャ', 'Masha (マシャ Masha?) is a robot created by Ryou to detect chimera animas and mew aqua. Originally called by her model number of R2000, Ichigo renames her &quot;Masha&quot; after her crush Masaya. Masha likes the new name and likes being with Ichigo. After the aliens are defeated, Masha chooses to stay with Ichigo when Ichigo goes to London with Masaya. In addition to detecting the chimera animas, Masha eats the jelly-fish like parasites that come out of the victims after the Mew Mews defeat them. ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/13402.jpg', NULL, NULL, '石原夏織', NULL, 13402, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016073', 'AN1651', 'パイ', 'Pie (パイ Pai?) comes to Earth with Tart to aid Kish in preparing the planet of the arrival of Deep Blue. Serious natured, he is calmly analytical during his initial attacks on the Mew Mews, scientifically escalating the &quot;mortality rate&quot; of each chimera anima he sends and, when they are defeated, noting that &quot;stronger tactics will be needed. Pie, like the other aliens, has the ability to fly and to transport himself. He attacks using chimera anima creations and with physical attacks', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/13399.jpg', '2月13日', NULL, '梅原裕一郎', NULL, 13399, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016074', 'AN1651', '藍沢誓司', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b277525-5vrvGmkYgOef.png', NULL, NULL, '石田彰', NULL, 277525, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016075', 'AN1651', '赤坂圭一郎', 'Keiichiro is the manager and baker of Cafe Mew Mew and Ryouss partner in the Mew Project.  Five years before the start of Tokyo Mew Mew, Keiichiro worked with Dr. Shirogane, Ryou&#039;s father, on the Mew Project in the United States. After Ryou''s parents were killed in a lab explosion, Keiichiro went with Ryou to Japan to continue working on the Mew Project. Keiichiro cares a great deal for Ryou, and worries when he risks himself to help the Mew Mews. Knowing he couldn''t stop Ryou, though, he o', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2697-rtB0RM0ljvbx.png', '11月12日', NULL, '白井悠介', NULL, 2697, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016076', 'AN1651', '本条みわ', 'Miwa is one of Ichigo''s friends and also her classmate, however, she is unaware of the Mew Mews. One of her other friends, Moe Yanagida, is also unaware of the Mew Mews. They are seen together, most of the time, and they are in almost every episode of the anime.  In episode 23 of the anime, Keiichiro Akasaka, the baker from CaféMew Mew, helped Miwa pay for a box of tea, so she developed a crush on him. Miwa and Moe, who has a crush on Ryou Shirogane, made gifts for their crushes, as suggested by', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40048-Yr7DlhDpWnsH.png', NULL, NULL, '鈴木愛奈', NULL, 40048, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016077', 'AN1651', '青山雅也', 'Masaya Ayoama is Ichigo''s long time secret love. He is extremelly skilled at kendo, one of the top best students in his club. In episode 1 he and ichigo go to the red data animal exhibit as their first date.', 13, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2695-MTBg0KlsTNLZ.jpg', '5月22日', NULL, '内田雄馬', NULL, 2695, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016078', 'AN1651', '柳田もえ', 'Moe is one of Ichigo''s friends and also her classmate, however, she is unaware of the Mew Mews. One of her other friends, Miwa Honjo, is also unaware of the Mew Mews. They are seen together, most of the time, and they are in almost every episode of the anime. In episode 23 of the anime, Ryou Shirogane saved Moe from some thugs, so she developed a crush on him. Moe and Miwa, who has a crush on Keiichiro Akasaka, made gifts for their crushes, as suggested by Ichigo, to win their hearts. They put a', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40047-Ar2AOOQYnXXz.png', NULL, NULL, '佐伯伊織', NULL, 40047, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016079', 'AN1651', '白金稜', 'Ryou comes from a wealthy family and has been stated to have an IQ surpassing 180, making him a natural genius, especially when it comes to genetics. It has also been rumored that he graduated from an American University. Because of this, and events in his past, he has a removed, sarcastic, and rude nature towards most of the cast, apart for his childhood friend, Akasaka-san. Despite this, he seems to be a kind person underneath, something that Ichigo catches on to later in the series, probably ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2696-9FqfNebm5wtI.png', '6月5日', NULL, '中村悠一', NULL, 2696, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016080', 'AN1651', '桃宮慎太郎', 'Shintaro is a handsome man. He has pitch black, spiky hair, tan skin, and cold, gray eyes.  Shintaro is rather strict and tempermental towards Ichigo, but only because he wants to protect her. Shintaro is actually very caring despite his outward appearance.      (Source: Tokyo Mew Mew Wikia)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/39047.jpg', NULL, NULL, '日野聡', NULL, 39047, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
