INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016109', 'AN1653', 'アザリー・ケットシー', 'She is Orphen''s foster sister, best friend, and the Bloody August. They were in the same orphanage and came to the Tower of Fangs together, believed to be magical-prodigies. She tutored him a lot, and gave him special attention. She was a great sorcerer—maybe one of the greatest. However, she had two sides to her: the kind, loving Azalie and the, as Orphen says, "scary" Azalie. After having her love declaration to someone else rejected, she seemed to be almost obsessed with her studies; she want', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b9685-Vayp0r3pJsBG.png', NULL, NULL, '日笠陽子', NULL, 9685, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
