INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016135', 'AN1655', '立花投馬', 'Brother of Souichirou Tachibana and Otomi Tachibana. Studies at Meisei middle school and is in the baseball club. Plays as third baseman although he is a better pitcher than the current ace.', 13, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b66347-UEoXQpiC1b6J.png', NULL, NULL, '梶裕貴', NULL, 66347, 'MAIN', 21) ON CONFLICT DO NOTHING;
