INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016142', 'AN1655', '赤井智仁', 'Tomohito Akai is a standout member at Kenjou High School.  He and his younger brother, Ryo Akai, do not get along and clash harshly.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b185840-8kTmplrbHBpj.png', NULL, NULL, '鈴木達央', NULL, 185840, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016143', 'AN1655', '原田正平', 'A big, intimidating schoolmate at Meisei. Despite his appearance and gruff attitude, Harada frequently gives Tatsuya sound advice on various matters, and at times shows he genuinely cares about his wellbeing.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b14239-hzfXO6kwmCWD.png', NULL, NULL, '銀河万丈', NULL, 14239, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016144', 'AN1655', '西村勇', 'A somewhat conceited pitcher who overestimates his worth in the story. He has a decent curve ball, but is not considered a threat by any of the main characters. He is easily forgotten and ignored, but considers Akio Nitta to be his only rival.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/3914.jpg', NULL, NULL, '中尾隆聖', NULL, 3914, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
