INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016229', 'AN1660', '夏油傑', 'Species: Human Occupation: Curse User Grade: Special Grade Curse User Cursed Technique: Cursed Spirit Manipulation  Suguru Getou is an antagonist in both the Jujutsu Kaisen series and its prequel Jujutsu Kaisen 0: Jujutsu High.', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133699-FCnXaISgazAi.png', '2月3日', NULL, '櫻井孝宏', 183, 133699, 'MAIN', 8243) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016230', 'AN1660', '釘崎野薔薇', 'Occupation: Jujutsu Sorcerer, Student Affiliation: Tokyo Jujutsu High Grade: Grade 3 Sorcerer  She is a first-year student and grade 3 jujutsu sorcerer at Tokyo Jujutsu High studying under Satoru Gojo alongside Yuji and Megumi.   Nobara is a confident and brash young woman with an unshakable character. More than anything, Nobara is determined to stay true to herself no matter what. She takes great pride in being both a pretty girl and a strong fighter, refusing to let anyone influence her.  Init', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133700-f6sOO3TcgLV6.png', '8月7日', NULL, '瀬戸麻沙美', 160, 133700, 'MAIN', 14544) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016231', 'AN1660', '伏黒甚爾', 'Touji Fushiguro, born Touji Zenin, is the father of Megumi Fushiguro. He took a job from the Star Religious Group to assassinate the Star Plasma Vessel.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162722-btzdghBizxKS.jpg', '12月31日', NULL, '子安武人', NULL, 162722, 'SUPPORTING', 7674) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016232', 'AN1660', 'コークン', 'Koukun is a minor antagonist in the Jujutsu Kaisen series. He is a soldier formerly aligned with a faction of curse users called Q.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306268-49iFgcDudSAC.jpg', NULL, NULL, '喜屋武和輝', NULL, 306268, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
