INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016236', 'AN1660', '祢木利久', 'Curse user who used to be a commander in Suguru Getou''s "family" of sorcerers. After Suguru''s death, Negi and Manami Suda both decided to carry on his will by joining the entity to who stole his body.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306257-XmeYJw91idBY.png', NULL, NULL, '井上剛', NULL, 306257, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016237', 'AN1660', '真人', 'Grade: Special Grade Cursed Technique: Idle Transfiguration  Mahito is one of the primary antagonists of the Jujutsu Kaisen series. He is a Cursed Spirit allied with Suguru Geto, Jogo, Hanami and several others. Their ultimate goal is the eradication of humanity and ultimately replacing the population with Cursed Spirits.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133702-Y7JRG5vAvjIL.png', NULL, NULL, '島﨑信長', NULL, 133702, 'SUPPORTING', 2992) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016238', 'AN1660', 'バイエル', 'Bayer is a minor antagonist in the Jujutsu Kaisen series. He is a soldier formerly aligned with a faction of curse users called Q.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306267-7QXgLLV4bMVB.jpg', NULL, NULL, '徳本恭敏', NULL, 306267, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016239', 'AN1660', '三輪霞', 'Species: Human Occupation: Jujutsu Sorcerer, Student Affiliation: Kyoto Metropolitan Curse Technical College Grade: Grade 3 Sorcerer  A second-year at Kyoto Metropolitan Curse Technical College. Kasumi is a hard-working, restrained, and considerate pacifist. She is also a big fan of Satoru Gojo.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156848-Rf0tuoQCNyZV.png', '4月4日', NULL, '赤﨑千夏', NULL, 156848, 'SUPPORTING', 3026) ON CONFLICT DO NOTHING;
