INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016241', 'AN1660', '天内理子', 'Riko Amanai is a student at Renchoku Girls'' Junior High and the designated Star Plasma Vessel for Master Tengen''s merger in 2006.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203015-ez2Io1gxIQOP.jpg', NULL, NULL, '永瀬アンナ', NULL, 203015, 'SUPPORTING', 340) ON CONFLICT DO NOTHING;
