INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016246', 'AN1660', '枷場美々子', 'Mimiko Hasaba is a character in Jujutsu Kaisen and Jujutsu Kaisen 0: Jujutsu High. She is an ally of Suguru Geto.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228986-TXJuABOhrxRA.jpg', NULL, NULL, '松田利冴', NULL, 228986, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016247', 'AN1660', '与幸吉', 'Koukichi Muta is a Semi-Grade 1 sorcerer and a second-year student at Kyoto Jujutsu High. He attends school by controlling the cursed corpse Ultimate Mechamaru, as Muta was born with a sickly and fragile body due to a Heavenly Restriction. In exchange, he has a nearly boundless amount of cursed energy that spreads over a vast range.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210154-nIn9DX39GFKP.jpg', '10月4日', NULL, '松岡禎丞', NULL, 210154, 'SUPPORTING', 475) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016248', 'AN1660', '猪野琢真', 'Species: Human Occupation: Sorcerer Affiliation: Jujutsu High Grade: Grade 2 Sorcerer  Takuma Ino is a grade 2 jujutsu sorcerer and a close associate of Kento Nanami who operates out of Tokyo Jujutsu High.  Takuma Ino is a genuine and cheerful person with a more positive outlook on things than most jujutsu sorcerers. He doesn''t believe he''s the smartest person around and has a lot of respect for Nanami. Whenever Ino finds himself in a tough situation, he asks himself what would Nanami do.', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157865-X9ENX9OzWevS.jpg', NULL, NULL, '林勇', NULL, 157865, 'SUPPORTING', 275) ON CONFLICT DO NOTHING;
