INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016251', 'AN1660', '花御 ', 'Species: Cursed Spirit  Hanami is an antagonist intent on ridding the Earth of Humans and reviving Sukuna.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172743-4Y5SXqED6A3G.jpg', NULL, NULL, '田中敦子', NULL, 172743, 'SUPPORTING', 211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016252', 'AN1660', '漏瑚', 'Grade: Special Grade Cursed Spirit  Jogou is an unregistered special grade cursed spirit aligned with Mahito, Hanami, and Dagon. He was born of humanity''s fear and negative association with volcanoes and other fire-related natural disasters. This resulted in a highly intelligent cursed spirit with massive levels of cursed energy even for a special grade. Jogou believes curses are the true humans and desires a world where his kind dominates the earth.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156991-niYjdp9CxO4w.png', NULL, NULL, '千葉繁', NULL, 156991, 'SUPPORTING', 355) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016253', 'AN1660', 'バッタの呪い', 'Grade 2 Cursed Spirit born from humanity''s hatred of the grasshopper plague.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b306261-Ms5bd10bi0Ug.png', NULL, NULL, 'かぬか光明', NULL, 306261, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
