INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016259', 'AN1660', '狗巻棘', 'Species: Human Occupation: Sorcerer, Student Affiliation: Jujutsu High Grade: Grade 2 Sorcerer Cursed Technique: Cursed Speech  He is a second-year at Tokyo Metropolitan Jujutsu Technical High School. Due to his curse ability, he is only willing to communicate with ingredients used to make rice balls.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157115-kdhRYQdVhH95.png', '10月23日', NULL, '内山昂輝', NULL, 157115, 'SUPPORTING', 10534) ON CONFLICT DO NOTHING;
