INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016263', 'AN1660', '虎杖倭助', 'Yuji''s Grandfather is shown to be a selfless, caring man who taught Yuji to help others. He was also short tempered and stubborn, to the point he would yell at Yuji for visiting him every day and buying him flowers. This temper meant that nobody else wanted to visit him and he tells his grandson to avoid dying alone.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194074-SnbrUkHIyM62.png', NULL, NULL, '千葉繁', NULL, 194074, 'SUPPORTING', 88) ON CONFLICT DO NOTHING;
