INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016272', 'AN1661', 'サラ', 'Sara was born in Asura in the Milbotts Region ruled by the Notos Greyrat Family. Her father was a hunter from whom she learned how to use the bow. Now a prodigy for her talent with the bow, she is an A-ranked adventurer and member of the party Counter Arrow.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206604-kMvs5P9cXJLK.png', NULL, NULL, '白石晴香', NULL, 206604, 'SUPPORTING', 2638) ON CONFLICT DO NOTHING;
