INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016276', 'AN1661', 'ゾルダート・ヘッケラー', 'Soldat Heckler is an S-ranked adventurer and the leader of the S-ranked party Stepped Leader. He is a skilled swordsman with advanced-ranked Sword God Style and intermediate-ranked Water God Style.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245377-4ahGPt8W6LIs.jpg', NULL, NULL, '鳥海浩輔', NULL, 245377, 'SUPPORTING', 166) ON CONFLICT DO NOTHING;
