INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016279', 'AN1661', 'ジーナス・ハルファス', 'Vice Principal of the Ranoa Magic Academy, also known as the Ranoa University of Magic. He was formerly a teacher at the University, and taught Roxy during her time as a student. After hearing of Rudeus''s achievements as an adventurer, Jenius sends him a letter inviting him to study as a special student in Ranoa.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b311809-EL0gvAhNykgx.png', NULL, NULL, '青山穣', NULL, 311809, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
