INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016282', 'AN1661', 'ゴリアーデ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b311810-Wof3SlDvQyN0.png', NULL, NULL, '斉藤貴美子', NULL, 311810, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016283', 'AN1662', '三日月閑', 'Shizuka Mikazuki is a very rational girl who prefers to act alone. Her actions are determined by the benefits and risk of said situation. This is the main reason why she didn''t join up with Akira and Kenichirou at first. Her personality is because of her upbringing. Her father was a successful business man. He was very strict and wanted her to be perfect, to succeed.', 26, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214582-k5Bcd0DB59ik.jpg', NULL, NULL, '楠木ともり', NULL, 214582, 'MAIN', 1515) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016284', 'AN1662', '天道輝', 'Akira Tendou is a former employee of a company that earned the nickname Black Company (exploitative employment system). This job made Akira so miserable that he was excited that there was a zombie apocalypse because he didn''t have to go to work.', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214584-4zsaqbOP55bf.png', NULL, NULL, '梅田修一朗', NULL, 214584, 'MAIN', 1025) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016285', 'AN1662', 'ベアトリクス・アメルハウザー', 'She came all the way to Japan from Germany because she loves Japanese culture. She saved up money to visit but the apocalypse had already started once she arrived at the airport.', 21, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214581-lk2deJ8pNsae.png', NULL, NULL, '髙橋ミナミ', NULL, 214581, 'MAIN', 684) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016286', 'AN1662', '竜崎憲一郎', 'An old friend of Akira Tendou from college and the rugby team. He hasn''t seen him in a year before the apocalypse. After he graduated from college he became a salesmen at a major real estate company because of his great communication skills. In reality he seems almost perfect but he too was miserable at his job and wanted to become a comedian.', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214583-akJm3W589tEd.png', NULL, NULL, '古川慎', NULL, 214583, 'MAIN', 518) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016287', 'AN1662', '日暮莞太', 'He is a former NEET and the leader of his group, consisting of people he found during the apocalypse''s first days.', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214586-UHkFPhvnrdid.png', NULL, NULL, '岡本信彦', NULL, 214586, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
