INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016307', 'AN1662', '蔵杉重信', 'He is a former cellphone shop worker that was a part of Kanta Higurashi''s group.', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214591-73lXnNW8v5aH.png', NULL, NULL, '荻野晴朗', NULL, 214591, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016308', 'AN1663', '堀京子', 'Kyouko Hori is one of the main protagonists of Horimiya, along with Izumi Miyamura. She is a student in Class 3-1 of Katagiri Senior High School. Kyouko is mostly a very energetic and popular person who always creates a happy atmosphere around herself. She is a hard-worker in all aspects of her life, and, according to Izumi Miyamura, she scores above 90% for all her tests.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66171-o2vk3689wWFK.png', '3月25日', NULL, '戸松遥', 163, 66171, 'MAIN', 12323) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016309', 'AN1663', '宮村伊澄', 'Miyamura is often mistaken for an otaku for his sneaky character. The truth behind his long hair and clothes is to hide his piercings and his excessive amount of tattoos. This is a secret that only Hori and Ishikawa know.  Izumi is a very thoughtful kid. He is a person who looks weak but is very strong.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66173-g8eU1LGWPB8O.png', '4月17日', NULL, '内山昂輝', 169, 66173, 'MAIN', 15711) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016310', 'AN1663', '井浦基子', 'She is Shuu Iura''s younger sister.  Self-described as an untalkative, gloomy type, Motoko is the opposite of Shuu. She tends to keep to herself and has a hard time making friends. However, unlike Shuu, this personality also carries over to her school life, though she is much more forceful and violent towards her brother than others. She is also pretty smart but lacks the confidence to use it too well.', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72467-PpdDmPQFbaMC.png', '5月14日', NULL, '金元寿子', 150, 72467, 'SUPPORTING', 145) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016311', 'AN1663', '安田真', 'Occupation: English Teacher Affiliation: Student Council (Manager), Katagiri Senior High School  He is one of the supporting characters for Horimiya. Yasuda loves high school girls and makes no attempt to hide this either. However, he never actually touches any of the girls, just acts overly friendly towards them and overly cold towards the guys. He often demands that any guys with girlfriends (mainly Miyamura and Sengoku) break up with them, so that he can have them instead. Any time he is with', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66975-1ENOxQZ7SJPm.png', NULL, NULL, '津田健次郎', NULL, 66975, 'SUPPORTING', 124) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016312', 'AN1663', '沢田ほのか', 'Sawada is a very clingy towards Kyouko Hori. Due to her attachment to Hori, she often gets angry when Hori is together with Izumi Miyamura, choosing to push him away. She views Miyamura as a love rival, but also as a brotherly figure. She was very close to her older brother who passed away some years ago. She also appears to have mild androphobia, often freezing up, running away, or hiding when approached by men. However, ever since she got to know Miyamura, she would hide behind him instead whe', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72459-NbyXnBAjLxKT.png', '12月31日', NULL, '麻倉もも', 150, 72459, 'SUPPORTING', 757) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016313', 'AN1663', '寺島玲子', 'She is a chemistry teacher at Katagiri High School and the homeroom teacher of class 3-1.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66973-cRamsBQtjWmG.png', NULL, NULL, '佐藤はな', NULL, 66973, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
