INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016318', 'AN1663', '仙石翔', 'He is the charismatic president of the student council of Katagiri Senior High School who is enrolled in class 3-3, the childhood friend of Kyouko Hori and the boyfriend of Remi Ayasaki.  Sengoku is a rather shy boy who gets embarrassed easily and he is a very wimpy where the slightest thing will make him cower in fear, especially things to do with horror or insects. Sengoku is very smart and serious, normally ranked #1 in the school (and #2 in phys ed). He enjoys reading and has an incredible l', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72447-SH9Hth8ZGJam.png', '5月9日', NULL, '岡本信彦', 170, 72447, 'SUPPORTING', 751) ON CONFLICT DO NOTHING;
