INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016320', 'AN1663', '井浦秀', 'He is a friend of Izumi Miyamura and pretty much everyone at school. He has his own way of thinking and always seems excited; he is a colleague from another class.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66967-driczOA04cxe.png', '2月7日', NULL, '山下大輝', 172, 66967, 'SUPPORTING', 984) ON CONFLICT DO NOTHING;
