INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016326', 'AN1663', '綾崎レミ', 'A member of the Student Council and she is known as the girlfriend of Kakeru Sengoku who attends Katagiri Senior High School where she is enrolled in class 3-5. She is more of a mascot in the student council, and is shown to do little to no work at all.   Remi is usually shown as a rather childish and immature girl who has a very straightforward personality, and often wears her emotions on her sleeve. And seems to rely on other people''s help. She''s also not very smart, often compared to Miyamura', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66965-Kfqui6IitXaL.png', '6月6日', NULL, '市道真央', 158, 66965, 'SUPPORTING', 1694) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016327', 'AN1663', '堀創太', 'Kyouko''s young brother.  He sees Kyouko as a motherly figure because she has been the one taking care of him since he was born because of the nature of their parents'' work.  In the beginning of the story, he is brought back to the Hori household by Izumi after he had fallen down on the street. Since then he has been very affectionate towards Izumi, going as far as calling him a non blood-related brother.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66969-w9HNa7igeTeF.png', '10月18日', NULL, '寺崎裕香', NULL, 66969, 'SUPPORTING', 565) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016328', 'AN1663', '柳明音', 'He is a 3rd year at Katagiri High School​ and a member of Hori and Miyamura''s regular group of friends. He is enrolled in class 3-6. He has very bad eyesight and cannot see properly without his glasses.', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72453-f9gRbQBUjKo6.png', '12月28日', NULL, '福山潤', 168, 72453, 'SUPPORTING', 1163) ON CONFLICT DO NOTHING;
