INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016336', 'AN1664', '斉森香耶', 'Kaya  is the daughter of Shinichi Saimori and Kanoko Saimori and the younger half-sister of Miyo Saimori who is currently engaged to Kouji Tatsuishi.  Kaya is very spoiled, entitled, and emotionally and mentally abusive towards her half-sister. She is also rather two-faced. Despite her polite public appearance, she is rather disrespectful and nasty in her actions when she believes she can get away with it, not only to Miyo but also to her boyfriend Kouji.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269669-UGIiBu246hCL.png', '4月19日', NULL, '佐倉綾音', NULL, 269669, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
