INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016341', 'AN1665', '六車拳西', 'Affiliation:  Profession:   Position:    Kensei is portrayed as a serious character, often angry at the others for their immaturity. A skilled and respected battlefield commander, he has a rather brutal fighting style quite often blasting his opponents apart. When outside of battle he has a blunt and slightly aggressive attitude, trying to cheer up a tearful Hisagi in a manner reminiscent of an army drill sergeant, though he seems more passive as a Vizard. He is most frequently irritated by his ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2344-ZvQAiyfpcERl.png', '7月30日', NULL, '杉田智和', 179, 2344, 'SUPPORTING', 169) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016342', 'AN1665', 'ベー・ゲー・ノイン', 'BG9 is a Quincy and a member of the Vandenreich''s Stern Ritter with the designation "K".  BG9 is a tall individual who has a mask which covers his entire face and extends behind his head. At its front, the mask has a peak at the centre and slits on both sides of this.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b87083-4RvUZ2MOdyIG.png', NULL, NULL, '田中秀幸', NULL, 87083, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016343', 'AN1665', 'チルッチ・サンダーウィッチ', 'Cirucci Thunderwitch dresses akin to the gothic lolita style of Japanese fashion. Her outfit consists of a frilly dress, large poofy sleeves that cut off at her shoulder, short purple-colored hair, teardrop markings on each cheek, and knee-high boots. Cirucci has wings on her back, but it is unclear if they are part of her outfit or something else. The remains of her hollow mask are positioned in her hair right above the left side of her forehead and resemble a spiked hairpin. Despite her rather', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b7429-6bwRITWlAsnJ.png', '2月27日', NULL, '桑島法子', NULL, 7429, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016344', 'AN1665', '大前田希代', 'Sister of Marechiyo Oomaeda', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306553-e2C7uEQPQ9ob.png', NULL, NULL, '藤田咲', NULL, 306553, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016345', 'AN1665', '狛村左陣', 'Occupation: Captain of the 7th Division Theme Song: "Don''t Turn Away" by White Wolf   Captain of the 7th Division  Komamura is the largest normal character in Bleach, being 57 cm taller (288 cm) than his subordinate Jirōbō (the runner-up) and even more physically imposing. The only larger human characters are the Seireitei gatekeepers, who are each roughly thirty feet tall. He is also quite unusual in that he is an anthropomorphic canine; the specific animal is unclear, as he has characteristics', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b4298-nuazBlSaHL7y.png', '8月23日', NULL, '稲田徹', 288, 4298, 'SUPPORTING', 221) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016346', 'AN1665', '松本乱菊', 'Zanpakutou: Haineko   Rangiku Matsumoto is the lieutenant of the 10th Division of the Gotei 13, serving under Captain Toushirou Hitsugaya.  Rangiku tends to be a slacker who doesn''t like paperwork and loves to drink sake. Her easy-going and free-spirited personality is in sharp contrast with the serious Hitsugaya, but the two seem to be quite close, regardless. Rangiku is almost constantly by his side and has shown her loyalty to him on several occasions. While she seems somewhat self-centered, ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b904-bdfi2xqHicCj.png', '9月29日', NULL, '松谷彼哉', 172, 904, 'SUPPORTING', 1732) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016347', 'AN1665', '二枚屋王悦', 'Ouetsu is a member of the Royal Guard.  He''s a quite lively and energetic individual, being prone to grandiose entrances and greetings. He has a tendency of going overboard, as he portrays a certain image as to take away from the fact that he lives in a humble state.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b75654-toLRJqeG6L8p.png', '8月18日', NULL, '上田燿司', NULL, 75654, 'SUPPORTING', 196) ON CONFLICT DO NOTHING;
