INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016350', 'AN1665', '鳳橋楼十郎', 'Rojuro Otoribashi, commonly referred to as Rose (ローズ, Rōzu?), is the former captain of the 3rd Division. He became captain approximately one year before Kisuke Urahara. He is an effeminate man with long, wavy, blond hair and a frilly shirt. He seems to be interested in music, as he speaks to Love about an artist&#039;s new single and has been seen playing or tuning a guitar on several occasions. Rose appears to be one of the calmer and perhaps wiser ones amongst the group, though he becomes irri', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2341-9TX1HBmLggia.png', '3月17日', NULL, '樫井笙人', NULL, 2341, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016351', 'AN1665', '草鹿八千流', 'Race: Shinigami Rank: Lieutenant of the 11th Division Relatives: Kenpachi Zaraki (adoptive father)  Yachiru is the shortest member of the Gotei 13. She became a shinigami without having taken the standard exams. She is the current Vice-Captain of the 11th division but her strength and powers thus far are unknown. She is also the president of the Shinigami''s Women Society.   She first met Kenpachi as a baby after he had just killed a group of people. She instantly became drawn to him as she later', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b910-cAC9g4i208Ou.png', '2月12日', NULL, '望月久代', 109, 910, 'SUPPORTING', 784) ON CONFLICT DO NOTHING;
