INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016356', 'AN1665', 'ルピ·アンテノール', 'Luppi temporarily replaces Grimmjow Jeagerjaques as the 6th Espada when Grimmjow is demoted by the loss of his arm. Luppi is a youthful Espada with short black hair and a rather feminine face. The remains of his hollow mask (a top row of teeth) rests on the left side of his head, looking like a hair comb or barette. Luppi&#039;s attire consists of long sleeves that fall past his hands, hiding them. The location of his hollow hole is hidden from view, but his Espada tattoo is prominently displaye', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1152-fBXUCtSJNi9P.png', '6月5日', NULL, '岸尾だいすけ', 161, 1152, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016357', 'AN1665', '有昭田鉢玄', 'Hachigen Ushōda is the physically largest vizard. He was formerly the lieutenant of the Kido Corps under Tessai Tsukabishi. He wears a tuxedo and has a black crossbone design in his pink hair. He is usually referred to as Hachi (ハッチ, sometimes translated as ''Hutch''), but his actual name is Hachigen. He seems to be a binding spells expert, since he is always tasked with making barriers and such for the vizard''s use. By his own admission, his powers are very similar to those of Orihime Inoue''s. De', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/2345.jpg', NULL, NULL, '長嶝高士', NULL, 2345, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016358', 'AN1665', '麒麟寺天示郎', 'Kirinji Tenjiirou is a member of Royal Guard and Unohana Retsu''s master.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b75068-Laov9XsW86Tv.png', '5月31日', NULL, '志村知幸', NULL, 75068, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016359', 'AN1665', 'エス・ノト', 'Äs Nödt is a Quincy and a member of the Vandenreich''s Stern Ritter with the designation "F".   Appearance: Äs has long, dark hair and dark eyes with visibly light pupils. Its attire is a variation of the Stern Ritter''s typical white uniform, consisting of the order''s signature hooded cloak and a knee-length trench coat, as well as black boots. Äs also wears a dark mask that obscures the lower half of its face and features five spikes running down its center.   Plot  _The Thousand-Year Blood War ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b64663-jwXgeNNZgRgQ.jpg', '12月29日', NULL, '松岡禎丞', NULL, 64663, 'SUPPORTING', 223) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016360', 'AN1665', 'シャルロッテ・クールホーン', 'Charlotte Chuhlhourne is a large, bulky and muscular Arrancar that dresses very feminine. His mannerisms and dress style border on those of a stereotypical drag queen. He has long wavy purple hair, large glowing lips, icy blue eyes, and curly long eyelashes. His hollow mask is a small tiara with horns. His Arrancar outfit is customised with feminine motifs.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/21634.jpg', NULL, NULL, '三宅健太', NULL, 21634, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016361', 'AN1665', 'ロバート・アキュトロン', 'Robert Accutrone is a Quincy and a member of the Wandenreich''s Sternritter with the designation "N".', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b284513-eLtojz66DHJn.png', NULL, NULL, '土師孝也', NULL, 284513, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016362', 'AN1665', '曳舟桐生', 'Kirio Hikifune is a former captain of the 12th Division and a member of the Royal Guard.  During her time as the captain of the 12th Division, her lieutenant, Hiyori Sarugaki, became very attached and came to love Kirio as much as she would her own mother. However, approximately 110 years ago, Kirio left the Gotei 13 to take up a position within the Royal Guard. She was soon succeeded by Kisuke Urahara, but failed to attend his inauguration ceremony.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b74357-C51Ta83pXtDK.png', '12月16日', NULL, '恒松あゆみ', NULL, 74357, 'SUPPORTING', 77) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016363', 'AN1665', '射場鉄左衛門', 'Iba has a distinctive hair cut and wears black sunglasses with his standard Shinigami uniform. He collects sunglasses, his main source being &quot;Silver Dragonfly Glasses Store&quot;, the same shop where fellow lieutenant Renji Abarai purchases his goggles. He also smokes and carries his Zanpakutō as a small blade inside his uniform. He has a large tattoo on his back consisting of a cat on fire and the kanji shōfuku (inviting luck). These features, plus his informal style of speech, are all str', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/18461.jpg', NULL, NULL, '西凜太朗', NULL, 18461, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016364', 'AN1665', '蒼都', 'Cang Du is a Quincy and a member of the Vandenreich''s Stern Ritter with the designation "I".', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b87079-MQKrzWOeQg8U.png', '5月27日', NULL, '倉富亮', NULL, 87079, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016365', 'AN1665', 'キャンディス・キャットニップ', 'Candice Catnipp is a Quincy and a member of the Wandenreich''s Sternritter with the designation "T" - The Thunderbolt. Part of the Bambies. Engaged in fight with both Ichigo and Byakuya, lost on both occasions.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189753-Shlnpav1hn3z.jpg', '6月7日', NULL, '内山夕実', NULL, 189753, 'SUPPORTING', 174) ON CONFLICT DO NOTHING;
