INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016368', 'AN1665', '氷輪丸', 'Master: Toushirou Hitsugaya  Hyourinmaru is the manifested spirit of Toushirou Hitsugaya''s Zanpakutou that is seen during the Zanpakutou Unknown Tales arc. At any time, Hyourinmaru can take the form of a gigantic, icy blue, serpentine dragon with large wings and an echoing voice.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/25881.jpg', NULL, NULL, '松岡大介', NULL, 25881, 'SUPPORTING', 74) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016369', 'AN1666', '三重あい', 'An absentminded and innocent middle-school girl who sits next to Komura-kun. She has poor eyesight and must wear glasses, but she tends to forget them quite often.  Whenever Mie forgets her glasses her depth perception in particular suffers and thus she tends to lean in close to Komura-kun.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129904-TThqlHWM3gM7.png', '11月29日', NULL, '若山詩音', NULL, 129904, 'MAIN', 756) ON CONFLICT DO NOTHING;
