INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016386', 'AN1667', '芦田圭', 'A tomboyish girl and Aika Natsukawa''s best friend, also a member of the Kōetsu High Volleyball Club. She''s often seen wearing hoodies during High School.  She has a cheerful personality and secretly supports the relationship that has been going between Aika and Wataru. Although Wataru didn''t seems to notice this, it has been proven by her actions. She is a typical best friend who always watching Aika and comforts her whenever she faced undesired circumstances.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292108-1P2fmgLbF7ZD.jpg', NULL, NULL, '花守ゆみり', NULL, 292108, 'SUPPORTING', 114) ON CONFLICT DO NOTHING;
