INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016407', 'AN1668', '安達垣愛姫', 'Aki comes from a well off family and is known for her brutal treatment of men. As a result, she has gained the nickname "Cruel Princess" from her classmates. She allegedly rejected Masamune-kun and gave him the nickname "Piggy" when the two were children leading to his transformation and commitment to revenge.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b76364-ATlG8j4fx3vg.png', '12月24日', 'AB', '大橋彩香', 162, 76364, 'MAIN', 2364) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016408', 'AN1668', '小岩井吉乃', 'Yoshino is Aki''s maid and follower. She seems to be a clumsy girl. However, beneath her clumsy and shy appearance she is actually extremely deceptive and cold, able to deceive and hurt Aki without a second thought. Unlike Aki, Yoshino easily gained weight from sweets.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121008-fCtwkTJ2v2bj.png', '11月22日', 'AB', '水瀬いのり', NULL, 121008, 'MAIN', 817) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016409', 'AN1668', '真壁政宗', 'A narcissistic boy who is obsessed with the idea of getting revenge. His feelings of revenge are aimed towards the popular rich girl, Adagaki Aki. Despite his handsome appearance now, he was once a chubby kid who people liked to make fun of.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b81967-vfprXRXeNdgq.png', '1月7日', 'A', '花江夏樹', 178, 81967, 'MAIN', 824) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016410', 'AN1668', '藤ノ宮寧子', 'Neko Fujinomiya is a cute and cheerful rich girl who transferred school after Masamune Makabe "gave her his coat on Christmas Eve" and fell in love with him. She has a frail body, needing to consume many drugs although she often makes jokes about it. Due to her habit of not wearing any panties, Aki and Yoshino nicknamed her "Pantie-less Woman".', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121013-BokQwnshmO6O.png', '6月16日', NULL, '三森すずこ', 159, 121013, 'MAIN', 460) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016411', 'AN1668', '雅宗兼次', 'Gender:', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155826-7TOhsCeJaovR.png', '7月1日', NULL, '斎賀みつき', NULL, 155826, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016412', 'AN1668', 'ミュリ・エルベッソン', 'Muriel Besson is a young French student with a keen interest in the Japanese culture. Her brother, Frank Besson, is the boss of a Milieu, who spoils her very much.  During Masamune''s trip to France, she uses him as her model of her hero, and Aki as the heroine.    Muriel has medium length blonde hair that is usually tied up, and blue eyes. Her right eye is usually covered with a black eye patch, with a white rose symbol on the patch. She has a black tattoo on the upper left side of her back.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155676-cBFFMEQnMlg3.png', NULL, NULL, '伊藤美来', NULL, 155676, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016413', 'AN1668', 'フランク・ベッソン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292799-XsgWJVkEZHff.png', NULL, NULL, '加瀬康之', NULL, 292799, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016414', 'AN1668', '金子 園香', 'Kaneko Sonoka is one of the girls who have self-proclaimed themselves as Aki Adagaki''s bodyguards and the Vice President of Yasaka High School Student Council.  Kaneko is a cute and fairly short girl. She has dirty-blonde hair that has two pink ribbons tying up two straps of her hair into ring-shaped like while the rest of her hair reaches her chest and pink eyes. She wears the Yasaka High School uniform which consists of a pink shirt, black vest with the school symbol on it, a striped yellow sk', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121010-tbOk03LzlQli.png', NULL, NULL, '伊瀬茉莉也', NULL, 121010, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016415', 'AN1668', '双葉妙', 'Masamune''s class rep. She loves Yaoi and likes pairing Masamune to Kojuurou.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121007-QOnQXBsJAtVe.png', '5月10日', NULL, '田所あずさ', NULL, 121007, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
