INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016419', 'AN1668', '早瀬絹江', 'Occupation: Housewife  She has light brown hair that curls at the tips and brown eyes. She wears a headband that has a dog footprint on and she usually is seen wearing an apron. She is very short, has a small body, and can be easily mistaken for a child, even though she is 42 years old. She is also the mother of Makabe Masamune.', 42, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121014-BJWpcwKHRVXH.jpg', '6月27日', NULL, '小倉唯', 138, 121014, 'SUPPORTING', 93) ON CONFLICT DO NOTHING;
