INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016439', 'AN1670', '芥川龍之介', 'Likes: Curios and antiques, tea, figs Dislikes: Bonsai trees, dogs, baths  "The weak will die. Die, and make way for others." A member of the notorious "Port Mafia" that operates by the harbor. Akutagawa has a black and white "survival of the fittest" view of the world, claiming that weak people should die and give way to the stronger ones. His ability is called "Rashōmon" (羅生門).  He is not afraid of pain and defeat, if only to hear a word from a "certain person". His ruthless, vicious nature ma', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89199-h8tHKG8vKPNZ.png', '3月1日', 'A', '小野賢章', 172, 89199, 'MAIN', 5522) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016440', 'AN1670', '田山花袋', 'Ability: Futon  He is an information broker for the Armed Detective Company. He used to be a member of the Agency, and has known Kunikida for ten years.', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138064-qAibIo94XlfQ.png', '1月22日', 'B', '鈴村健一', 175, 138064, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
