INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016442', 'AN1670', '幸田文', 'She is a civilian who assists Kunikida with a case.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138148-XY9f85n8qzYX.png', NULL, NULL, '寿美菜子', NULL, 138148, 'SUPPORTING', 70) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016443', 'AN1671', '一ノ瀬ちづる', 'Chizuru Ichinose, alternatively known as Chizuru Mizuhara in her "rental girlfriend" persona, is a college student at Nerima University who is majoring in Literature and she currently lives in Room 204 of Royal Hills Nerima, just next to Kazuya Kinoshita.', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128106-zSTsuULvz6PX.png', '4月19日', NULL, '雨宮天', 162, 128106, 'MAIN', 7284) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016444', 'AN1671', '木ノ下和也', 'A struggling university student living in Tokyo. He studies at Nerima University. Kazuya possesses a wishy-washy nature and is susceptible to yielding to his selfish desires. His lies often get him into trouble, because he cannot muster the strength to tell the truth. On the other hand, possessing a straightforward kindness that cares for those around him. He has also developed feelings for Chizuru.', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128105-gad6JuGEXPWe.png', '6月1日', NULL, '堀江瞬', 177, 128105, 'MAIN', 777) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016445', 'AN1671', '更科瑠夏', 'Ruka Sarashina suffers from arrhythmia and seeks a lover that will help her cope with her condition. She''s seen as being a very pushy and possessive kind of person. This personality of hers developed after learning of her condition and being alienated from her peers. Because of this, she became very fixated on the idea that getting a boyfriend would help her in having a faster heartbeat.  Along with her rather brash personality, she doesn''t like giving up easily; often making poor decisions to g', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b147005-5vLFz3lTsssh.png', '8月26日', NULL, '東山奈央', 158, 147005, 'SUPPORTING', 3455) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016446', 'AN1671', '一ノ瀬小百合', 'She is Mizuhara''s grandmother.', 77, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283247-GJxhmUgL6yz0.jpg', NULL, NULL, '定岡小百合', NULL, 283247, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
