INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016448', 'AN1671', '桜沢墨', 'Sumi is a college student who works as a rental girlfriend for the Diamond app. She''s extremely shy which initially made the job quite difficult for her, but she started to improve after spending time with Kazuya.', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b144665-aPda7bPvOoYl.png', '3月20日', 'O', '高橋李依', 156, 144665, 'SUPPORTING', 4030) ON CONFLICT DO NOTHING;
