INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016450', 'AN1671', '七海麻美', 'She is a freshman at Nerima University and the ex-girlfriend of Kazuya Kinoshita.', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154224-7dJ09BKEnG3v.png', '11月13日', NULL, '悠木碧', 158, 154224, 'SUPPORTING', 9818) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016451', 'AN1671', '八重森みに', 'A streamer otaku who moved to the flat next to Kazuya and happens to go to the same college as him. Calls Kazuya "Master."', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153703-KOLZ2Oz2sFDo.png', '4月8日', NULL, '芹澤優', NULL, 153703, 'SUPPORTING', 708) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016452', 'AN1671', '木部芳秋', 'Kazuya''s childhood friend from elementary school. He often cares for Kazuya.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172022-MGBDREu4JrGy.png', NULL, NULL, NULL, NULL, 172022, 'SUPPORTING', 185) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016453', 'AN1671', '栗林駿', 'Kazuya''s friend.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172023-YiilpQjx1Nmv.png', NULL, NULL, NULL, NULL, 172023, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016454', 'AN1672', 'ガイ＝グリーンウッド', 'A friend of Oliver''s and a member of the Sword Roses. Guy is cheerful and friendly, with a frank and pleasant personality and great thoughtfulness and concern towards his friends. He''s unusually talented with the use of magical flora.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258621-oIutyrwFVmXa.png', NULL, NULL, '菅原慎介', NULL, 258621, 'MAIN', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016455', 'AN1672', 'ピート＝レストン', 'A friend of Oliver''s and a member of the Sword Roses. Pete is a mage born into a nonmagical family that enters Kimberly after scoring well on their difficult entrance exam. he forms a strong bond with the Sword Roses, who support him in his learning about the magical world and becoming stronger in it.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258623-gI9v05L3tPu6.png', NULL, NULL, '杉山里穂', NULL, 258623, 'MAIN', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016456', 'AN1672', 'オリバー＝ホーン', 'Oliver attends Kimberly Magic Academy to better refine his vast skills. Upon arriving, he meets the likes of Nanao, Chela, Katie, Guy, and Pete, their tight-knit bond eventually leading to the formation of the Sword Roses alliance.  Oliver is a gentle, rational, thoughtful and caring boy. Although less outwardly emotional than others, he’s intelligent, brave and cares for his friends. Oliver generally takes every situation calmly but can quickly lose his temper when someone he''s close to is harm', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258618-iTwFOz7qOgMU.png', NULL, NULL, '田丸篤志', NULL, 258618, 'MAIN', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016457', 'AN1672', 'ナナオ＝ヒビヤ', 'Hailing from Tourikueisen in the distant country of Yamatsukuni, Nanao is a samurai girl who was offered a second chance at life by Theodore McFarlane. She attends Kimberly at his behest and finds a new purpose in life in crossing blades with Oliver Horn. She is a noble and cheerful person who holds honor in high regards, and a good fight even moreso.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258620-yRpaTYp6c90n.png', NULL, NULL, '貫井柚佳', NULL, 258620, 'MAIN', 238) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016458', 'AN1672', 'カティ＝アールト', 'A friend of Oliver''s and a member of the Sword Roses. Katie has very strong ideals compared to the typical mage, desiring to reform magical society''s treatment of demi-humans. She appears to have a crush on Oliver and in contrast often finds herself at odds with Guy, although they remain close friends and seem to have a slight cooking rivalry amongst themselves.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258626-aKx9jxAlBWrj.png', NULL, NULL, '大和田仁美', NULL, 258626, 'MAIN', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016459', 'AN1672', 'ミシェーラ＝マクファーレン', 'A friend of Oliver''s and a member of the Sword Roses. Chela is a proud young lady and the eldest daughter of the noble house of McFarlane, one of the five oldest families in Yelgland, and among the elite in the Magical World. She is an incredibly skilled mage, and often serves as the Sword Roses'' voice of reason alongside Oliver as the two most mature members of the group.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258624-PNn32Qio7xhX.png', NULL, NULL, '山田美鈴', NULL, 258624, 'MAIN', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016460', 'AN1672', 'リチャード＝アンドリューズ', 'A student at Kimberly Magic Academy and a classmate of the Sword Roses. He is the heir to the Andrews noble family. Initially seeing Oliver as a rival after misunderstandings that antagonized the two, he later duels him in a proper rematch and begins to see him as a friend.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304173-Oi8GfxQIylpD.png', NULL, NULL, '千葉翔也', NULL, 304173, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016461', 'AN1672', 'トゥリオ=ロッシ', 'A student at Kimberly Magic Academy and a classmate of the Sword Roses. Ytallian by birth, Rossi taught himself the sword by ignoring the fundamentals out of dislike for the three standard Sword Arts styles. He has sharp instincts and his combat style is based around dirty play.  His lack of fundamentals caused him to lose to Oliver, who had practiced the fundamentals to the point of pain, in a duel. He has since pursued the study of both the Koutz Style and magicombat to improve his skills.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258627-ztbOVHUJkjSI.png', NULL, NULL, '神原大地', NULL, 258627, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016462', 'AN1672', 'サイラス＝リヴァーモア', 'An upperclassman at Kimberly Magic Academy. Rivermoore is a necromancer who controls the bones of the dead, and is considered equally dangerous as Ophelia.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304174-c3qDgRv2sHlj.png', NULL, NULL, '伊丸岡篤', NULL, 304174, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016463', 'AN1672', 'カルロス＝ウィットロウ', 'An upperclassman at Kimberly Magic Academy. Carlos is an androgynous youth with a beautiful voice. They were assigned male at birth but was rendered Castrato—magically neutered—in order to be rendered immune to Ophelia Salvadori''s Perfume.  Alongside Ophelia they befriended Alvin Godfrey and co-founded the Kimberly Campus Watch with him, Tim Linton and Lesedi Ingwe. A falling-out with Ophelia later inspired Carlos to form a club to support students with gender and sex-linked magics like hers.', NULL, 'なし', 'https://s4.anilist.co/file/anilistcdn/character/large/b304175-w2XUScAyVMCR.png', NULL, NULL, '山本和臣', NULL, 304175, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016464', 'AN1672', 'アルヴィン＝ゴットフレイ', 'An upperclassman at Kimberly Magic Academy and the current Student Council President. Godfrey is kind and compassionate towards the younger students, protecting them from the more twisted attendants of the school.  Godfrey was born with abnormally high mana reserves for a non-noble mage and he has a strong affinity for fire magic, giving him his nickname "Purgatory". He boasts incredible firepower, strong enough even to injure the powerful instructors of the academy.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b267388-5rhL96yzJXE3.png', NULL, NULL, '日野聡', NULL, 267388, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016465', 'AN1672', 'エスメラルダ', 'Esmeralda is the headmistress of Kimberly Magic Academy. Her fame—and infamy—extends far beyond the Union’s borders. Due to mysterious circumstances, she is afflicted with strange, untreatable headaches.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258628-XWztPtTV9Kbq.png', NULL, NULL, '田中敦子', NULL, 258628, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016466', 'AN1672', 'テレサ＝カルステ', 'A student at Kimberly Magic Academy. She is in the year below the Sword Roses.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b267387-vw0NObxNGQLx.png', NULL, NULL, '真野あゆみ', NULL, 267387, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016467', 'AN1672', 'オフィーリア＝サルヴァドーリ', 'An upperclassman at Kimberly Magic Academy. Ophelia is a mysterious witch from a family of succubi who lives in the depths of the academy''s labyrinth. She was once a normal student who, after enduring distressing events, left the academy to perfect her magical arts in the labyrinth. She is on the verge of being consumed by the spell and creates chimeras to kidnap new students.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258625-LcJXhCQpSNEC.png', NULL, NULL, '茅野愛衣', NULL, 258625, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016468', 'AN1672', 'ダリウス＝グレンヴィル', 'Darius Grenville is the Alchemy Instructor of Kimberly Magic Academy. He is famous for stealing research results from the brighter students and presenting them as his own theories. Darius thinks very highly of himself. He looks down on his students and doesn''t hesitate to let them know that, often speaking very ill of those he dislikes.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258617-ogJWAuIuLryW.png', NULL, NULL, '東地宏樹', NULL, 258617, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016469', 'AN1672', 'ヴェラ＝ミリガン', 'A strange fourth-year student fascinated by demi-humans. Miligan is an excellent witch with great abilities and a few secrets. Despite her almost fanatical pursuit of her goals, she loves the younger students and enjoys teaching them. She takes an interest in Katie, taking her on as a research partner and apprentice.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258616-2893t10hheRp.png', NULL, NULL, '加隈亜衣', NULL, 258616, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016470', 'AN1672', 'エンリコ フェルギェーリ', 'The magical engineering instructor at Kimberly Magic Academy. Enrico is prone to designing outrageous lessons designed to maim students. His forte is making golems, and he believes the pursuit of sorcery and technology lies outside the bounds of morality. He was the teacher of Chloe Halford, and later, a Gnostic Hunter working alongside her.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b285393-j554GZMS4Umo.png', NULL, NULL, '大塚芳忠', NULL, 285393, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016471', 'AN1673', 'グゴイル', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '高橋伸也', NULL, 310554, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016472', 'AN1673', '宿屋の女将', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314435-CzdWRu2SvxTX.jpg', NULL, NULL, '寺依沙織', NULL, 314435, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016473', 'AN1674', '幻燈河螢多朗', 'Keitaro Gentoga is a young man with a spiritual constitution, the tutor of Yayoi Hozuki and the childhood friend of Eiko Hozuki. He can feel the presence of supernatural beings, and his presence attracts supernatural beings, even Yayoi who can see supernatural beings is often ignored. In order to not be easily possessed, Keitarou was taught by his grandmother to exercise and meditate regularly, because supernatural beings have difficulty possessing people with healthy bodies and minds, as a resu', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139462-VicTVjHmpHtA.jpg', NULL, NULL, '島﨑信長', NULL, 139462, 'MAIN', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016474', 'AN1674', '寶月詠子', 'Keitarou''s childhood friend and Yayoi''s cousin.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139463-dwhPQsBaAZw5.jpg', NULL, NULL, '花澤香菜', NULL, 139463, 'MAIN', 254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016475', 'AN1674', '寶月夜宵', 'Yayoi is the main protagonist of the Dark Gathering series. She is a young girl with a spiritual constitution who''s collecting dangerous ghost in order to get enough power to rescue her mother''s spirit from an evil ghost, the Spectre of Death.  She''s obsessed with the occult stemming from her desire for revenge on the Spectre of Death for taking her mother''s spirit. She will do almost anything to save her. That includes using any kinds of ghost, even if they are extremely evil.  Despite this obs', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139461-AxfBBZMZjwaH.jpg', NULL, NULL, '篠原侑', NULL, 139461, 'MAIN', 482) ON CONFLICT DO NOTHING;
