INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016483', 'AN1674', '神代愛依', 'High school freshman. One of the students Keitarou tutors. Frequently experiences malicious hauntings, and what was though initially thought to be linked to her late brother turns out to be bigger.   A malevolent god saw her when she was younger and claimed her as their bride, making a promise to marry her when she turns 20. As a result, many malicious spirits surround her, attracted by the god''s energy.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200412-p644sFkq5gvX.jpg', NULL, NULL, '川口莉奈', NULL, 200412, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
