INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016548', 'AN1677', '沖田総司', 'A genius swordsman of the Shinsengumi and master of the Tennen-rishin ryu sword style. Okita was the captain of Shinsengumi''s First Unit. In the OVA, he often fought together with Saito and was involved in the Ikedaya Affair in 1864. On one of his night encounters with Kenshin, he eagerly draws his sword and comments that Kenshin''s Hiten Mitsurugi-Ryuu gets better every time he sees it.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3402-FkurkUOz2KVN.jpg', NULL, NULL, '保志総一朗', NULL, 3402, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
