INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016553', 'AN1677', '鵜堂刃衛', 'Kurogasa, otherwise known as Udou Jin-e, was a hitokiri during the Revolution, and there is evidence he continued killing people well after the end of the Revolution. He attacked high-ranking Imperialist officials of the Meiji government (leading some to believe he fought for the Tokugawa shogunate during the war, since he did state that he was a member of the Shinsengumi, though his thirst for blood led him to killing members of his own squad), killing anyone who stood in his way. He appears as', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b18779-dp8wl4LJs4A2.png', NULL, NULL, '杉田智和', NULL, 18779, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016554', 'AN1677', '般若', 'Hannya is a pupil of Aoshi. The village he was born in was poor, so he was abandoned at birth to reduce the number of people to feed. Hannya survived, but he could not return to the village so he wandered around like an animal until Aoshi found him and gave him a position in the Oniwabanshuu. Hannya is the master of disguise within the group, an ability he gained by removing all his prominent facial features, which is why he wears the demonic mask on his face. As Aoshi gave him something to live', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b18930-QdwqMOu9z3Xc.png', NULL, NULL, '置鮎龍太郎', NULL, 18930, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016555', 'AN1677', '小国玄斎', 'The doctor and Kamiya Family''s family friend. He is the grandfather of Suzume and Ayame.   He took Megumi under his wing to train her as a full pledged doctor.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b42039-UHDAhdqnVa1R.jpg', NULL, NULL, '多田野曜平 ', NULL, 42039, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
