INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016569', 'AN1677', '石動雷十太', 'A warrior fighting against the pacification of Japan, Raijuta attempts to build an army of the most powerful bandits to rebel against the new Japanese government. He saves Yutaro, a child of a rich family, in order to acquire the resources to build his army.     Raijuta''s fighting style Shinko Ryu has the ability to create a long distance attack that travels through the air with the force of his Katana. This attack injures Yutaro''s arm to an extent the nerves are permanently damaged. Raijuta and', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b21008-gY9A3BYOlmLB.jpg', NULL, NULL, '三宅健太', NULL, 21008, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
