INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016574', 'AN1677', '塚山由太郎', 'Yutaro is a young boy that inherited a HUGE fortune from his parents. His parents had died when he was younger. He appears when Dr. Genzai''s sister (she looks just like his brother) is working for Yutaro.    Yutaro lived in a wealthy mansion on a hill, who was practically served and waited on everyday. He wanted to learn swordsmanship since his father was deemed as an excellent fighter. He sees Kenshin with a sword and demands lessons from him. But Kenshin refuses, and Yutaro flies off the handl', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b21007-exPxDakV23Uo.jpg', NULL, NULL, '三瓶由布子', NULL, 21007, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
