INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016584', 'AN1677', '赤末有人', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b45347-n6iRgqhfTyOO.jpg', NULL, NULL, '竹内良太', NULL, 45347, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016585', 'AN1678', 'エミリア・ユスティーナ', 'Emilia is the main female protagonist and the Hero who defeated the Demon King Satan. After forcing the Demon King to retreat from Ente Isla, she followed him to modern day Japan to ensure his destruction. However, just like the Demon Lord, she lost most of her powers upon her arrival and was forced to assume a Japanese name. She was also forced to find employment, and so became a call center agent. She is a half human and half angel.  Overall, Emi is a strong-willed and determined hero, display', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b70735-DmmbHRLKpS0E.png', '9月12日', NULL, '日笠陽子', NULL, 70735, 'MAIN', 1459) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016586', 'AN1678', 'サタン・ジャコブ', 'Satan Jacob is the main protagonist of the series. He was once the Demon King who declared war on Ente Isla in an attempt to annex the four continents. However, due to the actions of the Hero Emilia Justina and her companions, he was forced to retreat to Earth, causing him to lose almost all of his powers.  Satan was well-known throughout Ente Isla as the great overlord of his people, his name synonymous with the terror and cruelty his army brought to those unfortunate enough to fall victim. He ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b70733-d564H7iUj7Y2.png', NULL, NULL, '逢坂良太', NULL, 70733, 'MAIN', 2523) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016587', 'AN1678', 'アルシエル', 'Alciel is one of Satan''s Demon Generals and was also transported to modern day Japan with him. Extremely loyal to Maou, he takes care of the domestic duties at home and goes to the library to research ways for Maou and himself to regain their powers.  Back in Ente Isla, Alciel was known widely as the right hand of King Satan and a master strategist, making him both a trusted adviser and top military commander to the ruler of the Demon Realm. However, he shared his leader''s belief that humans liv', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b70737-lDeBmECttJCK.png', NULL, NULL, '小野友樹', NULL, 70737, 'MAIN', 1003) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016588', 'AN1678', 'クレスティア・ベル', 'She is the chief interrogator and executioner for the Church Investigation Commission, who came into the human realm from Ente Isla to check on reports about Emi''s alliance with Maou. Unknown to Maou who she is, she becomes his next door neighbor and eventually became close, being a good cook she would drop by in Maou''s apartment to  prepare meals for everyone. She knows little about the human realm especially in Tokyo that she is having difficulty going around the city and understanding people''', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b83105-NoBGyXWCvlW2.jpg', NULL, NULL, '伊藤かな恵', NULL, 83105, 'MAIN', 431) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016589', 'AN1678', 'アラス・ラムス', 'Alas Ramus is the appointed daughter of Sadao Maou and Emi Yusa.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158748-fZ530q2Fc2Ur.png', NULL, NULL, '木野日菜', NULL, 158748, 'MAIN', 146) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016590', 'AN1678', 'ルシフェル', 'Lucifer is a fallen angel and one of the Demon King''s generals. After his defeat at the hands of Hero Emilia, he was secretly rescued by Olba Meyer, who promised to return Lucifer to heaven if they became allies in defeating the Demon Lord. After being defeated by the Demon Lord, Urushihara moved in with Sadao Maou and Ashiya.  Lucifer is shown to be cunning and sneaky as well as a childish, preferring to surf the internet and play video games rather than help Ashiya with the housework. Due to h', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b83103-fksjOXqJCmxd.png', NULL, NULL, '下野紘', NULL, 83103, 'MAIN', 1106) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016591', 'AN1678', '佐々木千穂', 'Chiho is Maou''s friend and a fellow employee at MgRonald''s. She has a crush on Maou. She can hear and understand the language of Ente Isla, after receiving feedback from a hypnosis spell that Maou cast on her father, Inspector Sasaki.  She has a strong will and a polite, friendly, pleasant all around personality. She is head over heels for Maou, and sometimes gets jealous when she sees Emi and Maou together.  She is a part-time employee at MgRonald''s along with Maou. Maou had met her father when', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b70739-rJpfVU2YH5nS.png', '9月10日', NULL, '東山奈央', NULL, 70739, 'MAIN', 781) ON CONFLICT DO NOTHING;
