INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016619', 'AN1679', '佐藤亮太', 'Ryouta is a salaryman who has suddenly been transferred to a mysterious world where everything is dropped from monsters. All of his stats, including his physical and magical strength, are the weakest "F". In addition, his level is fixed at "1", the lowest. However, he has a unique skill "Drop Skill, All S", which makes him the strongest even though he is level 1..!', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297410-MIL8NmHGe2Ud.jpg', NULL, NULL, '石川界人', NULL, 297410, 'MAIN', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016620', 'AN1679', 'エミリー・ブラウン', 'Emily is an adventurer girl who uses a large hammer that does not match her petite frame. She meets Ryouta, after he defeats a slime in a dungeon. She is honest and kind, but her low drop skill means that she earns little money and lives in the dungeon alone. She has good life skills such as cooking and cleaning.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297412-MbIBvzJdIrLv.jpg', NULL, NULL, '久住琳', NULL, 297412, 'MAIN', 77) ON CONFLICT DO NOTHING;
