INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016628', 'AN1680', 'ブレイド', 'Blade is a transfer student at Rosewood Academy.  He is the great hero, a unique existence in the world, destined to defeat evil. Due to this immense burden, Blade was never able to relate to other people nor form bonds of friendship with anyone, this being the reason for his obsession with being a normal person.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249375-Tin40gymlGgJ.jpg', NULL, NULL, '川島零士', NULL, 249375, 'MAIN', 47) ON CONFLICT DO NOTHING;
