INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016642', 'AN1681', '片瀬詩織里', 'She is in charge of planning in the ''Second Development Section'' and has been with the company for three years. Shinozaki, who works in the same team, is the ''only junior staff member'' for her and she cares about her in some way.  Her favourite animal is a cat. She is somewhat cat-like herself, and often "catnames" people she likes when she gets close to them or when a tasty-looking meal is brought to her.  She is a reliable older woman who cooks and does her housework well. However, she has nev', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b166994-kBkFeQGvcZ5y.png', '2月11日', NULL, '立花日菜', NULL, 166994, 'MAIN', 291) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016643', 'AN1681', '篠崎拓馬', 'He is a first year in the company that is in charge of planning in the ''Second Development Section''.  He is shy about love, and although he is interested in Shiori, he is unable to talk about the distance between them; he is healed and thrilled on a daily basis.  He used to go to the arcade when he was in high school and is good at crane games. However, he is of an age where he has never had a girlfriend', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b166995-VL3jrNBXpyj6.png', '5月15日', NULL, '新祐樹', NULL, 166995, 'MAIN', 35) ON CONFLICT DO NOTHING;
