INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016646', 'AN1681', '早川千夏', 'She''s a new employee joined in the same period as Shinozaki.   She''s in charge of design in the 2nd Development Section. She and Shinozaki grew up close to each other and attended the same preschool, elementary school and junior high school. She has a refreshing personality and a clear-cut way of saying things.  Although she keeps it a secret from all her colleagues except Shinozaki, she has geeky hobbies and enjoys cosplay.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b166996-SCOh9kjtY08z.png', '10月9日', NULL, '花守ゆみり', NULL, 166996, 'SUPPORTING', 99) ON CONFLICT DO NOTHING;
