INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016682', 'AN1684', 'ヴァミリオ', 'Power level: 78  One of the Four Heavenly Kings of the Empire. Has a hair-trigger temper, but is big-hearted underneath. The serious one of the group, she usually gets caught up in Helck and Piwi''s shenanigans.  She can use fire and summoning magic and excells at fighting several enemies simultaneously.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121108-wZkid4QN5bK7.png', NULL, NULL, '小松未可子', 152, 121108, 'MAIN', 590) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016683', 'AN1684', 'ヘルク', 'Power level: 99  The titular human hero Helck. He is the older brother of the hero Cless. Immensely strong, reliable, and capable, Helck seeks to become the champion of demons and destroy the humans.', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121109-S0JrxCikKbAV.png', NULL, NULL, '小西克幸', 200, 121109, 'MAIN', 271) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016684', 'AN1684', 'ピウイ', 'Piwi is a round pure green fluffy bird like creature.  Piwi is raucous and very ignorant. Yet, he has been described with a "cute" personality. He is very carefree, sometimes even oblivious to the violence that occurs around him.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152542-hehnwQhinr65.png', NULL, NULL, '井澤詩織', NULL, 152542, 'MAIN', 190) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016685', 'AN1684', 'アリシア', 'Alicia is a close friend of Helck. She is a mercenary that Helck met on his journey to Edil''s home. She comes from a long line of mercenaries. She was told that one of her ancestors was a hero that fought demons before the current Human Empire was founded.  (Source: helck.fandom.com)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b150236-wd6aqzjV23jC.jpg', NULL, NULL, '近藤玲奈', NULL, 150236, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016686', 'AN1684', 'ラファエド', 'Rafaed (ラファエド, Rafaedo) is a very powerful swordsman and alongside the Human King and Mikaros, one of the main antagonists of Helck. He saved Cless by bringing him to Mikaros when the child became sick. He is the caretaker and father figure of Helck, Cless, and Sharuami.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152534-ON0xbdIm34eX.png', NULL, NULL, '宮内敦士', NULL, 152534, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016687', 'AN1684', 'チュパブラ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b309937-jmDDGccFt2ej.jpg', NULL, NULL, '三浦勝之', NULL, 309937, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016688', 'AN1684', 'クシキ', 'Level 43 Spy', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b311035-wuqvKC6P1J7v.jpg', NULL, NULL, '岩崎諒太', NULL, 311035, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
