INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016692', 'AN1684', 'エディル', 'Edil always put the people and his comrades first. He is very cheerful among his friends even in hard times. He has an initial distrust of Demons and blames them for the suffering of the Human Empire because of the propaganda. He often sees his older brothers in Helck because of Helck''s burly body and gentle smile. He does not like a specific type of woman, but would prefer a woman who does not mind him speaking truthfully and is powerful.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b152535-UYXJL8KF6YW6.png', NULL, NULL, '七海ひろき', NULL, 152535, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016693', 'AN1684', 'ミカロス', 'Mikaros is an arrogant, egoistic person, who wants to destroy the current world order. He would do anything to succeed.  He is a great tactician, manipulator and executes his plans brilliantly. He fears death and is terrified/irritated by the though of someone being stronger, whose he can''t match no matter what he does.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b152541-EI8g5kv4bJhI.png', NULL, NULL, '平川大輔', NULL, 152541, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016694', 'AN1684', 'エリーユ姫', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313783-QfUspWpgUIp4.jpg', NULL, NULL, '朝井彩加', NULL, 313783, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
