INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016696', 'AN1684', 'クレス', 'Cless is the hero of the human world and the younger brother of Helck.  (Source: helck.fandom.com)', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150238-du8kXjVjrMSC.jpg', NULL, NULL, '小野元春', NULL, 150238, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
