INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016703', 'AN1684', 'カバノ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b312543-ydHQH29TMkzD.jpg', NULL, NULL, '山口竜之介', NULL, 312543, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016704', 'AN1684', 'アスタ', 'Asuta is full of curiosity, so she takes interest in lots of things. She is very cautious about her surroundings and always takes extra precautions to ensure success, such as using tools that her natural abilities can already accomplish. She is quick to jump to a conclusion if it means something poses as a possible danger.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152536-8YcwFzY4Z5Ts.png', NULL, NULL, '青木志貴', NULL, 152536, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016705', 'AN1684', 'ヒュラ', 'Hyura is the current First Brigade Leader of Tooru Castle. She was one of the final four contestants for the next Demon King to replace Tooru.  (Source: helck.fandom.com)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b150237-2Agc0anXmrR0.jpg', NULL, NULL, '前田玲奈', NULL, 150237, 'SUPPORTING', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016706', 'AN1684', 'イスタ', 'Ista is very caring of her older sister and her well being. She loves her sister deeply.  Ista feels uncomfortable at the sight of blood, especially when she was little. She is a very clumsy girl, a crybaby, a coward, and a worrywart. However, despite these traits, she is a hard worker and her willpower is superior to even Hyura''s. She loves her sister more than anything else.  Her dream is to serve the Red Heavenly King, Vamirio, whom she greatly admires.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152538-4Drxoc0EuAI0.png', NULL, NULL, '白石晴香', 168, 152538, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016707', 'AN1684', 'ロココ', 'Rococo is a very cheerful person. She enjoys taking care of everything flawlessly apart from warfare. She is a pacifist in favor of living together with the humans.  She greatly reveres Azudora and would gladly give her life for Azudora''s sake.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152537-vTft9HnYTV5k.png', NULL, NULL, '徳井青空', NULL, 152537, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016708', 'AN1684', 'ムーンミ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314341-fOzNXte07tlN.jpg', NULL, NULL, 'いとうさとる', NULL, 314341, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016709', 'AN1684', 'ホン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b298362-0q05kPesGZvq.jpg', NULL, NULL, '石田彰', NULL, 298362, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016710', 'AN1684', 'ケンロス', 'Kenros is a carefree and pleasant person. He is an extreme pacifist. He prefer to do things at his own pace and is proud of being the self-proclaimed fastest in the Empire. He amicably idolizes Helck.  He is highly charismatic and friendly to everyone no matter who it is.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b152539-I20WUVrCyL6y.jpg', NULL, NULL, '吉野裕行', NULL, 152539, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
