INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016717', 'AN1684', '魔女', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313522-OUA0W16gPlQ5.png', NULL, NULL, 'ゆかな', NULL, 313522, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016718', 'AN1685', '諭吉', 'An extremely capable tsundere cat. When he was a kitten, he almost froze to death in the street when he was picked up by Saku and became her pet. Initially, he was just an ordinary cat, but because Saku was so lacking in life skills, he had to do something about it and grew into a very capable cat. Although he calls Saku a "useless person," everything he says and does is filled with gratitude and love for his owner.', 5, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265486-F1NUcHA3F1xk.jpg', NULL, NULL, '安元洋貴', NULL, 265486, 'MAIN', 333) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016719', 'AN1685', '福沢幸来', 'The owner of Yukichi, she is a 28-year-old office worker. According to Yukichi, she is a "useless person" who works too hard and is barely able to take care of herself outside of work. She always puts off taking care of herself until later and pushes herself to the limit until she collapses. Until she picked up Yukichi, she used to fall sleep in the entrance area of her garbage-filled house(!). As long as she has a bit of good fortune and a beer, she can live happily.', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265485-cK58E4BEIaqt.png', NULL, NULL, '石川由依', NULL, 265485, 'MAIN', 156) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016720', 'AN1685', '幸来の父', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309554-xU8KuaEsselg.jpg', NULL, NULL, '福山潤', NULL, 309554, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
