INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016722', 'AN1685', '柴咲ゆり', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309539-YuZPICOBtYRG.jpg', NULL, NULL, '加隈亜衣', NULL, 309539, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016723', 'AN1685', '幸来の母', 'While she cares about her daughter, she has a tendency to have a foul mouth, often calling Saku her "stupid daughter." She is worried about Saku, calling her regularly.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309557-r1vW9saBFhm4.png', NULL, NULL, '佐藤聡美', NULL, 309557, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
