INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016727', 'AN1685', '尾代', 'One of Saku''s colleagues who is also good friends with Yuri. She often goes to singles meetups, but the results are never good. Other colleagues often ask her to introduce them to Saku.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309559-ET90maNE8gYg.png', NULL, NULL, '稲瀬葵', NULL, 309559, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
