INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016767', 'AN1688', 'ヒューゴ', 'A former pickpocket, Hugo now chooses the highroad, and works with Zain and Cuff at the Circus.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b329732-aoQsqjnB9MBu.png', NULL, NULL, '石上静香', NULL, 329732, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
