INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016769', 'AN1688', 'ファイファ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b351633-qdY6ue5MwxMc.png', NULL, NULL, '根本京里', NULL, 351633, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016770', 'AN1688', '狼', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b351634-1CX8raLpwYn6.png', NULL, NULL, '三宅健太', NULL, 351634, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016771', 'AN1689', 'ライザリン・シュタウト', 'An ordinary girl whose unique characteristic is the fact that she is just that - ordinary. Ryza has a wild and tomboyish personality with a strong sense of justice. While she can be stubborn in her convictions, her heart is in the right place. Her whole world is turned upside down during an extraordinary encounter...', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b223350-yNmgtin88wwu.png', NULL, NULL, 'のぐちゆり', 161, 223350, 'MAIN', 1870) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016772', 'AN1689', 'クラウディア・バレンツ', 'Klaudia is the daughter of wealthy travelling merchant. She possesses a refined aura and kind personality. She has an interest in music and practices playing the flute, but hides it from her father. When visiting Kurken Island she makes friends with Ryza, Lent and Tao, and becomes one of the members of the secret hideout. Together they share many adventures over the summer.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b251207-JipTTcadUKjo.png', NULL, NULL, '大和田仁美', 164, 251207, 'MAIN', 1473) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016773', 'AN1689', 'リラ・ディザイアス', 'As a member of the fallen Oren race in the Underworld, she strives a goal to eliminate the remaining problems left by the extinct Klint Kingdom, and avenge her homeland from the Philscuha''s invasion together with Empel Vollmer.', 100, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b251208-VJWf9p0waouW.png', NULL, NULL, '照井春佳', 164, 251208, 'MAIN', 1505) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016774', 'AN1689', 'レント・マルスリンク', 'Lent is a childhood friend of Ryza and Tao, who, together, aims to venture out to the mainland and explore the world out from their homeland. Furthermore, as an aspiring adventurer, he wants to be a known man who travels past the restricted and unknown places of which no one ever been before so that he can be acknowledged for who he can become, and overshadow his now drunk abusive father', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300891-ItOdMOrN7hDX.png', NULL, NULL, '寺島拓篤', 179, 300891, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016775', 'AN1689', 'タオ・モンガルテン', 'Tao is childhood friends with Ryza and Lent who, together, aims to venture out to the mainland and explore the world out from their homeland, although he is the most hesitant out of the group to actually join the voyage. His family owns old books that contain ancient language and aims to discover and learn it as they travel.', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300892-Zvoc70ihiOhl.jpg', NULL, NULL, '近藤唯', 170, 300892, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016776', 'AN1689', 'アンペル・フォルマー', 'Empel is a wandering alchemist investigating the ruins of the Klint Kingdom together with Lila Decyrus. Due to an injury, he is unable to perform advanced techniques but teaches Ryza the world of Alchemy as she has the talent. He apparently has a sweet tooth that enjoys all kinds of sweets, of which he would often buy dozens of them', 100, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300893-Xb19ClaIapSg.jpg', NULL, NULL, '野島裕史', 172, 300893, 'MAIN', 28) ON CONFLICT DO NOTHING;
