INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016818', 'AN1695', '津島善子', 'A first-year student who consistently has bad luck, so she thinks of herself as a fallen angel, although she is very proud of this fact. She insists on being called "Yohane" instead of her real name, Yoshiko.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89849-OXKMEsvrPQ12.png', '7月13日', 'O', '小林愛香', 156, 89849, 'MAIN', 1580) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016819', 'AN1695', '小原鞠莉', 'A half-Japanese third-year girl whose Italian-American father manages a chain of Italian-style hotels. She has a bright personality and moves at her own pace.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89851-YMGrQCtVAqjz.png', '6月13日', 'AB', '鈴木愛奈', 163, 89851, 'SUPPORTING', 762) ON CONFLICT DO NOTHING;
