INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016821', 'AN1695', '黒澤ダイヤ', 'Dia is a third year student who is the president of the student council, and is the older sister of Ruby Kurosawa.  Dia is a very refined, polite and mature young woman who speaks in a formal style of Japanese, regarding all of her friends with politeness by referring to each of them as "-san", and usually ending her phrases with "-desu wa." Very hardworking and a bit of a perfectionist, she dislikes when things are done sloppily or incorrectly. She is also very meticulous regarding small detail', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89847-oAPgNyrOp6tO.png', '1月1日', 'A', '小宮有紗', 162, 89847, 'SUPPORTING', 812) ON CONFLICT DO NOTHING;
