INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016826', 'AN1695', 'ペラピー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b307070-7XeBwyNbkWQo.png', NULL, NULL, NULL, NULL, 307070, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016827', 'AN1695', '桜内梨子', 'Riko is a reserved, polite and modest girl who likes indoor activities, acting as a foil to her friends, the more energetic Chika and You. However, while she is calm and mature, she often flies into a panic when under pressure, jumping to conclusions and making mistakes. Because of this, and a previous incident on which she failed to play the piano at a live audience, she does not think she is special, so she does not want to become a school idol. However, her friend Chika drags her into it, in ', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89845-KlToJ5lQEs5U.png', '9月19日', NULL, '逢田梨香子', 160, 89845, 'SUPPORTING', 970) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016828', 'AN1695', '渡辺月', 'Tsuki Watanabe is You Watanabe''s cousin, and she is a second-year student who serves as the acting Student Council President at Numazu High School. Growing up in Italy, Tsuki is incredibly fluent in Italian.   A dependable friend and fond of uniforms, Tsuki shares many qualities with her school idol cousin. Of the entire student body, she was the only one willing to help the transfer students be accepted into the new school.    (Source: Love Live! Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218936-V6sazfYjvCmq.png', NULL, NULL, '黒沢ともよ', NULL, 218936, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016829', 'AN1695', 'ライラプス', 'A large wolf beast that lives with Yohane. She has a gentle personality and is a good companion to Yohane.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b308611-knNV78kVhwQk.png', NULL, NULL, '日笠陽子', NULL, 308611, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016830', 'AN1695', '松浦果南', 'Kanan Matsuura is a third-year student living alone with her grandfather, who runs a diving shop on a nearby island. Breezily mature, she rarely sweats the details and usually maintains a calm, cool demeanor.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89846-e78QbB8WupZl.png', '2月10日', 'O', '諏訪ななか', 162, 89846, 'SUPPORTING', 532) ON CONFLICT DO NOTHING;
