INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016834', 'AN1695', '国木田花丸', 'Hanamaru is an easily distracted first-year student whose family runs a local temple without several modern-age utilities such as computers and hand dryers. Because of this, she becomes enamored upon seeing them, much to the surprise of others. She refers to herself as either "ora" or "Maru", and ends many of her sentences with "-zura" because of her Shizuoka dialect. She is also a member of a local choir due to her talent at singing. Before joining Aqours, she is an avid reader at the school''s ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89850-oxXH5NDC5Pnj.png', '3月4日', 'O', '高槻かなこ', 152, 89850, 'SUPPORTING', 784) ON CONFLICT DO NOTHING;
