INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016852', 'AN1698', 'ハルハラ・ハル子', 'Haruko Haruhara is Mabase''s newest resident, and an extraterrestrial investigator for the Galactic Space Police Brotherhood.  Haruko is an energetic, spontaneous girl with light-pinkish hair. She claims to be 19 years old, but it is impossible to know if that is true. In the first episode, she runs over Naota with her Vespa and hits him in the head with her guitar. Shortly after, she becomes the Nandaba household''s house-maid while working to find Atomsk, the most powerful space pirate in the ga', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b627-VkiKQwzH1c8S.png', NULL, NULL, '雨蘭咲木子', NULL, 627, 'MAIN', 3144) ON CONFLICT DO NOTHING;
