INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016856', 'AN1698', 'アマラオ', 'Commander Amarao works for the department of Interstellar Immigration. This agency, among other things, acts as a middle man for negotiations between the government and Medical Mechanica. Thus, Haruko/Raharu is a big problem for them as she is bent on provoking an attack by disrupting communications. Amarao has fake eyebrows made of nori which he believes serve the dual purpose of making him look macho and protecting him from N.O. Amarao seems to have had a past relationship with Haruko similar ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b634-DaH9meIeKH77.jpg', NULL, NULL, '前田剛', NULL, 634, 'SUPPORTING', 104) ON CONFLICT DO NOTHING;
