INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016916', 'AN1704', 'アルファ', 'Race: Elf  Alpha is the second-in-command of Shadow Garden. After being cured of Demon Possession by Cid Kagenou, she would devote her life to his cause, becoming the first member to be recruited into his organization, Shadow Garden.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162246-IbbxkhNJFDN5.png', '7月23日', NULL, '瀬戸麻沙美', NULL, 162246, 'MAIN', 1645) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016917', 'AN1704', 'シド・カゲノー', 'Race: Human  Cid Kagenou, under the moniker of "Shadow," is the founder and leader of the secret organization "Shadow Garden." He founded the organization to help realize his fantasy of becoming an “Eminence in Shadow". However, unbeknownst to him, his fabrications are often revealed to be quite genuine in reality. Cid is the reincarnation of Minoru Kagenou.   (Source: The Eminence in Shadow Wiki)', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136837-3WR22FYet8Hv.jpg', '1月10日', NULL, '山下誠一郎', NULL, 136837, 'MAIN', 6919) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016918', 'AN1704', 'ベータ', 'Race: Elf  Beta is the second member of Shadow Garden, supporting her master Shadow against the Order of Diabolos.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162247-R6OrAuT1FwL4.png', '10月27日', NULL, '水瀬いのり', NULL, 162247, 'MAIN', 1257) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016919', 'AN1704', 'デルタ', 'Race: Beastkin  Delta is a member of Shadow Garden, being fourth of the original Shadow Seven to join the organization after her Demonic Possession was healed by her master Shadow. As the most physically gifted of the Seven, Delta is also often the most destructive and brutal of the group due to her lack of sense and self-control.  (Source: To Be a Power in the Shadows! Wiki)', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162248-57Xgk6EmwKRQ.png', '4月29日', NULL, 'ファイルーズあい', NULL, 162248, 'SUPPORTING', 2669) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016920', 'AN1704', 'オメガ', 'Member of Shadow Garden, and one of the Numbers (No. 24). She is a subordinate of Epsilon. Omega is usually calm and collected but is troubled by her tendency to laugh at silly jokes.', 24, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b295293-w4DP3ifIZHu2.png', '12月4日', NULL, '前川涼子', NULL, 295293, 'SUPPORTING', 88) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016921', 'AN1704', 'アレクシア・ミドガル', 'Race: Human  Alexia Midgar is the second princess of the Kingdom of Midgar and younger sister of Iris Midgar. She is also a student of Midgar Royal Spellsword Academy.  (Source: To Be a Power in the Shadows! Wiki)', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168799-uAsWFrrfqxTN.png', '4月6日', NULL, '花澤香菜', NULL, 168799, 'SUPPORTING', 742) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016922', 'AN1704', 'クローディア', 'An elite staff member of the Magic Swordsmen Association who becomes the leader of Association''s task force.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316309-mWkqBjM0ZRPA.png', NULL, NULL, '小市眞琴', NULL, 316309, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016923', 'AN1704', 'クレア・カゲノー', 'Race: Human  Claire is the older sister of Cid Kagenou and heir to the Kagenou Family.  (Source: To Be a Power in the Shadows! Wiki)', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168798-IrHBKh5xbRsr.png', '6月2日', NULL, '日高里菜', NULL, 168798, 'SUPPORTING', 603) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016924', 'AN1704', '665番', 'Race: Elf  665 is a member of Shadow Garden''s Numbers and is in a squad with 664 and 666. She has a calm personality and is good at providing support.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b229658-QPPZFbPR1LT7.png', '8月2日', NULL, '羊宮妃那', NULL, 229658, 'SUPPORTING', 68) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016925', 'AN1704', 'クイントン', 'A ferocious swordsman who has participated in the Bushin Festival many times.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296393-wvxuGqitrNTa.jpg', NULL, NULL, '三宅健太', NULL, 296393, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016926', 'AN1704', 'カナ', 'One of Yukime''s closest aides and sisters with Natsu.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316310-YfO7PNdmB8fv.png', NULL, NULL, '朝日奈丸佳', NULL, 316310, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
