INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016928', 'AN1704', 'マルコ・グレンジャー', 'Knight of the Crimson Order', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290847-2rdQVKiCCwIk.jpg', NULL, NULL, '安田陸矢', NULL, 290847, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016929', 'AN1704', 'クアドイ', 'One of the Named Children of the Cult of Diablos.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b319872-0nmKoO5nbIbi.png', NULL, NULL, '濱野大輝', NULL, 319872, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016930', 'AN1704', 'イータ', 'Race: Elf  Eta is the seventh member of Shadow Garden, being one of the original Seven Shadows. She specializes and is in charge of the research faction of Shadow Garden and as a result has her own laboratory. She is known as Eta Lloyd Wright, the genius architect, whose work won unanimous first place in an Architecture of the Year.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289297-e2DgfeWhVPRa.jpg', '11月10日', NULL, '近藤玲奈', NULL, 289297, 'SUPPORTING', 281) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016931', 'AN1704', 'ローズ・オリアナ', 'Race: Human  Rosa Oriana is a noble Princess from the Oriana kingdom. She is known for being a genius in art in her kingdom. However, she came to Midgar Royal Spellsword Academy in order to learn swordsmanship.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168800-eb3FqWq0IdyV.png', '8月7日', NULL, '白石晴香', NULL, 168800, 'SUPPORTING', 521) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016932', 'AN1704', 'アイリス・ミドガル', 'Race: Human  Iris Midgar is the first princess of the Kingdom of Midgar and older sister of Alexia Midgar. She is also leader of the Crimson Order.   (Source: *The Eminence in Shadow* Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204204-wsPvzUwfdUwJ.jpg', '9月5日', NULL, '日笠陽子', NULL, 204204, 'SUPPORTING', 218) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016933', 'AN1704', 'ガーター', 'President of Garter Corporation and Gettan''s primary confidant.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318095-uCkiIVvYlTSV.png', NULL, NULL, '茶風林 ', NULL, 318095, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016934', 'AN1704', 'ドエム・ケツハット', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297029-0uu6ETEihyie.jpg', NULL, NULL, '速水奨', NULL, 297029, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016935', 'AN1704', 'ユキメ', 'Race: Therianthrope (Fox)  She is the ruler of the White Tower, a therianthrope known as a "Spirit Fox". Even Among the Spirit Fox clan she possesses exceptional talents and combat abilities, using an iron fan as her weapon to dance gracefully in battle. While she manages the red-light district in the Lawless City, she is also a savvy entrepreneur who runs a trading company called the Snow Fox Corporation', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217045-g7JT2Qvwa00f.png', NULL, NULL, '伊藤静', NULL, 217045, 'SUPPORTING', 250) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016936', 'AN1704', 'イプシロン', 'Race: Elf  Epsilon is the fifth member of Shadow Garden. Due to her insecurities with having a flat-chest, she manipulated her slime bodysuit every year to slowly increase the mass on her chest, eventually developing a fake large breast. As a consequence of this, she developed extreme magic control earning her the title, "The Precision."', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162249-eJRpBIC5lAZX.png', '2月2日', NULL, '金元寿子', NULL, 162249, 'SUPPORTING', 745) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016937', 'AN1704', 'ウィクトーリア', 'Member of Shadow Garden, serving as one of The Numbers under the codename Number 559. Her abilities are said to rival those of the Seven Shadows. She is one of only two people, except the Seven Shadows, to receive their powers directly from Shadow himself. Victoria does not care about consequences of her actions or collateral damage as long as she can accomplish her mission.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306198-BaeyFHlWhiPj.jpg', NULL, NULL, '伊藤美来', NULL, 306198, 'SUPPORTING', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016938', 'AN1704', 'ジャガ・イモ', 'One of Cid Kagenou''s chosen "friends" to help him blend in as a background character', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287013-mKBY4xbondVc.jpg', '6月15日', NULL, '松重慎', NULL, 287013, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016939', 'AN1704', 'ザブラ', 'Delta''s older brother and member of the Clovers, a small elite group under the Garter Corporation.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318096-gdIftaRg27ZR.png', NULL, NULL, '坂泰斗', NULL, 318096, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016940', 'AN1704', 'モードレッド', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b229659-gt4setpIM0ZE.png', NULL, NULL, '子安武人', NULL, 229659, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016941', 'AN1704', 'ジャガノート', 'Race: Human  Tyrant the Juggernaut is one of three monarchs of Lawless City. He mainly relies on his instincts and physical strength to demolish his opponents, as using any techniques would only slow him down    (Source: To Be a Power in the Shadows! Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b229663-XqNjegFIGn2s.png', NULL, NULL, '小山剛志', NULL, 229663, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016942', 'AN1704', 'ゼータ', 'Race: Beastkin  Zeta is the sixth member of Shadow Garden, being one of the original Seven Shadows. She usually travels around the world alone gathering intelligence.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264565-acUMiD3pz2ZU.png', '2月22日', NULL, '朝井彩加', NULL, 264565, 'SUPPORTING', 387) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016943', 'AN1704', 'ニュー', 'Race: Human  Nu is the thirteenth member of Shadow Garden and an employee of Mitsugoshi Company.   (Source: To Be a Power in the Shadows! Wiki)', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b168968-kiFqnWfpCLUE.png', '8月28日', NULL, '内田真礼', NULL, 168968, 'SUPPORTING', 240) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016944', 'AN1704', 'カイ', 'Member of Shadow Garden, and one of the Numbers (no. 22). She is a subordinate of Epsilon. She has a serious and stern demeanor but is surprisingly shy and blushes often.', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b295292-Eo3yIn4Qh8ND.png', '5月4日', NULL, '南真由', NULL, 295292, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016945', 'AN1704', 'マーガレット', 'A maid in service of the Oriana royal family and former personal caretaker of Rose. She used to admire Rose but that quickly turned to distrust after the incident in the Midgar Kingdom. She in awe of Cid''s skills as a pianist and persistently offers to assist him in finding a patron.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b320661-3UPS00RqkhJF.png', NULL, NULL, '上田麗奈', NULL, 320661, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016946', 'AN1704', 'エリザベート', 'Race: Vampire  Elisabeth is one of the three monarchs of the Lawless City and the Queen of Vampires.  (Source: To Be a Power in the Shadows! Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217044-mgNojqXLQCRo.png', NULL, NULL, '早見沙織', NULL, 217044, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016947', 'AN1704', 'ガンマ', 'Race: Elf  Gamma is a member of Shadow Garden, being third of the original Seven Shadows as well as the director of the Mitsugoshi Company. Despite her lack of coordination, Gamma''s knowledge has allowed her to recreate many of the items described by her master Shadow to sell as Mitsugoshi''s exclusive products.  (Source: To Be a Power in the Shadows! Wiki)', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162245-x86QMM6nOj75.png', '5月20日', NULL, '三森すずこ', NULL, 162245, 'SUPPORTING', 718) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016948', 'AN1704', 'ゴルドー・キンメッキ', 'A swordsman who participated in the God of War Tournament.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296394-tJo8XIMuP42Z.jpg', '1月24日', NULL, '興津和幸', NULL, 296394, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016949', 'AN1704', '番犬', 'Watchdog of the Crimson Tower at Lawless City. His task is to ensure that no one enters the Tower.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316306-hKM56ecOLK3b.png', NULL, NULL, '福島潤', NULL, 316306, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016950', 'AN1704', 'ケビン', 'Guard of the royal palace of the Oriana Kingdom. Kevin has unrequited love towards Margaret but is convinced his feelings are reciprocated. He behaves obsessively towards Margaret, confronting and threatening Cid after seeing the two in close conversation.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b320662-uxkxTUz2KCYc.png', NULL, NULL, '川田紳司', NULL, 320662, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016951', 'AN1704', 'メアリー', 'Race: Vampire  Mary is a Vampire Hunter, dedicated in putting an end to Elizabeth, the Vampire Queen.  (Source: To Be a Power in the Shadows! Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217043-VZDrrt1DYl5Q.png', NULL, NULL, '加隈亜衣', NULL, 217043, 'SUPPORTING', 121) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016952', 'AN1704', 'ラムダ', 'Member of Shadow Garden, and one of The Numbers (No. 11). She is in charge of training new recruits.', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298851-UMG5YdDRpnRB.jpg', '6月26日', NULL, '長谷川育美', NULL, 298851, 'SUPPORTING', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016953', 'AN1704', 'アウロラ', 'Race: Human  A woman known as the Calamity Witch who once brought chaos and destruction to the world. In the Goddess'' Trial in the Sacred Land, she is summoned in reaction to Cid''s presence and does battle with him in the form of Shadow. Her body is sealed in the sanctuary, and after helping Cid to escape she disappears together with its destruction.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215409-Y1Ti42451ivg.png', '3月25日', NULL, '名塚佳織', NULL, 215409, 'SUPPORTING', 687) ON CONFLICT DO NOTHING;
