INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016963', 'AN1708', 'アンディ', 'Andy is member no. 9 of the Round Table. He is a Negator with the alias Undead. His original personality is that of Victor.  Andy is a deuteragonist along with Fuuko Izumo.  Andy is insanely reckless, he enjoys attempting to die and is always looking for new methods of death. He also has a soft spot for Fuuko, who he is very protective of and gets very angry when she is hurt, to the point where he will willingly remove the card in his head to release Victor.   Andy is a tall and muscular man, wi', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158749-W1XmNGmRJphS.png', '4月15日', NULL, '中村悠一', NULL, 158749, 'MAIN', 909) ON CONFLICT DO NOTHING;
