INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017004', 'AN1710', 'ゴブリンスレイヤー', 'The series'' main character, an experienced silver ranked adventurer who only concerns himself with hunting goblins. The jobs he takes merely involve goblins and he takes no interest in others. His appearance is not as glamorous or elegant due to using equipment that would seem lacking for an adventurer of his rank. He wears a gray suit of grubby leather armor, with chainmail underneath, a small buckler shield with a sharpened rim attached on his left forearm. His weapon is a sword of strange len', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126458-wCulCEFEPZSK.png', NULL, NULL, '梅原裕一郎', NULL, 126458, 'MAIN', 3624) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017005', 'AN1710', '女神官', 'Race: Human  Rank: Obsidian (Previously), Porcelain (Previously), Steel (current rank)          The main female protagonist. She is a porcelain rank adventurer, the lowest rank as she had just joined. Her personality consist of being young, kind, and a generally helpful person. She is capable of using healing magic and protective spells with a high amount of proficiency.  After her first goblin hunt rapidly goes downhill and saved by Goblin Slayer, she joins with him as a new party. Even after t', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126483-NQuBqaXHUJO2.jpg', NULL, NULL, '小倉唯', NULL, 126483, 'MAIN', 1102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017006', 'AN1710', '妖精弓手', 'A high elf adventurer. She came with Dwarf Shaman and Lizard Priest to find Goblin Slayer and recruit his help. They face some trouble earlier as they are unable to pronounce "Goblin Slayer" and refer to him in other names, until they find him. They revel their objective; due to the increase in other demon monsters, there are not enough people to deal with Goblins and the elf army cannot mobilize to attack goblins as it would create suspicion and panic, if the army were focusing only on taking o', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126457-leHoOLIOZy2a.png', NULL, NULL, '東山奈央', NULL, 126457, 'SUPPORTING', 1293) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017007', 'AN1710', '槍使い', 'Spearman is a silver-ranked adventurer based in the frontier. He is the partner of Witch. As a silver ranked adventurer, the third highest rank attainable, he induces the respect of his fellow adventurers, especially newbies, who look up to him.  He has brown spiky hair, and has light red earrings matching the color of his eyes. He wears a resplendent blue armor and is equipped with his singature weapon, a spear. Extremely confident in his abilities, he is keen on trying to impress other people ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n126488-fW2f7wryREzj.jpg', NULL, NULL, '松岡禎丞', NULL, 126488, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017008', 'AN1710', '大将', 'Taishou is the leader of the six gold-ranked adventurers renowned for defeating the Demon Lord ten years ago.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136315-BU2QJIMLQiCn.png', NULL, NULL, NULL, NULL, 136315, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
