INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017010', 'AN1710', '少女巫術師', 'Age: +20 Race: Rhea Job: Adventurer Rank: Bronze Affiliation: Adventurer''s Guild - Heavy Warrior''s Party  Druid Girl has a kind disposition and is friendly towards others. She tries to give advice to newer adventurers when given the chance.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n132710-bZNp9XpbHaML.jpg', NULL, NULL, '原田彩楓', NULL, 132710, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017011', 'AN1710', '令嬢剣士', 'Noble Fencer took up adverturing to become independent from her family. She was prideful, expecting to rise to Gold and even Platinum rank within a short period of time; and looked down upon goblins. However, her traumatizing ordeal with them crushed her into becoming a brooding woman fixated on killing the goblin paladin and retrieving her stolen family sword. After accomplishing those goals with the aid of Goblin Slayer''s party, she is able to overcome her rage and move on.  Now known as Femal', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188204-i0puFnVSEyTg.png', NULL, NULL, '上坂すみれ', NULL, 188204, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017012', 'AN1710', '蜥蜴僧侶', 'A lizardman adventurer who forms a party with High Elf Archer and Dwarf Shaman. They later team up with Goblin Slayer and Priestess. His rank is silver, the third highest rank. Calm and composed, he speaks to people politely and adresses them in a respectful manner. He seems to be the most soft-spoken, even-tempered, and sociable member of the party.  Lizard Priest has green skin and horns on his head. His intimidating visage and towering stature makes him come off as unnerving, even to his frie', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n126487-TErPQ7ADCryW.jpg', NULL, NULL, '杉田智和', NULL, 126487, 'SUPPORTING', 210) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017013', 'AN1710', '重い剣士', 'Race: Human Job: Adventurer Rank: Silver Affiliation: Adventurer''s Guildis   A silver ranked adventurer. He is currently acting as an instructor teaching new adventurers basic combat.', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131812-4mY1CxbvGqka.jpg', NULL, NULL, '濱野大輝', NULL, 131812, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
