INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017015', 'AN1710', '鉱人道士', 'A dwarf and a member of the party with Lizard Priest and High Elf Archer. They team up with Goblin Slayer and Priestess in order to infiltrate some ruins invaded by goblins. As a silver adventurer, he is an experienced spell caster. Well-built and with good physique despite his short stature, Dwarf Shaman''s long hair is completely white, which he ties up in a ponytail, and the beard he often strokes is elaborately braided. His earlobes have been elongated and are pierced by earrings. His priest ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n128254-6x8qS52q9Q0n.jpg', NULL, NULL, '中村悠一', NULL, 128254, 'SUPPORTING', 131) ON CONFLICT DO NOTHING;
