INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017017', 'AN1710', 'ゴブリン', 'Monsters that destroy and steal anything they come across. They all have a predisposition to hate "those with words".', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132632-rHa6hK46MzYb.jpg', NULL, NULL, '竹田海渡', NULL, 132632, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
