INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017025', 'AN1710', '受付嬢', 'A young woman who runs the Guild''s front office as a receptionist and hands out contracts to adventurers. She shows concern over the villages pleading for help against the goblins and is exasperated from how few experienced adventurers would take such jobs. This problem would leave inexperienced rookies to die from them or worse. She holds great amounts of respect for Goblin Slayer, due to his willingness to take on many goblin contracts others would not touch.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/126485-2zo57ux4EMeC.jpg', NULL, NULL, '内田真礼', NULL, 126485, 'SUPPORTING', 551) ON CONFLICT DO NOTHING;
