INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017027', 'AN1710', '魔女', 'Witch is a silver ranked adventurer who is in a party with Spearman. She is a beautiful spell-caster with long, purple hair who wears a revealing set of robes, dark colored with gold yellow outlining. She is usually shown as being rather seductive, acting in a rather amorous manner, often suggesting sexual undertones in otherwise normal conversation, which causes those she interacts with to become flustered or embarrassed. Despite her teasing, she is shown to be caring of those around her, offer', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n126486-e0DjNT3rBOT7.png', NULL, NULL, '日笠陽子', NULL, 126486, 'SUPPORTING', 459) ON CONFLICT DO NOTHING;
