INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017093', 'AN1713', '白川ルナ', 'Considered one of the school''s most beautiful girls, Shirakawa is easygoing and friendly with most people, earning her even more popularity. Since she is so popular, bad rumors tend to go about her, like how she dates guys for two or three months at best, and how easily she switches from guy to guy at the drop of a hat. All those rumors are false though. Despite her gal appearance, Shirakawa is sincerely devoted to whoever she is dating (to the point of being called "Heavy" or "Annoying"). She r', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263823-A2kH5dpddT44.png', NULL, NULL, '大西沙織', NULL, 263823, 'MAIN', 619) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017094', 'AN1713', '加島龍斗', 'Kashima has admired Shirakawa since the first year and got the lucky break of moving to the same class as her during the second year, turning simple admiration into a one-sided crush. Kashima never hoped to get more than that and was happy with keeping the status quo.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263824-b78Bn8aYLMoW.png', NULL, NULL, '花江夏樹', NULL, 263824, 'MAIN', 90) ON CONFLICT DO NOTHING;
