INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017122', 'AN1716', 'Desir Herrman', 'Magic Circle Rank: Tier 3 (Analysis Magic)  Desir Herrman is the central protagonist of A Returner’s Magic Should Be Special. After his return to the past upon the failure of clearing the Shadow World, he resolves to strengthen his allies so that the future doesn’t get repeated. In Hebrion Academy, commoners are frowned upon and put into the Beta class whilst the nobles are designated the alpha class, Desir is one of the commoners who hates the class system and wants things to change. As a resul', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141151-u6mLf1y5k7PJ.jpg', NULL, NULL, '寺島拓篤', NULL, 141151, 'MAIN', 383) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017123', 'AN1716', 'Romantica Eru', 'Circle Tier Level: 3 (Wind Mage)  When Desir Arman first meets Romantica after returning from the Shadow Labyrinth she exhibits a superiority complex due to her position as a noble which slowly decreases as the story progresses and she gets to know Desir Arman.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141152-ZnFSz0sTI1fD.jpg', NULL, NULL, '鈴代紗弓', NULL, 141152, 'MAIN', 179) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017124', 'AN1716', 'Pram Schneider', 'Circle Tier Level: 3 (Swordmage)  Pram is a member of Desir Arman''s alpha party made of commoners.', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141153-okb1ScsIZB0u.jpg', NULL, NULL, '藤原夏海', NULL, 141153, 'MAIN', 164) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017125', 'AN1716', 'Elheim Triquincy', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b330046-D2sUCBVTWusR.jpg', NULL, NULL, NULL, NULL, 330046, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017126', 'AN1716', 'Azest Kingscrown', 'Circle Level Tier: 4 (Swordmage)  Azest Jedgar F. Roguepalace was the firstborn of Gilltian Jedgar F. Roguepalace, the current emperor of the Hebrion Empire and thus the heir to the Hebrion throne. Initially Azest was a cold person and she tends to be uninterested about other people unless they consist of her close friends in the Desir group.', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141154-QJQ3ieyGBS1F.jpg', NULL, NULL, '瀬戸麻沙美', NULL, 141154, 'SUPPORTING', 339) ON CONFLICT DO NOTHING;
