INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017130', 'AN1716', 'Doneta Hadoon', 'A member of the Alpha Class and Blue Moon Party. Despises and looks down on commoners.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b324709-KhfHtmZ01Iwt.png', NULL, NULL, '間島淳司', NULL, 324709, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017131', 'AN1716', 'Percival Asengunitz', 'A member of the Alpha Class and Blue Moon Party.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b324710-F09uzGOwZoAa.png', NULL, NULL, '小松昌平', NULL, 324710, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017132', 'AN1716', 'Zod Exarion', 'Circle Tier Level: 7 (Sage)  Sage of Wisdom Zod Exarion is the Master of the Tower of Magic and the one and only Seventh-Circle magician in existence. He was known as the greatest mage in the world, the man who had singled-handily revived interest in magic. He also was one of the 100 people who fought against Bhromier Napolitan and one of the six who survived the battle.', 91, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172080-749EAEg0m4ig.jpg', NULL, NULL, '速水奨', NULL, 172080, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017133', 'AN1716', 'Priscilla Heisilgard', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b330045-zgz4P5pq0mnx.jpg', NULL, NULL, NULL, NULL, 330045, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017134', 'AN1717', 'クレア・フランソワ', 'Claire François is a proud noble who in the original [Revolution] is the villainess who bullies the heroine.   Claire is prideful with a competitive side to prove her worth as well as her family name. Her threatening behaviour conceals her fragile heart that comes from her childhood experiences. Becomes more prone to jealously as people she cares for may leave her. Her arrogant personality is mainly influenced by her father doting on her in her childhood more than anything.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149900-vwB2SAZARoKL.png', '3月28日', NULL, '奈波果林', 157, 149900, 'MAIN', 890) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017135', 'AN1717', 'レイ・テイラー', 'An ordinary office worker who finds herself in the body of the protagonist of her favorite otome game, Revolution. She aims to become a couple with her favorite character, Claire François.  Rae deliberately plays herself up as being a foolishly happy-go-lucky girl who is obsessed with gaining Claire''s affection. However, in reality, this is more of a coping mechanism brought about by her early experiences with exploring her sexuality. She is actually far less open with her true feelings, often b', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b171836-nB12KkDqxDbF.png', '7月19日', NULL, '芹澤優', 162, 171836, 'MAIN', 974) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017136', 'AN1717', 'ユー・バウア', 'The third heir within the Bauer Kingdom''s royal family. A charismatic and attractive prince type who uses charm to mask a cunning mind. Yu is the second most popular capture target within the game.', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b298261-TZOg5k6yG2oX.jpg', '3月3日', NULL, '日笠陽子', NULL, 298261, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017137', 'AN1717', 'ミシャ・ユール', 'Misha is Rae''s best friend and roommate at the Academy. She is a noble from a house that fell from grace and became impoverished. Despite the Jur family''s struggles with money, she still holds some reputation. She is accepting of her position and, rather than hold onto the noble status, portrays herself as equal among people with common background. This allowed for Rae and Misha to form their longstanding friendship.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231851-RLK56z4ArWum.png', '10月10日', NULL, '愛美', 152, 231851, 'SUPPORTING', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017138', 'AN1717', 'レレア', 'Baby slime adopted by Rae.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b312168-tFIiHSBnhS22.png', NULL, NULL, '栗坂南美', NULL, 312168, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017139', 'AN1717', 'マナリア・スース', 'Manaria Sousse is the first crown princess of the kingdom of Sousse. She is a distant relative of Claire. She is the world''s first confirmed quad-caster who possesses the highest aptitude in every element.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298263-slGkyuuTPLyS.png', NULL, NULL, '水樹奈々', NULL, 298263, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017140', 'AN1717', 'レーネ・オルソー', 'Lene is the eldest daughter of a wealthy merchant family, Aurosseau. She loyally serves Claire François as her personal maid. Lene seems very patient, and comes off as meek and subservient, but in reality, she just knows how to handle Claire very well after years of serving her.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231853-XsnDryQqYBru.png', '10月19日', NULL, '長谷川育美', 154, 231853, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017141', 'AN1717', 'ロレッタ・クグレット', 'Loretta is from the House Kuguret, a family well known for their history of military service.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305401-IH4fAjRAMi7L.png', NULL, NULL, '松本沙羅', NULL, 305401, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017142', 'AN1717', 'ドル・フランソワ', 'Dole François is the Minister of Finance in the Bauer Kingdom and the father of Claire François.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b349885-NIjz3Np98nrR.jpg', NULL, NULL, '三上哲', NULL, 349885, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017143', 'AN1717', 'ピピ・バルリエ', 'Pipi is the daughter of the House Barlier, a family with deep-seated connections in Bauer’s business world. She is childhood friends with Claire François and Loretta Kugret.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305402-osHrdU3Z0FwY.png', NULL, NULL, '栗坂南美', NULL, 305402, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017144', 'AN1717', 'ロッド・バウアー', 'The eldest heir within the Bauer Kingdom''s royal family and first in line to the throne. He is a energetic young man who becomes interested in Rae, much to her dismay. Rod is the most popular capture target within the game.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298262-uuXFghCXGyvF.png', NULL, NULL, 'KENN', NULL, 298262, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017145', 'AN1717', 'セイン・バウアー', 'The second heir within the Bauer Kingdom''s royal family. Thane is often stoic and feels his abilities are inferior to his brothers, giving him a complex about it. Thane is considered as the least popular capture target within the game.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b298260-wUaxgXWnriJQ.png', NULL, NULL, '浪川大輔', NULL, 298260, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
