INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017201', 'AN1720', 'ウィリアム・G・マリーブラッド', 'He is a lone human from the City of the Dead, born with vague memories of a past life and raised by a group of undead until the age of adulthood, he swore an oath to Gracefeel and leaves the city in search for adventure and civilisation while he restores the faith of his guardian deity.  He was brought to the City of the Dead as an infant by demons with the intention to be used as a sacrifice to break the seal placed upon the High King, however, he was found and taken in by a group of undead, th', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129745-gmUvsvhY0FPw.jpg', NULL, NULL, '千葉翔也', NULL, 129745, 'MAIN', 304) ON CONFLICT DO NOTHING;
