INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017204', 'AN1720', 'メネルドール', 'Meneldor is a half-elf outcast and most loyal friend of William. He was previously an adventurer and hunter.  He is a half-elf a mix race between humans and elves. His hair is silver that is tied up into a ponytail and his eyes are the colours of jade.  Meneldor was born in Grassland to the north, in the Great Forest of Erin where the elves live. Because of his mixture of elf and human blood he was an outcast and couldn''t get along with any of the residents, he later decide to run away and becom', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129750-NZoJAvMMbxn0.png', NULL, NULL, '村瀬歩', NULL, 129750, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
