INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017210', 'AN1720', 'スタグネイト', 'Stagnate is a malice goddess associated with undeath. She is the adversary of William and becomes particularly interested. She obverse his journey and aids him despite them being foes.   She is mischievous and cunning. She adores humans and wants to eternalise heroes who shine the way for others. She feels remorse and ashamed of how her Echo acted in his final moments.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129751-ZPdLRP9BHajw.jpg', NULL, NULL, '大久保瑠美', NULL, 129751, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
