INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017216', 'AN1720', 'グレイスフィール', 'Gracefeel is a mysterious goddess associated with the flame and enteral flux. She is the guardian deity of William.  She is a humanoid goddess with long black hair and gold eyes. She has a gentle face and wears a hooded robe that covers her notable features. She holds a lantern in her right hand usually held by a long handle. In her herald form, she takes the appearance of a warm flame.  Gracefeel is the goddess of the flame and flux. She was a renowned deity with many followers in the Union Age', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129753-E5mBHrKOTSfa.jpg', NULL, NULL, '悠木碧', NULL, 129753, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017217', 'AN1720', 'オーガスタス', 'Augustus is a specter. He has become something akin of a herald of Gracefeel''s and protects the seal of the High King.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n129747-FN0MVY3k6RAB.jpg', NULL, NULL, '飛田展男', NULL, 129747, 'SUPPORTING', 77) ON CONFLICT DO NOTHING;
