INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017235', 'AN1721', 'ルフ・ヴェルライズ', 'Leuf Vellize was the last chancellor of the Byandy Empire, serving Emperor Framrodia Byandiraz until she was killed in office at some time proximate to the empire''s collapse. She possesses Elemental hearing even in death and can thus communicate with Elementals, though she cannot see them.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302194-p43dMsTEmZ09.png', NULL, NULL, '本田貴子', NULL, 302194, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
