INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017238', 'AN1721', '虚銃座', 'Utsurojuza, real name Shula Zoozolozo Cramplamp Lampton, is the former third-ranking Imperial Court Sorcerer of the Byandy Empire and—or once was—an ''Enemy of the world.'' In the century-long wake of the empire''s collapse, he has allied with the alchemist Pani Guldmarg.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302195-TeEUYTxP5UIV.png', NULL, NULL, '松岡禎丞', NULL, 302195, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
