INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017275', 'AN1726', '小鳥遊聖', 'Sei Takanashi is an office lady in her twenties who was summoned by the Saint Summoning Ritual. Her saintly powers enhance her abilities by fifty percent, due to her appearance she was not crowned as Saint. Accidentally making scenes with her research, she is on the verge of being found out as the saint. But after seeing her abilities she was finally been recognized as the Saint. She Likes to cook and make cosmetics in her spare time.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188173-jITKX4tsmDDU.png', NULL, NULL, '石川由依', NULL, 188173, 'MAIN', 361) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017276', 'AN1726', 'アルベルト・ホーク', 'He is the commander of the Knights of the Third Order. He is nicknamed the "Ice Knight" for his frigid demeanor. He became an ally of Sei Takanashi after she saved him from a mortal wound.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188170-poMRW0FjHomE.png', NULL, NULL, '櫻井孝宏', NULL, 188170, 'MAIN', 255) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017277', 'AN1726', 'ヨハン・ヴァルデック', 'He is the director of a medicinal plants institute and the second son of Count Valdec.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188171-uCu8ZrHrF2eY.png', NULL, NULL, '江口拓也', NULL, 188171, 'MAIN', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017278', 'AN1726', 'ユーリ・ドレヴェス', 'He is the grand magus of the Royal Magi Assembly. His only interest is in research related to magic and magical powers. He looks cheerful and passionate on the outside, but on the inside, he is a completely different man.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188172-6hy90e0EMw7d.png', NULL, NULL, '小林裕介', NULL, 188172, 'MAIN', 165) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017279', 'AN1726', 'ジュード', 'He is a researcher at the same institute for medicinal plants as Johan Valdec and is responsible for teaching Sei Takanashi.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188174-6WRL8JPlNnd3.png', NULL, NULL, '八代拓', NULL, 188174, 'MAIN', 79) ON CONFLICT DO NOTHING;
