INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017290', 'AN1727', 'ベルグリフ', 'A former adventurer whose dreams were shattered long ago. An injury forced him to return to his hometown, but part of him could never give up on adventuring. This inspired his daughter to follow his path, and even now, he continues to train. He is quite bothered by the moniker ''Red Ogre" his daughter gave him.', 42, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290652-mr7dN1tYplOI.jpg', NULL, NULL, '諏訪部順一', NULL, 290652, 'MAIN', 56) ON CONFLICT DO NOTHING;
