INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017309', 'AN1729', 'ミーア・ルーナ・ティアムーン', 'Home town: Tearmoon Empire / Lunatear (Imperial Capital) / Whitemoon Palace  The Tearmoon Empire''s one and only Princess. Lazy, selfish, and a complete coward. She doesn''t have a specific goal and only care about herself. She''s 12 by the time she first attends to Saint-Noel Academy.  A few years later, the Empire was in ruins under a financial crisis, a famine and an epidemic that caused the death of 10% of its population. By the time Mia was 17, the revolutionary army caught her while on the ru', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172654-Khtu5KqgNWMM.png', '12月16日', NULL, '上坂すみれ', NULL, 172654, 'MAIN', 292) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017310', 'AN1729', 'ディオン・アライア', 'Home town: Tearmoon Empire  The imperial army''s mightiest swordman. His skills as a mercenary earned him an official rank in the imperial army, where he could become a squadron captain of 100 soldiers.  In the previous timeline, Mia''s selfish desire for a jewelry box sparked a conflict in Sealence Forest, resulting in a tragedy that killed all of Dion''s subordinates. Soon after the revolution broke out, Dion sided with the revolutionary army''s cause, where he played a major role in bringing down', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220630-6lkJDXqoRh0y.jpg', NULL, NULL, '古川慎', NULL, 220630, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017311', 'AN1729', 'ゴリアル', 'Home town: Kingdom of Remno  Commander of the Diamond Legion.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '喜屋武和輝', NULL, 220640, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017312', 'AN1729', 'ジェム', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220642-7CjVNkic3KY8.jpg', NULL, NULL, '利根健太朗', NULL, 220642, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017313', 'AN1729', 'アンヌ・リトシュタイン', 'One of Mia''s loyal retainers. She''s known to be a little clumsy in her duties as a maid. The eldest daughter of the Littstein family. From a commoner and poor origin, she didn''t come to the Whitemoon Palace to dedicate her life to loyal servitude to the imperial family but because she was in need of money.  In the previous timeline, by the time Mia was imprisoned, a few people had come to see Mia for the first few weeks but their visits ended as soon as they realized that she would never claim t', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220608-5cfI6fYXCpmh.png', '12月23日', NULL, '楠木ともり', NULL, 220608, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017314', 'AN1729', 'ラフィーナ・オルカ・ヴェールガ', 'Birthday season: Spring (early) Home town: Holy Principality of Belluga  The daughter of Duke Orleans, the ruler of the Holy Principality of Belluga where Saint-Noel Academy is located. The president of the student council and effective ruler of Saint-Noel Academy, where aristocrats and royalty such as Mia and Sion attend. She is a true saint who does not care about her status, treats ordinary people and nobles alike, and while giving mercy to them, she has a fastidious personality, values justi', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220619-Eg8yKNtHKgit.png', NULL, NULL, '東山奈央', NULL, 220619, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017315', 'AN1729', 'リンシャ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220641-gDjtqrkZW3uW.jpg', NULL, NULL, '白石晴香', NULL, 220641, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017316', 'AN1729', 'ルードヴィッヒ・ヒューイット', 'Home town: Tearmoon Empire  One of Mia''s loyal retainers. The second son of a mercantile family, he had been a bright spark ever since he was a young boy. He''d always dreamed of becoming a government official, but it didn''t take him long to realize just how rotten to the core the Tearmoon Empire was after he began studying towards his goal. It was because of this that he truly despised those blueblooded nobles and the imperial family. Disciple of the Wandering Sage.  In the previous timeline, he', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220609-27mvGxvFdxWC.jpg', NULL, NULL, '梅原裕一郎', NULL, 220609, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017317', 'AN1729', 'クロエ・フォークロード', 'She''s a timid girl whose defining features are her thick crop of black hair and even thicker glasses. She came from a family of merchants who ran a fairly large business. Given more to books than to banter, she has a much more reserverd personality unlike her parents.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220624-QdBNA43AfmMa.png', NULL, NULL, '高橋李依', NULL, 220624, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017318', 'AN1729', 'エリス・リトシュタイン', 'Home town: Tearmoon Empire / Lunatear (Imperial Capital)  Anne''s younger sister and second daughter of the Littstein family. She is naturally sick and usually stays in bed. Her hobby is writing novels, and she is also the author of the story Anne told to Mia in prison in the previous timeline.  In the previous timeline, she died before Mia''s execution, partly due to her lack of acquaintance and lack of a satisfying meal. For Mia, who was living in prison at the time, Elise''s story was one of her', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220614-gy9puYtej5Hk.jpg', NULL, NULL, '羊宮妃那', NULL, 220614, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017319', 'AN1729', 'ランベール', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '加藤渉', NULL, 220643, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017320', 'AN1729', 'ティオーナ・ルドルフォン', 'The eldest daughter of Outland Count Rudolvon, who owns a territory in the southern frontier of the Tearmoon Empire. In the empire, the Outland Count is considered a lower class noble, and in order to overcome the adversity, she is a talented woman who not only studies but is also good at swordsmanship. Her family consists of her father, the head of the Rudolvon Outland Count family, and her brother Cyril Rudolvon, who is two years younger. She is also on good terms with her maid, Liora Lulu, be', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220615-ySVc8rBaKmP1.jpg', NULL, NULL, '高尾奏音', NULL, 220615, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017321', 'AN1729', 'セロ・ルドルフォン', 'Home town: Tearmoon Empire / Outland County of Rudolvon  The eldest son of Outland Count Rudolvon and younger brother of Tiona. A young but scholarly person who likes to research, mainly good at botany.  In the previous timeline, his research was fruitful and the development of ''wheat resistant to cold'' saved food shortages in the territory, and played a major role for the revolutionary army in gaining popularity.  In the timeline of the main story, Mia remembers this when she interacts with Tio', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220634-50Z7g0ohQeSe.jpg', NULL, NULL, '関根明良', NULL, 220634, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017322', 'AN1729', 'レムノ国王', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '平林剛', NULL, 220637, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017323', 'AN1729', 'シオン・ソール・サンクランド', 'First Prince of the Kingdom of Sunkland, a country that boasted a proud lineage and power on par with the Tearmoon Empire. He is an all-around genius who displays great talent in everything, and is a good young man who strives for "fairness" and "justice".  In the previous timeline, he was one of the enemies who condemned Mia as "an incompetent ruler", helped the leader of the revolutionary army, and was present at Mia''s execution.  <br>_(Spoiler from Volume 2 of the LN)_', 12, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220617-FUQI0RSs8DvK.jpg', NULL, NULL, '堀江瞬', NULL, 220617, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017324', 'AN1729', 'マティアス・ルーナ・ティアムーン', 'Home town: Tearmoon Empire / Lunatear (Imperial Capital) / Whitemoon Palace  The current emperor of the Tearmoon Empire and Mia''s father. He deeply loved his late wife and has not remarried even after her passing. He is famous for his love for Mia. He persistently tells Mia "Call me daddy", but she constantly refuses to call him that. In the previous timeline, he was executed before Mia.', 48, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220633-2IqL6pGphe8e.jpg', NULL, NULL, '松山鷹志', NULL, 220633, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017325', 'AN1729', 'グレアム', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '伊丸岡篤', NULL, 220639, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017326', 'AN1729', 'リオラ・ルールー', 'Home town: Tearmoon Empire / Sealence Forest  A maid who serves Tiona Rudolvon. A native of the Lulu tribe, a minority ethnic group that lives in the forest area "Sealence Forest" that stretches across the border between the Rudolvon Outland Count and Berman Viscount territories. Many of the Lulu tribe are unfamiliar with the official language of the continent, and she is no exception, with a stuttering way of speaking. She is a master archer and has high physical ability. She is attached to her', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220616-l27qt72Jg24f.jpg', NULL, NULL, '斎藤楓子', NULL, 220616, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017327', 'AN1729', 'ベルマン', 'Home town: Tearmoon Empire, Berman Viscounty  The head of the Viscount Berman family, which has a fief next to the Rudolvon family. He''s concerned that his territory is smaller than that of the Outland Count Rudolvon, who seems to look down on him as a county aristocrat, and he plans to forcefully cultivate the Sealence Forest located between their territories.  In the previous timeline, this led to the outbreak of civil unrest among the Lulu tribe, which eventually led to the destruction of the', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220629-xR2JZxemxkmF.png', NULL, NULL, '佐藤せつじ', NULL, 220629, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017328', 'AN1729', 'ムジク', 'Home town: Kingdom of Remno / Doni Village  Hunter.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, '相馬康一', NULL, 220638, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017329', 'AN1729', 'アベル・レムノ', 'Home town: Kingdom of Remno / Fedscoud Castle  Second Prince of the Kingdom of Remno. He is a kind-hearted boy who treats women like a gentleman. However, in the Kingdom of Remno, where swordsmanship is held in high esteem and tend to be male dominated, he was often called a "weakling" for his character. In particular, he had been losing to his brother Gain, the first prince, who is two years older than him, in swordsmanship practice, and when he was shown Sion''s swordsmanship, which is superior', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220620-9kyGMq7p6QbJ.jpg', NULL, NULL, '松岡禎丞', NULL, 220620, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017330', 'AN1729', 'ルドルフォン', 'Home town: Tearmoon Empire / Outland County of Rudolvon  The head of the Outland Count Rudolvon family, father of Tiona and Cyril.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220635-nZ7rdtlM3Env.jpg', NULL, NULL, '谷昌樹', NULL, 220635, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
