INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017332', 'AN1729', 'キースウッド', 'Home town: Kingdom of Sunkland  A follower of Sion Sol Sunkland, the first prince of the Kingdom of Sunkland. Originally a war orphan, he was taken in by Abram, the current king, and raised like his own son. Because of this, he and Sion have grown up together like brothers, and they sometimes cross the boundaries of their relationship and treat each other frankly as if he were his own son. Although he is eccentric and cynical, he is at heart a loyal and sincere young man.  In the timeline of the', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220618-FNoB58nw19tM.jpg', NULL, NULL, '増田俊樹', NULL, 220618, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
