INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017335', 'AN1730', 'ダリ', 'Assuming the identity of a boy named Hitori, he and his brother Migi are adopted by the middle-aged couple, Mr. and Mrs. Sonoyama. He can be described as logical and precise. Dali is the twin most focused on his vengeance and instructs Migi to act stealthily like a good boy, but at times, he can lose his composure. Dali is highly protective of Migi; if anyone messes with Migi, Dali may resort to violent methods.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b284574-2ItxVSwnEPbw.png', NULL, NULL, '村瀬歩', NULL, 284574, 'MAIN', 123) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017336', 'AN1730', 'ミギ', 'Assuming the identity of a boy named Hitori, he and his brother Dali are adopted by the middle-aged couple, Mr. and Mrs. Sonoyama. He''s shown to be more sensitive of the two when it comes to emotions and has a hard time controlling his feelings.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b284573-reuUf3ZGegal.png', NULL, NULL, '堀江瞬', NULL, 284573, 'MAIN', 106) ON CONFLICT DO NOTHING;
