INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017346', 'AN1732', 'ゴウセル', 'He is shown to be completely clueless and unaware of others'' feelings, not understanding the meaning of friendship. He often states things factually, not understanding how what he says can upset people. He decides to assist Elizabeth on her journey, not because of a desire for justice, but because he felt obligated as a member of the Seven Deadly Sins.  Since Gowther doesn''t understand emotions, he goes to great length to understand them. For example, observing Meliodas and Ban''s friendship.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88823-Oppzl2h6OhO8.png', '6月2日', NULL, '高木裕平', 175, 88823, 'SUPPORTING', 1770) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017347', 'AN1732', 'メラスキュラ', 'Melascula is a warrior of the Demon Clan, serving directly under the Demon King as the Faith of the Ten Commandments.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126466-0BGdVrZnXGRB.png', NULL, NULL, '市道真央', NULL, 126466, 'SUPPORTING', 263) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017348', 'AN1732', 'マーリン', 'She is a member of the Seven Deadly Sins. She has the mark of the boars sin of gluttony. She was regarded as the greatest mage in Britannia and is the master of Vivian as well as a teacher of King Arthur of Camelot. She came to the aid of the sins in their battle against Hendirkson but had to leave to tend to the King. She has not officially rejoined the sins but said she would as soon as she was finished with her other business.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89180-rN6OVPki8h3V.png', '12月3日', 'AB', '坂本真綾', NULL, 89180, 'SUPPORTING', 1978) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017349', 'AN1732', 'ペルガルド', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b311029-uE2Vo8jX022g.jpg', NULL, NULL, '小山力也', NULL, 311029, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017350', 'AN1732', 'バルトラ・リオネス', 'The eleventh king of Liones and father of Elizabeth.  He was held captive after the Seven Deadly Sins were framed for killing the great holy knight Zaratras.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131565-U0CcO6YR8w3T.jpg', '11月11日', NULL, '西凜太朗', NULL, 131565, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017351', 'AN1732', 'オルロンディ', 'Orlondi is a vampire and royal member of the Vampire Clan. He served the Vampire King twelve years ago, during the time their clan controlled the Kingdom of Edinburgh.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199219-zkk9DQPjqyLa.jpg', NULL, NULL, '小牧未侑', NULL, 199219, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017352', 'AN1732', 'タイズー', 'is a mountain bandit-turned merchant, and a three-time champion of Vaizel''s annual fight festival', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n131910-F1jn6wUvyZwy.jpg', NULL, NULL, '松田健一郎', NULL, 131910, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017353', 'AN1732', 'ペリオ', 'Pelliot is a young boy who, like his group of friends, love to play role the Seven Deadly Sins and order the villagers around.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199216-eEK00CrGAqGW.jpg', NULL, NULL, '深川和征', NULL, 199216, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017354', 'AN1732', 'ドロレス', 'Dolores is a member of the Giant Clan and a friend of Diane.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131576-k8fcBCDAlGQU.jpg', '2月19日', NULL, '広橋涼', NULL, 131576, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017355', 'AN1732', 'ジェリコ', 'Jericho is an apprentice Holy Knight who served under the Weird Fangs. She was stationed at the Baste Dungeon, where the Deadly Sin, Ban was imprisoned. She is young woman of slim build, with light hair that is swept over the left side of her face and tied into a ponytail at the back. She wears a black coat over her armor, adorned with a cross on the left side and larger cross covering the back. Underneath her armor are similarly fashioned black clothes. Metal gauntlets cover her arms, while met', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/86699-oRLKbh6x7ijB.jpg', '9月6日', 'AB', '井上麻里奈', NULL, 86699, 'SUPPORTING', 495) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017356', 'AN1732', 'ハウザー', 'Hauser is a Holy Knight, a colleague and partner of Gilthunder, and a subordinate of the Great Holy Knight, Dreyfus. He wears a set of Holy Knight armor and has short light-colored curled up hair. Hauser demonstrates a lot of self confidence and is very optimistic, which is the complete opposite of Gilthunder''s personality; he is also shown to be somewhat naive and stupid.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/86685-EVUJUHwElo95.png', '9月19日', 'B', '木村良平', NULL, 86685, 'SUPPORTING', 221) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017357', 'AN1732', 'スレイダー', 'Slader was kidnapped and raised as a child by savages who held no regard for his worth as a human. After being freed by the king of Liones he pledged loyalty and resolved to hunt down any who wronged the kingdom.  He is a member of Dawn Roar who holds a rivalry against Gowther of the Seven Deadly Sins.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n131889-hA4qiH1hg8oL.jpg', '4月4日', NULL, '三木眞一郎', NULL, 131889, 'SUPPORTING', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017358', 'AN1732', 'ギーラ', 'Geera is a Holy Knight who left herself in a near-death state to have access to the Capital of the Dead and kill the Deadly Sins who had gone there. She is a young female with a slim build. She has long black hair and her eyes are depicted as if they are closed.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n86665-ZbYVIjmbyfl9.jpg', '12月6日', 'A', '伊瀬茉莉也', NULL, 86665, 'SUPPORTING', 246) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017359', 'AN1732', 'ガラン', 'Galand is a demon who is a member of the Ten Commandments, a group of elite warriors of the Demon Clan handpicked by the Demon King himself. He was sealed away along with the rest of the clan in the Coffin of Eternal Darkness until he was set free by Hendrickson.', 991, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131571-CQBpyMbZaxfO.png', '1月4日', NULL, '岩崎ひろし', NULL, 131571, 'SUPPORTING', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017360', 'AN1733', '瀬名垣一咲', 'When she was 5 both her parents died and she was adopted by her Yakuza grandfather', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213096-wKcfpnGAtnK0.png', NULL, NULL, '鬼頭明里', NULL, 213096, 'MAIN', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017361', 'AN1733', '宇藤敬弥', 'He is a 26-year-old yakuza member.', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213095-IF84jvqBEk9t.png', '12月22日', NULL, '梅原裕一郎', NULL, 213095, 'MAIN', 123) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017362', 'AN1733', '関谷香織', 'One of the Senagaki leaders.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213098-G0JDSQXt5phV.png', NULL, NULL, '中原麻衣', NULL, 213098, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017363', 'AN1733', '田貫幹男', 'Heir to the Tanuki group.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213099-FXKzZZTvDn0W.png', NULL, NULL, '榎木淳弥', NULL, 213099, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017364', 'AN1734', 'キタサンブラック', 'Team: Spica  Her smile brightens the room. A festival-loving bucket of sunshine.  Ever bright and cheerful, she loves festivals more than anyone else. Her innate altruism makes her unable to ignore a person in need, and she''s always ready to lend an ear. Her bottomless kindness has earned her the admiration of those around her, but when she gets too excited, her words take on a certain festival flair. With a smile as bright as the sun, she continues to run towards the dazzling horizon, hoping th', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200355-30WAdFX7GUOZ.png', '3月10日', NULL, '矢野妃菜喜', 140, 200355, 'MAIN', 681) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017365', 'AN1734', 'サトノダイヤモンド', 'Team: Capella  Possesses a will harder than diamonds! She can handle any jinx!  Born to an affluent house, she was showered with love and affection growing up. This sheltered upbringing has made her somewhat naive, but her gentle, honest demeanor hides a diamond-hard resolve. She trudges on resolutely, determined to break the Satono family''s jinx and bring honor to her family.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200354-eCorGNUFRn0E.png', '1月30日', NULL, '立花日菜', 135, 200354, 'MAIN', 272) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017366', 'AN1734', 'ゴールドシップ', 'Wild and unpredictable, this golden runner is unlike anybody else!  An unpredictable firebrand born with an extra helping of free spirit. She''s prone to some dramatic swings in mood and motivation—one moment she could be setting up an elaborate punchline, and in the next you would be hard-pressed to get her to move. She seems to get along with anyone and everyone, but it is unclear just how she views her bonds with others. Truly, one could call her Tracen''s greatest mischief-maker.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125305-EH7Kf1WPFY5x.jpg', '3月6日', NULL, '上田瞳', 170, 125305, 'SUPPORTING', 892) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017367', 'AN1734', 'サウンズオブアース', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b312667-ttv6YCHGknPH.png', '4月12日', NULL, 'MAKIKO', 161, 312667, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017368', 'AN1734', 'トレーナー', 'Trainer of Team Spica.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/125308-zi5QLqjXLBAF.jpg', NULL, NULL, '沖野晃司', NULL, 125308, 'SUPPORTING', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017369', 'AN1734', 'ドゥラメンテ', 'The most powerful blood flows through her body. The product of a prestigious family.  An elite Umamusume with a promising future, born from a prestigious family known for producing many excellent athletic Umamusume. She is usually quite serious and stoic, but when a race is in front of her, her fighting spirit takes over and she shows her wild side. She has been close friends with Air Groove from a very young age.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316322-KM8okxoRVHD8.png', '3月22日', NULL, '秋奈', 166, 316322, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017370', 'AN1734', 'ダイタクへリオス', 'Good vibes only! For real, for real! No cap! ☆ Who''s ready to party? This racer!  "I''m so loud?! Well, DUH, if you''re gonna do something, you gotta make it FUN! And if you wanna call that cringe, I''ll just crank it up even louder! ♪" That''s the mindset of this bright, chatty runner. Get ready for smilemaxxing and par-tays, ''cause she''s in it to enjoy it. Helios is never one to turn down an invitation, and has a way of making every occasion a blast.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205733-V2qapUVxBERM.png', '4月10日', NULL, '山根綺', 156, 205733, 'SUPPORTING', 214) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017371', 'AN1734', 'スペシャルウィーク', 'Rar''n to go! A pure-hearted girl focused on her dream.  Born in Hokkaido, Special Week is a bright and cheery, hardworking Umamusume. After losing her birth mother, Special Week was raised by her mother''s friend. Now, she hopes to make both her moms proud by fulfilling her promise of becoming Japan''s top racer. Though she may falter along the way, her indomitable spirit ensures that she runs ever forward.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125299-25UtXyMMdoyQ.png', '5月2日', NULL, '和氣あず未', 158, 125299, 'SUPPORTING', 637) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017372', 'AN1734', 'ツインターボ', 'Turbo boost! This wild charger knows no limits!  A student brimming with youthful energy who just wants to run, run, run like crazy! She doesn''t really know her own limits yet, so she has a tendency to hit them full-force, but she seems to be enjoying life on the wild side. She''s a bit immature compared to the other runners her age, and she can be a bit selfish, but it''s hard to fault her honest, whimsical personality.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200351-7PNcjunPxKY9.png', '4月13日', NULL, '花井美春', 146, 200351, 'SUPPORTING', 293) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017373', 'AN1734', 'メジロパーマー', 'Let''s have a good time! This Umamusume is upbeat and always there for friends.  A young lady from the renowned Mejiro family, though you might not guess it from her casual, friendly attitude. She''s quite a socialite and notices even little changes in the people around her, but having such talented relatives caused her to develop a bit of an inferiority complex. Eventually, she found a way to handle those feelings—run, run, and run some more, smiling all the way. As long as she keeps running ahea', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205734-6P1BUT7U7jYT.png', '3月21日', NULL, 'のぐちゆり', 160, 205734, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017374', 'AN1734', 'ヴィルシーナ', 'She is a confident young lady who takes pride in the fact that she deserves the title of "Queen," which is the highest position in the world. She is the eldest of three sisters and strives to set a good example for both of her sisters. She has been given a high-level education in a wealthy family and is very talented and accomplished. However, she has been cursed by the number "2", and has a difficult time winning.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b326198-G7W2v2vVGLVV.png', '3月5日', NULL, '奥野香耶', 158, 326198, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017375', 'AN1734', 'トウカイテイオー', 'Unbeatable and adorable! A happy hoppin'' racer.  A bright, bubbly Umamusume with a natural knack for racing. She''s long looked up to the student council president, Symboli Rudolf, and this admiration serves as her ultimate motivation in becoming the number one racer. Fans can''t get enough of Teio''s boundless confidence, and have lovingly dubbed her upbeat march the "Teio Step."', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125300-mb168DIpLbWC.png', '4月20日', NULL, NULL, 150, 125300, 'SUPPORTING', 2061) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017376', 'AN1734', 'マチカネタンホイザ', 'Straightforward and positive-thinking, this model student always gives 110 percent! But despite her efforts, her inner ditz often has her fumbling in crucial moments. The ups and downs balance out into results that are—according to her—completely average. She sometimes wishes she could be more like the strong personalities around her, but she''s determined to charge through and find success her own way!', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200353-DrAJpWOYyHxn.png', '5月7日', NULL, '遠野ひかる', 155, 200353, 'SUPPORTING', 255) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017377', 'AN1734', 'ライスシャワー', 'Bringer of misfortune? This racer pursues her dreams despite her dreary outlook.  A timid Umamusume, she is under the impression that any misfortune befalling those around her is entirely her fault, when really, it''s just bad timing. Nevertheless, she is determined to eradicate this supposed jinx of hers. She loves reading picture books in her spare time, especially "The Blue Rose of Good Fortune."', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205736-czNHCYh48fIc.png', '3月5日', NULL, '石見舞菜香', 145, 205736, 'SUPPORTING', 1001) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017378', 'AN1734', 'メイショウドトウ', 'In order to change her outlook and herself, this pessimist gives it her all.  Her self-esteem droops as low as her ears. Things never seem to go quite right for this clumsy girl. Even so, she''s determined to change herself for the better and doesn''t want to ever give up, all for the chance at securing a brighter future. She admires T.M. Opera O''s grandiose self-confidence.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211557-8Oxh2lU1wk7k.png', '3月25日', NULL, '和多田美咲', 164, 211557, 'SUPPORTING', 263) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017379', 'AN1734', 'ヴィブロス', 'Vivlos is a devilishly cute young lady. She''s the youngest of three sisters, and has been a spoiled brat since she was a child, because of her family''s wealth. She has been fascinated by Dubai since she went there on vacation, and longed to live a celebrity life in a luxurious country. Her goal is to run a race in Dubai, using her natural talent and great sense of timing as her weapons.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b326199-6tA1KTllLsru.png', '4月9日', NULL, '伊藤彩沙', 156, 326199, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017380', 'AN1734', 'ウオッカ', 'Headstrong and full of life! A roadster with a heart of gold.  Dedicated to being the coolest, this Umamusume tries her best to act like a delinquent. She takes after her motorcycle-loving father, emulating his hobbies and attitudes down to the letter. Her grandstanding nature sees her charge daringly into any challenge, never afraid of what she might face. She has a bit of a cat-and-dog relationship with her roommate, Daiwa Scarlet.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125304-XAdxEdkeSJh7.png', '4月4日', NULL, '大橋彩香', 165, 125304, 'SUPPORTING', 203) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017381', 'AN1734', 'イクノディクタス', 'Control freak. A skilled Umamusume who can adapt to anything.  A straight-laced Umamusume with the organizational prowess of a secretary. She expertly manages her condition with cool, collected assessments, but is surprisingly personable despite her strictness. She''s fiercely determined to keep herself running for as long as possible—inspired by a time in the past when she could not...', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200352-ciQm7Yb5QeVn.png', '4月16日', NULL, '田澤茉純', 163, 200352, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017382', 'AN1734', 'エアグルーヴ', 'The coolly calculating Empress. Highly gifted and ambitious.  The vice president of Tracen Academy''s student council, known to the other students as the "Empress". The daughter of an accomplished racer, she constantly strives to live up to her mother''s racing prowess and ability to guide others. To this end, she has joined her friend and confidant, Symboli Rudolf, in the student council. Despite her strict schedule, she still makes time to tend the flowers in the garden.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b140846-gsLxIFWO23fg.jpg', '4月6日', NULL, '青木瑠璃子', NULL, 140846, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017383', 'AN1734', 'マチカネフクキタル', 'Fortune be with me! This charm-tastic Umamusume loves fortune-telling.  A fortune-telling fanatic and lover of the supernatural, she''s content to leave the outcomes of races and many other things up to luck. If she''s not divining for her own sake, then she''s divining for someone else''s. She places an immense faith in a revelation from a certain god stating that as long as she keeps running, the way forward will open up before her. The name of the cat shaped bag that she carries is "Miss Nya."', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211561-BkDHJdLFeGhN.png', '5月22日', NULL, '新田ひより', 163, 211561, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017384', 'AN1734', '東条ハナ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b200349-H9F8fl4kDnIq.png', NULL, NULL, '豊口めぐみ', NULL, 200349, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017385', 'AN1734', 'ロイスアンドロイス', 'Make a legend! Aiming to be the strongest from a peculiar perspective.  A smart Umamusume that excels at working independently. In order to become the "strongest" Umamusume, winning over people''s hearts, she diligently studies how to appeal to fans in addition to her racing. In front of fans, she acts hardworking, but does not let that character show for others. She is truly a demon of self-production.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b329734-MMuH2A7sBgLF.png', '3月10日', NULL, '田辺留依', 159, 329734, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017386', 'AN1734', 'サイレンススズカ', 'The silent runner aiming to break the sound barrier.  An Umamusume seen as a prodigy who''s always ahead of the pack, both figuratively and literally. She gets so absorbed with running that she comes off as aloof, but most know that she is dedicated. She is roommates with Special Week and many find themselves attracted to her authentic personality.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125298-MyaIqv1U5mcg.jpg', '5月1日', NULL, '高野麻里佳', 161, 125298, 'SUPPORTING', 752) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017387', 'AN1734', 'ナイスネイチャ', 'Don''t expect much from her. This Umamusume is super cynical.  An Umamusume of humble background with a penchant for being pessimistic. She tends to think of herself as a supporting character, and this causes her to shy away from high expectations—this sometimes leads to imperfect performances. She has quite the knack for cooking and cleaning due to her working-class upbringing, and does so whenever she has time. She''s something of a familiar face among the seniors in her town.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200350-NCKuSh9jnxFm.png', '4月16日', NULL, '前田佳織里', 157, 200350, 'SUPPORTING', 377) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017388', 'AN1734', 'ミホノブルボン', 'Always follows commands! The cyborg Umamusume.  An Umamusume also known as the "Cyborg". She views the world through the lens of programming and databases, carrying out her objectives in an expressionless and robotic manner. Even so, she is not an emotionless machine—her constant training since her youth has simply resulted in less interactions with people, leading to her current personality. Underneath that robotic shell, she does indeed have feelings.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205735-SmbhSGTIgmv8.png', '4月25日', NULL, '長谷川育美', 160, 205735, 'SUPPORTING', 156) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017389', 'AN1734', 'リバーライト', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b319097-3BC0s6Wdu86u.jpg', NULL, NULL, NULL, NULL, 319097, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017390', 'AN1734', 'コパノリッキー', 'Rickey☆Lucky☆A Caring Feng Shui Girl☆  A bright and cheerful person generally stated to be a very lucky girl. Her knowledge of Feng Shui goes deep, and is all truly real. She has adopted Feng Shui not just in her daily life, but also while training and during races. She wants to make everyone happy with her Feng Shui power! Not only that, but her advice for bringing good fortune seems to be well received...', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b329733-GRio3RJb2Hf5.png', '3月24日', NULL, '稲垣好', 165, 329733, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017391', 'AN1734', 'サクラバクシンオー', 'This class representative''s gone wild! Full Speed Bakushiiiin!  A class representative who''ll rush recklessly into any situation. Once her mind is set on something, she''ll bakushin dash straight to her goal—often causing more chaos than she helps resolve. She never acts out of self-righteousness, however, and tends to feel downhearted if no one is asking for her assistance. Her aptitude for sprinting is quite overwhelming, and she is confident she can outrun anyone with unmatched speed.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265079-aZoxXDigj7Pm.png', '4月14日', NULL, '三澤紗千香', 158, 265079, 'SUPPORTING', 91) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017392', 'AN1734', 'メジロマックイーン', 'The crown jewel of the prestigious Mejiro clan. A classy and poised young lady.  Born into a family of racing legends, Mejiro McQueen is a long-distance runner who is the envy of her peers. She has class and decorum befitting her prestige, and is determined to take first at the Tenno Sho, like many Mejiro racers before her. On her days off, she enjoys having afternoon tea with the many other residents of the Mejiro estate.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125309-nhewmUEllCnU.png', '4月3日', NULL, '大西沙織', 159, 125309, 'SUPPORTING', 903) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017393', 'AN1734', 'サトノクラウン', 'Turf Magician! An elite sister you can rely on.  She is a cheerful and determined older sister who lives in both Hong Kong and Japan. She''s also one of the talented members of the Satono family, and carries the family''s high expectations. She has a personality that burns more brightly in the face of adversity, and sometimes solves problems as brilliantly as magic.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b312664-dNUGGNAoVMkV.png', '3月10日', NULL, '鈴代紗弓', 163, 312664, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017394', 'AN1734', 'ダイワスカーレット', 'Beyond arrogant! This hothead hates to lose.  Unyielding, strong-willed, and cheeky, she wants to be number one at everything she does. She usually plays the role of the perfect, mild-mannered honor student, but the truth is that she hates losing more than anything else. If it''ll help her be number one, she''ll go through any training—no matter how grueling. She sees her rather showy roommate Vodka as both her motivation and her rival.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125301-lWAxeTdvjUsS.png', '5月13日', NULL, '木村千咲', 163, 125301, 'SUPPORTING', 359) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017395', 'AN1734', 'シュヴァルグラン', 'Ambitious with a timid heart. Aiming to become a great Umamusume.  She''s introverted, withdrawn, and has an inferiority complex about her talented older and younger sisters. She spends her time working hard to hopefully surpass them both one day, and have her own abilities acknowledged. She''s not on bad terms with either of her siblings... but they both have a glamorous temperament, which makes her a bit out of place when they''re together.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b312665-roVfMWMIIrcN.png', '3月14日', NULL, '夏吉ゆうこ', 160, 312665, 'SUPPORTING', 208) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017396', 'AN1734', '黒沼', 'Mihono Bourbon''s Trainer, whom she refers to as "Master."', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211186-inQk4owAVX5D.png', NULL, NULL, '黒田崇矢', NULL, 211186, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
