INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017398', 'AN1735', '浅雛悠', 'Haruka is a taciturn high school student and "F4" racer belonging to "Komaki Motors".  With an obstinate personality that declares "I don''t need any support", he continues to run single-mindedly in order to fulfill his dream of standing on the podium.  He usually lodges at the Komaki household and works part-time as a newspaper delivery person.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297106-RqFYRF5HsPjH.png', '2月17日', 'A', '古屋亜南', NULL, 297106, 'MAIN', 38) ON CONFLICT DO NOTHING;
