INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017410', 'AN1736', '秋里コノハ', 'Konoha has great passion for visual novels and bishoujo games. She admires both classic and modern games. She experienced big dissapointment when the company where she works at, hired her to illustrate background characters. Her biggest dream is to create her own game.   She has a very childlike personality. She easily gets excited and prone to crying.', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313986-DD0XFbuSNjvp.png', NULL, NULL, '古賀葵', NULL, 313986, 'MAIN', 172) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017411', 'AN1736', '六田守', 'Alcoholsoft''s resident programmer and the president''s son. He is extremely confident in his own programming and has a near obsessive love of the PC-98. Despite programming for bishoujo games, he has no particular love for them.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313987-PQT391J1DTx4.png', NULL, NULL, '阿部敦', NULL, 313987, 'MAIN', 29) ON CONFLICT DO NOTHING;
