INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017455', 'AN1738', '小ノ星海果', 'She is a first-year student of Fujino Misaki High School who was unable to make friends due to extreme fright, and she was escaping from reality, thinking that she could express her feelings to aliens living on planets other than Earth.  She is extremely frightened and unable to communicate well with others. After meeting Yu, they set a goal to build a rocket to reach the stars in space.  Her special skill is swimming.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288810-61wtTbc61OKY.png', '1月22日', NULL, '船戸ゆり絵', NULL, 288810, 'MAIN', 207) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017456', 'AN1738', '明内ユウ', 'Yuu is Umika''s classmate and a self-proclaimed alien. She has a telepathic ability called "Odekopathy", which allows her to read the thoughts of others by matching her forehead with theirs.  She has an abysmal optimism and a bright personality, and she instantly melts away the anxiety and tension of others.  She also tends to hate steady effort and studying. With her natural cheerfulness and energy, she can easily open up to her new classmates. Due to a spaceship malfunction, she crash-landed on', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300088-jFB0qmeZdvYC.jpg', NULL, NULL, '深川芹亜', 160, 300088, 'MAIN', 122) ON CONFLICT DO NOTHING;
