INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017467', 'AN1739', '青山光男', 'He is the manager of the Planning and Sales department at Minette. Mitsuo''s wife ran away from him shortly after he bought a house and a new employee he was in charge of ran away after a week; as a result, he has low self-esteem and he is lonely. He tends to spend lot of time working and he often makes little time for his wife. Although, this is due to the fact that he had to work a lot to pay off the debt and mortgage for his new home he bought with his wife. His wife said that since he didn''t ', 39, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305655-4r5LJxljdK5T.jpg', '7月7日', 'O', '杉田智和', 180, 305655, 'SUPPORTING', 74) ON CONFLICT DO NOTHING;
