INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017469', 'AN1739', '白桃', 'He was an abandoned cat who was found and picked up by Kentarou Momose and Yuusei Shirosaki. Shirosaki later adopted him. He was named by taking a kanji each from Shirosaki''s (白) and Momose''s (桃) names.', 0, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305657-iwcS4TiFsNne.jpg', '2月2日', NULL, '下野紘', NULL, 305657, 'SUPPORTING', 133) ON CONFLICT DO NOTHING;
