INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017508', 'AN1743', '豚', 'An otaku who reincarnates in a different world and somehow turns into a pig!? He thinks he''s travelling with no abilities, but he can use his wits, smarts and guts to solve problems!', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b293769-iX5YGaCakl5g.jpg', NULL, NULL, '松岡禎丞', NULL, 293769, 'MAIN', 29) ON CONFLICT DO NOTHING;
