INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017511', 'AN1743', 'セレス', '"Um, Jess. Is that pig a friend? He keeps looking at my legs and saying weird things."   A Yethma girl from Yesuma that Jess and Buta meet during their travels. She realises Buta is actually human inside when he starts daydreaming while staring at her legs.', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313929-3vm53OO4kUfI.png', '2月14日', NULL, '富田美憂', NULL, 313929, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017512', 'AN1743', 'ブレース', 'A silent Yethma girl who had been imprisoned.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313930-TYgN6q1hNfMP.png', NULL, NULL, '能登麻美子', NULL, 313930, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017513', 'AN1743', 'Kuchisshi', 'A large dog that Notto takes with him. A capable companion who works together with Notto in battle. Although it has a wolf-like appearance, it is friendly and likes to sniff Jess'' bare legs.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b320354-T81tTiXUF6fW.png', NULL, NULL, NULL, NULL, 320354, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017514', 'AN1744', '時野谷瞬', 'He lives in poverty with his mother and younger sister, Mio. Due to an accident, his father passed away and Mio lost her ability to walk. To take care of Mio and support the household finances, he had to give up his passion for online gaming and start living a life focused on school and part-time work.  (Source: Official Site, translated)', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309586-2umLrQlLXdQu.png', '9月17日', 'AB', '小野賢章', NULL, 309586, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017515', 'AN1744', '三枝悠宇', 'A rising star actress. Her behavior and way of speaking are rough, giving the impression of a disappointing girl. When participating in e-sport tournaments, she hides her true identity behind a mask.  (Source: Official Site, translated)', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309587-jKbmDChanzKH.png', '7月20日', 'O', '雨宮天', NULL, 309587, 'MAIN', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017516', 'AN1744', '稲月望', 'Shun''s childhood friend. She is the daughter of Souta Inatsuki, the manager of the e-sports cafe "FOX ONE", where she helps after school as a staff member. She has a close relationship with Shun''s family, especially with his sister Mio.', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b309588-B1xmx4tHZIBc.png', '5月16日', 'A', '水瀬いのり', NULL, 309588, 'MAIN', 27) ON CONFLICT DO NOTHING;
