INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017523', 'AN1745', '翠石依織', 'Cheerful leader of AKYR. He is always smiling, but his feelings are unreadable. As he has been in the underground world for a long time, he somewhat lacks common sense between good and evil. He treasures the members like family members and has set his heart on creating a place for them.', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300539-MuRUxebghdEK.png', '5月2日', 'AB', '近藤孝行', 175, 300539, 'MAIN', 66) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017524', 'AN1745', '西門直明', 'Naokira is a member from The Cat''s Whiskers. He leads a double life as a linguistic professor by day and a bar owner by night. He''s always calm and collected. He treats everyone kindly without discrimination and can''t abandon anyone who is in trouble. He harbors a deep attachment for the bar he''s managing currently.', 34, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b291461-sS3zlk98FJcT.png', '9月18日', 'B', '竹内良太', 183, 291461, 'MAIN', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017525', 'AN1745', '朱雀野アレン', 'A young man who loves hip-hop above all else. He has a scary look in his eyes and isn''t friendly, so people find him hard to talk to, but he''s actually just awkward. He was born a quarter-Russian to a pianist father and an opera singer mother. He is also from a well-known musical family, but he left home after his parents disapproved of his passion for hip-hop.', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300537-eRFeou0mKWJf.png', '10月1日', 'AB', '梶原岳人', 178, 300537, 'MAIN', 98) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017526', 'AN1745', '矢戸乃上珂波汰', 'Elder twin brother of the Yatonokami family. He is an orphan in a poor city, raised by adults who oppressed him; thus he hardly trusts anyone. He is careless and tends to find things troublesome, but is devoted and will do anything for his twin brother, Nayuta. As of now, both of the twins are living off the money that they make from rapping for shady underground business.', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300538-SWiXJ4RA4Wff.png', '12月24日', 'B', '小林裕介', 165, 300538, 'MAIN', 148) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017527', 'AN1745', '燕夏準', 'Born in one of the most prominent financial conglomerate family in Korea. Due to his demeanor and looks, he was nicknamed ''Smiling Young Noble'', but he is actually quite sadistic in nature. Because he was born in a complicated environment swirling in conflicting interests and ulterior motives, he lived half of his life very fiercely and swore to take revenge on both of his parents in his heart.', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301229-hWKXLWmc9fuV.jpg', '4月8日', 'AB', '村瀬歩', 185, 301229, 'MAIN', 106) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017528', 'AN1745', 'アン・フォークナー', 'Their appearance takes that of a fashionable modern girl, but in reality, they are the manliest one in BAE. In their younger years, they were oppressed by their old-fashioned and strict mother. Because of that, they decided to live true to themselves. Right now, they are working part-time as a hostess, taking advantage of their good looks.', 20, 'なし', 'https://s4.anilist.co/file/anilistcdn/character/large/b301230-YbiJihUzjr4r.png', '6月12日', 'B', '96猫', 175, 301230, 'MAIN', 126) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017529', 'AN1745', '闇堂四季', 'He has a passive and introverted personality. When he ran away from home before, he was picked up by Saimon and started working at the bar. Just like that, he becomes a freeloader who works as a hall staff. Constantly nervous and have absolutely no self-confidence but, he excels at being able to recall any song just by listening to it once - his hidden talent.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301237-Rq7syEVtfQ4P.png', '8月8日', 'AB', '寺島惇太', 166, 301237, 'MAIN', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017530', 'AN1745', '矢戸乃上那由汰', 'Younger twin brother of the Yatonokami family. Nayuta has been sickly since he was little thus his elder brother, Kanata really cherishes and takes care of him a lot; so his self-centered personality stands out a bit. He has absolute trust in Kanata, who has protected him so far. He has a default, dry attitude towards his surroundings, but gets ridiculously excited when it comes to Kanata. He is also in charge of preparing cozmez''s costumes.', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301238-cpnCo8Sy9n6G.png', '12月24日', 'B', '豊永利行', 163, 301238, 'SUPPORTING', 111) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017531', 'AN1745', 'パラドクスデビル', 'The host of Paradox Live.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b321057-PH7QWoZdKORl.png', NULL, NULL, '三宅健太', NULL, 321057, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017532', 'AN1745', '雅邦善', 'A man with a large and muscular body and a very straight-forward, passionate personality. He is bad at reading the atmosphere, but that is the main factor in keeping AKYR in order. Zen was originally a police officer, but after meeting Iori, due to certain reasons, he decided to join him. He''s the trouble consultant for the hosts at the host bar.', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301239-3rcCG291mp7i.jpg', '1月1日', 'A', '月崎志麻', 188, 301239, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017533', 'AN1745', '棗リュウ', 'A childish but mysterious rapper and member of The Cat''s Whiskers. Ryu was found by Naoakira prior to the series. He is currently under Yohei''s tutelage, training to be a bartender. Ryu is also good friends with Hokusai from Akan Yatsura. Ryu is an eccentric, energetic person, often saying nonsensical things and acting in a way that can be bewildering or annoying to others.', 800, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301240-uQgmQ7wsKgmw.jpg', '4月1日', '"Thick and Syrupy"', '花江夏樹', NULL, 301240, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017534', 'AN1745', '伊藤紗月', 'He literally fights with everyone he sees except for his members. He acts tough, but he''s actually a very honest and good young man. In the past, he was betrayed by his own best friend and went through a difficult period of time; at that time, he followed Iori who picked him up. He is unaware that his MC name, Gaia, is the name of a goddess.', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301248-6PiQK6Aumc0d.png', '5月15日', NULL, '畠中祐', 170, 301248, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017535', 'AN1745', '円山玲央', 'Generally speaking, he''s the lively youngest member of AKYR. The type that shows all of his emotions on his face. His speciality is pushing work onto other people and is very sleek at it. Formerly a young master who lived in a mansion, however after a certain incident, his family was torn apart. During that time, he was picked up by Iori.', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301245-YkwDC2fpnvUe.png', '7月21日', 'B', '矢野奨吾', 162, 301245, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017536', 'AN1745', '征木北斎', 'A young man with a mysterious atmosphere. He had to experience a lonely childhood because his father was in prison. When he was living on the street, cats started piling up around him, so he became fond of cats. After a certain turmoil, he was picked up by Iori and joined AKYR. Hokusai is often misunderstood, but he has a very gentle and kind-hearted personality.', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301241-flUprwFyTmQe.png', '3月3日', 'AB', '土岐隼一', 193, 301241, 'SUPPORTING', 84) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017537', 'AN1745', '神林匋平', 'He''s a heavy drinker, so he is quick to lose temper. He was a pretty bad person before. Currently, he has turned over a new leaf; although he''s blunt, he''s genuinely compassionate, a man among men. He has known Saimon for a long time, they even had their own 2-people unit in the past. He treasures the spirit of HIPHOP.', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301236-0MSQCq9q79vO.jpg', '8月28日', 'O', '林勇', 176, 301236, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017538', 'AN1745', '辰宮晴臣', 'A member of BURAIKAN, the founders of Phantom Live. A legendary composer of tracks. Although he’s basically expressionless and unfriendly, with poor communications skills that make him seem damaged, the tracks he produces are expressive and delicate. His rap skills are extremely advanced, and the sound swims and glides as he pleases. At present, he owns a Chinese restaurant called Raimentei.', 36, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318875-AsB9qlVv8kR4.png', '9月9日', NULL, '諏訪部順一', NULL, 318875, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017539', 'AN1745', '九頭竜智生', 'A member of BURAIKAN, the founders of Phantom Live. He has an overwhelming affinity for phantoms and is able to create powerful illusions despite not having experienced any trauma. His music, produced with his outstanding musical sense, fascinates audiences all over the world, elevating the BURAIKAN name to the global level.', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b318876-HqKCnL8RJlz0.png', '6月21日', NULL, '小野賢章', NULL, 318876, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
