INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017559', 'AN1748', '河本カナ', 'The 17-year-old protagonist of season three, FLCL Alternative. She is a noisy airhead who works part time at a restaurant and hangs with her friends, Mossan, Hijiri and Pets in what was a unremarkable time until she crossed paths with Haruko who opened her N.O. Channel.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131264-IvhuKENyZnwe.png', NULL, NULL, '美山加恋', NULL, 131264, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
