INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017562', 'AN1748', '本山満', 'One of Kana''s friends who goes by the nickname "Mossan," a high school student with aspirations to be a clothing designer/model.<br></br>(Source: Wikipedia)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131266-aXejKpXImMqG.jpg', NULL, NULL, '田村睦心', NULL, 131266, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017563', 'AN1749', '春日未来', 'Hometown: Tokyo  Full of energy, and a tad bit dense, Mirai is the center of MILLIONSTARS, taking a similar role to Haruka in the original iDOLM@STER series.  She''s not a smart girl, as she tends to forget to do her homework, she didn''t know who Oda Nobunaga (one of the most, if not the most famous warlord in wartime Japan) was, and she always speaks before thinking. She also seems to be a terrible cook since her homemade special drink caused the Producer to make a really scary face.  Her path t', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b86147-7p47fYlxFFse.jpg', '6月28日', 'O', '山崎はるか', 156, 86147, 'MAIN', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017564', 'AN1749', '伊吹翼', 'Hometown: Tokyo  Tsubasa is a naturally talented and easygoing young girl that loves to do anything she views as fun. Tsubasa takes an interest in whatever is popular and tries to stay up to date with the latest trends. Her dream is to one day have the ideal "happy life" she imagines her role model has and believes this will be easier to reach if she becomes popular, which is why she likes to spend time with Rio, receiving guidance on how to become a "popular lady" like her. Tsubasa was even int', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b86151-EECzgzhypQQO.jpg', '7月30日', 'B', NULL, 158, 86151, 'MAIN', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017565', 'AN1749', '最上静香', 'Hometown: Saitama Prefecture  At first glance, one might think that she''s a stoic loner because of her harsh words towards the Producer (“I don''t have the time!”, ”A producer like this is better than none I guess”). Although, in truth, she is still childish, somewhat hot-blooded, and really cares for her friends.  The reason she acts harsh towards the Producer is because her distrust of adults (she sees them as selfish and she thinks that they always look down on children). This may have been ca', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b86153-qknC479krtMN.jpg', '9月14日', 'A', '田所あずさ', 162, 86153, 'MAIN', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017566', 'AN1749', 'エミリー スチュアート', 'Hometown: United Kingdom  The foreigner of the MILLIONSTARS, Emily is an energetic and cheerful European girl who loves Japan with a burning passion and aims to be a Yamato Nadeshiko.   Her standards of what is appropriate for a Yamato Nadeshiko and what is not is somewhat strange, like how she considers all idols to be Yamato Nadeshiko, or how she tries her best to not use any foreign words. She speaks in a very peculiar way, using complicated Japanese terms and words rather than ones more norm', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273801-T5M7HO9fFFA0.png', '1月8日', NULL, '郁原ゆう', 156, 273801, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017567', 'AN1749', '豊川風花', 'Hometown: Chiba  Fuka is a former nurse with a gentle and kind personality and always tries to look after the other idols and the Producer and due to her giving nature, it seems hard for her to decline majority of requests from others. Many of the younger idols look up to her as a big sister or even a mother due to to her reliable and caring demeanor. She is one of the oldest idols in 765 Production.  While many other busty idols either don’t realize their own sexiness or use it as their own wea', 22, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273806-83Colf3phLaI.png', '9月2日', NULL, '末柄里恵', 162, 273806, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
