INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017569', 'AN1749', '七尾百合子', 'Hometown: Tokyo  The bookworm of MILLION STARS, Yuriko is a girl who loves books very much. She loves reading any genre of book as long as it’s interesting to her, though her favorite genres seem to be fantasy and mystery. As such, Yuriko constantly daydreams and imagines about fantastical worlds and the magical aspects of the books she read in her daily life.   Yuriko can be shy around strangers, but when among her friends, or any book-related topic (or just something that stimulates her quite ', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b88501-nNdHhPc9yvxO.png', '3月18日', 'B', '伊藤美来', 154, 88501, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
