INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017574', 'AN1749', '高山紗代子', 'At first glance, Sayoko might look just like any other honors student. That''s not wrong, however, she''s actually more of a hot-blooded type. She''s been determined since childhood-- she’d always put her whole heart into things and never give up until the last second. However, Sayoko often lacks self-confidence, believing that she doesn''t have any outstanding talents. However, her determination allows her to believe that if she puts as much effort as she can into her work, she can do anything.  Sa', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252170-A0HgPzqiOEQF.jpg', '12月29日', 'A', '駒形友梨', 156, 252170, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
