INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017613', 'AN1749', '田中琴葉', 'Hometown: Tokyo  Kotoha is a very diligent girl with a passion for acting, though she often gets lost in it when doing so. If one had to describe what Kotoha is like in three words, it would be “an honors student”; she''s diligent, takes everything seriously, does all work to her absolute best, and she just seems to be perfect at everything. Yet, she actually has low self-confidence. She often says that she has no any real talents (except maybe acting), and she has a somewhat fragile mentality.  ', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b165576-wazxb4lD3wG8.jpg', '10月5日', 'A', '種田梨沙', 157, 165576, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
