INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017634', 'AN1751', '碧棺左馬刻', 'MC Name: Mr.Hc (Hardcore) Division: Yokohama Solo Song: G anthem of Y-CITY Quote: Life is not fair.  One of the four former members of The Dirty Dawg and current leader of MAD TRIGGER CREW alongside his teammates, Iruma Juto and Busujima Rio.  A yakuza who works in Yokohama with a perpetual sour look on his face. He''s the youngest member in his group. Quick to start a fight over the smallest things.  His father was domestically abusive, and his mother went on to kill his father for committing sa', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131610-C0OvVYNuQY8A.png', '11月11日', 'B', '浅沼晋太郎', NULL, 131610, 'MAIN', 413) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017635', 'AN1751', '飴村乱数', 'MC Name: easy R Division: Shibuya Solo Song: drops Quote: The optimist sees the doughnut, the pessimist sees the hole.  One of the four former members of The Dirty Dawg and current leader of Fling Posse alongside his teammates, Arisugawa Dice and Yumeno Gentaro.  Despite his child-like appearance, he''s quick-witted and is able to get a total understanding on how others perceive him. He livens up the scene with his innocent appearance, but ends up saying unnecessary things, and his natural airhea', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131611-BkFLj1BW9xGu.png', '2月14日', 'O', '白井悠介', NULL, 131611, 'MAIN', 600) ON CONFLICT DO NOTHING;
