INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017638', 'AN1751', '有栖川帝統', 'Division: Shibuya Solo Song: 3$EVEN and SCRAMBLE GAMBLE Quote: Love the life you live. Live the life you love.  A compulsive gambler and one of the three members of Fling Posse alongside Yumeno Gentaro and Amemura Ramuda. He hates steady, stable lifestyles. He''s so into gambling that he''ll bet his life as easily as he''ll bet money. He''s been surviving on his extreme lucky streak ever since he was born. He gambles for the thrill of it, though he takes hexes and jinxes very seriously. He always ca', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b142474-Jqq5aEIbNWdV.png', '7月7日', 'B', '野津山幸宏', NULL, 142474, 'SUPPORTING', 269) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017639', 'AN1751', '観音坂独歩', 'A normal office worker and one of the three members of Matenrou alongside Jinguji Jakurai and Izanami Hifumi.  An employee for a medical device manufacturer and a member of Matenrou. Peculiar in that he''s not peculiar at all. Always exhausted by his work as a salaryman. He has a habit of muttering to himself. A major cynic and tends to look at everything negatively. His pessimistic personality leaves him with very few friends and his only childhood friend is Hifumi, from his elementary days. He ', 29, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131613-L7CcTclCFrpG.png', '5月15日', 'O', '伊東健人', NULL, 131613, 'SUPPORTING', 673) ON CONFLICT DO NOTHING;
