INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017641', 'AN1751', '躑躅森盧笙', 'A teacher who used to be part of a comedy duo with Sasara Nurude and is currently part of the Osaka division. He has crippling stage fright and can''t speak in front of large crowds, but is nonetheless beloved by his students.', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b165127-IbGeVY3kTrrQ.jpg', '3月1日', 'A', '河西健吾', 181, 165127, 'SUPPORTING', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017642', 'AN1751', '東方天乙統女', 'The leader of the Party of Words. She took control over the government by coup d''état using the Hypnosis Mic in the first year of the H Age. She created and ratified the H law, abolished the military and built the women-centered society. In the third age of H, she organized a Division Rap Battle in which men compete against each other with their Hypnosis Mics for the territory.', 49, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186343-5AE7NrclxLXl.png', '6月24日', 'A', '小林ゆう', 159, 186343, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
