INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017645', 'AN1751', '入間銃兎', 'A policeman who investigates assault, bribery, embezzlement, extortion, and other heinous crimes. He was the one to suggest inviting Rio Mason Busujima to join him and Samatoki Aohitsugi in MAD TRIGGER CREW. He is the oldest member of the group.', 29, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145618-XYGrmMnAJDxe.png', '5月30日', 'A', '駒田航', NULL, 145618, 'SUPPORTING', 180) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017646', 'AN1751', '伊弉冉一二三', 'A worker at a host club and one of the three members of Matenrou alongside Jinguji Jakurai and Kannonzaka Doppo.  A host, who became so due to certain circumstances, and a member of Matenrou. Has an honest personality and a flirty tone of voice. Because of his appearance and tone, he is easily misunderstood. Actually an extreme gynophobe. Became a host to overcome his fear of women. When he puts on his suit, he transforms into quite the womanizer. A friend of Doppo''s since elementary school. Has', 29, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131614-7MfGlp6duQZZ.png', '6月22日', 'A', '木島隆一', 179, 131614, 'SUPPORTING', 305) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017647', 'AN1751', '勘解由小路無花果', 'The second person in the Party of Words'' hierarchy. The woman in charge of all political measures of the Party.  She deeply respects the leader of the Party, Otome Tohoten and owes her a debt of gratitude. She despises men from the bottom of her heart and believes that the world would be better without them. Even though she’s very strict with herself and others, she has a soft spot for Nemu Aohitsugi.', 31, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b186345-qi9ssq0IkCzD.png', '12月1日', 'AB', 'たかはし智秋', 173, 186345, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017648', 'AN1751', '天谷奴零', 'A conman in the Osaka division alongside Sasara Nurude and Rosho Tsutsujimori. He has a strong sense of duty, is a man of his word and is quite charming, but you can never quite tell when he''s speaking his mind.', 46, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b165126-l4Yv3r261Soa.jpg', '1月23日', 'A', '黒田崇矢', NULL, 165126, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
