INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017650', 'AN1751', '毒島メイソン理鶯', 'Half-American on his father''s side, and half-Japanese on his mother''s. He speaks and behaves as if he were still a soldier. During his time as a naval officer, he respected rank above anything else. For example, if a superior told him that white was black, then white was black. In dire circumstances, he shows no mercy to his enemies.', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145621-xsf8ydOdlBr0.png', '6月21日', 'B', '神尾晋一郎', NULL, 145621, 'SUPPORTING', 143) ON CONFLICT DO NOTHING;
