INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017669', 'AN1752', 'デメトリオ・タルデリ', 'Tardelli is a Forward. He wears the jersey #2 and #3, depending on the original source. He is based on the italian player Marco Tardelli. In the Italian dub of Shin Captain Tsubasa, he is named "Marchesi", while in the Italian localization of Captain Tsubasa: Rise of New Champions, his surname is translated as "Nardelli", possibly to avoid confusion with said real-life player.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334603-WmovMmMEPE5j.jpg', NULL, NULL, '伊藤節生', NULL, 334603, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
