INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017671', 'AN1752', '日向小次郎', 'National team Jersey Number: #9  Position: Forward   To help his family, Kojiro Hyuga wants to be a professional player, an ace striker. His devotion to football and his persistence to shoot the goal is outstanding. He was both Tsubasa’s and Genzo’s top rival. A great guy, Hyuga is not only strong, but he is also tough but at the same time caring. Can be a bit impulsive at times, though. He was once famous because of his roughness and many players were scared of him. But, Hyuga is actually a gen', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b6780-3ATo2nw9HXDR.jpg', '8月17日', NULL, '佐藤拓也', NULL, 6780, 'SUPPORTING', 190) ON CONFLICT DO NOTHING;
