INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017673', 'AN1752', '早田誠', 'Makoto Soda is a fearsome defender who knows how to injure people with tackles without the referee''s knowledge. He is quite fast and he tends to put effects on his balls when he passes or shoots. A bit like Hyuga and Napoleon, he is an impulsive person and can get into a fight with someone.  In the match between Nankatsu and Azumaichi, he gave Tsubasa a hard time and even injured Tsubasa''s leg. However Nankatsu still managed to win. He was also chosen as a member of the All Japan Jr. Youth, to p', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b43021-n7IMdzyTfUvq.jpg', NULL, NULL, '小林裕介', NULL, 43021, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
