INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017678', 'AN1752', 'Carlos', 'He first appeared in Captain Tsubasa ch. 51 "Opening Ceremony".  He''s the private Language teacher of Tsubasa Ozora, who helped him during his last year of middle school in order to get prepared for his departure to Brazil. He usually appears in the Ozora household and also cheered his student in the finals of the middle school tournament.  Carlos is very cheerful but also determined to make Tsubasa a good learner, always teasing his student that he gives more importance to Football (even stoppi', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334546-UFBKqZdlvJRE.jpg', NULL, NULL, NULL, NULL, 334546, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
