INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017707', 'AN1752', 'Elle Sid''s Mother', 'The mother of Elle Sid Pierre.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334551-VVFkyHlYK5r1.jpg', NULL, NULL, '濱口綾乃', NULL, 334551, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017708', 'AN1752', '藤沢美子', 'Yoshiko Fujisawa is Hikaru Matsuyama''s girlfriend, later fiancée, and former manager of Furano Middle School.  Yoshiko is Matsuyama''s grade school friend, originally from Hokkaido. She moves to United States after Furano Middle School lost to Nankatsu, but later return to Japan to meet Matsuyama and complete her education in Japan.  Yoshiko is a kind, hardworking and quiet girl, fitting well in the "Yamato Nadeshiko" ideal regarding women in Japan.  (Source: Captain Tsubasa Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334552-h9w5rWsLrZNo.jpg', NULL, NULL, '椎名へきる', NULL, 334552, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017709', 'AN1752', 'ホルセ・ガレヤ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334555-YAxXGmzLE83D.jpg', NULL, NULL, '伊藤節生', NULL, 334555, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017710', 'AN1752', 'フリオ ガルトーニ', 'Galtoni is an Argentinian keeper.  Galtoni is the regular goalkeeper of Argentina Jr. and later Olympic Argentina. He wears the number "1" jersey.  His name is a reference to Argentinian footballer Daniel Bertoni. In Get in the Tomorrow, his name is put as Jorge Galtoni, while in a color spread of the manga''s complete special issue, his name is put as Julio Galtoni.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334556-9TaACFzAwsdR.jpg', '5月6日', NULL, '小林大紀', NULL, 334556, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017711', 'AN1752', 'サルバトーレ・ジェンティーレ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334558-2zTvd7k5s2D8.jpg', NULL, NULL, '村田太志', NULL, 334558, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017712', 'AN1752', 'ガブリエル・ガルバン', 'Galvan is a defender of Argentina.  He is a character who first appeared in Captain Tsubasa, chapter 93. Due to his physique, he has good power, and proved to be reliable in Argentina''s defense line. He wears the jersey #5.  He is based on real life player Luis Galván. Interestingly enough, in Captain Tsubasa J: Get in the Tomorrow, his name is also put as Luis Galvan. Whether this is purposely or coincidentally is unknown. His name according to a color spread of the manga''s special complete iss', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334557-4keTNxgmYxCE.jpg', '4月18日', NULL, '木内太郎', NULL, 334557, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017713', 'AN1752', 'ミッシェル・フィッシャー', 'Michel Fischer is a French player. He was a member of Seine Jr. Youth in J Boys'' Challenge. Fischer and his teammates were football partners of Taro Misaki during the latter''s time in France. During the 1st International Jr. Youth Tournament in France, beside their home team, they also supported Misaki and the Japanese team.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334560-SnDgfIXjmaON.jpg', NULL, NULL, '米内佑希', NULL, 334560, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017714', 'AN1752', 'ジョルジュ', 'Georges is a French midfielder. In J Boys'' Challenge, he was a player of France Jr. Youth. In Rising Sun, he was part of Olympic France.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334561-JUa1ieDdlaC0.jpg', '2月25日', 'O', '小林大紀', NULL, 334561, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017715', 'AN1752', 'ミヒャエル ハイン', 'Hain is a midfielder who previously played as defender. He wears the number "7" jersey.  His name is a reference to former footballer Uwe Hain. His first name is Michael in the Complete special issue, and Matthias (マティアス) in Captain Tsubasa J: Get in the Tomorrow.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334563-d2gFT5c77VkG.jpg', '11月2日', 'O', '米内佑希', NULL, 334563, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
