INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017717', 'AN1752', '歌均', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334565-e0GNQzGY597F.jpg', NULL, NULL, '村田太志', NULL, 334565, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017718', 'AN1752', '早川あづみ', 'Nationality: French/Japanese Occupation: Exchange student; Supporter of All Japan Jr. Youth  Azumi Hayakawa is a French nikkei young woman who attended the same school as Taro Misaki during his two and a half year stay in Paris.  Azumi first appeared on Captain Tsubasa ch.90 "Big Gathering in Paris!".', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334566-zDHN3JoKASSI.jpg', NULL, NULL, '白砂沙帆', NULL, 334566, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017719', 'AN1752', '神田幸志', 'Koshi Kanda is the closest Tsubasa Ozora''s rival for the love of Sanae Nakazawa.  His first appearance was in Captain Tsubasa (chapter 56). He''s a tall, athletic, good-looking young man with slightly fluffy bangs. His looks change slightly in the 2023 series: his hair is a bit less fluffy, he has slightly tanned skin, and has dark blue eyes.  Kanda is a very emotional young man, impulsive and fiery. While not a cruel person, he can be extremely arrogant as well and especially to people that he e', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334567-bSBG7NmO0kkq.jpg', NULL, NULL, '中村悠一', NULL, 334567, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017720', 'AN1752', 'マイケ・ギルド', 'Mike Gildo was the coach of Germany Jr.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334568-cI3pr7gUx6Zq.jpg', NULL, NULL, '濱岡敬祐', NULL, 334568, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017721', 'AN1752', '石 鉄男', 'Tetsuo Ishida is an attacking midfielder who plays for Minamiuwa.  He first appeared on Captain Tsubasa ch.65 "Furano Goes to the Front". He is the captain of his team, with a good balance between offensive and defensive skills, as well as his excellent ball control. In the quarter-final, he and his team give Matsuyama''s Furano middle school a run for their money.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334569-OAC9ROYnplG9.jpg', NULL, NULL, '村田太志', NULL, 334569, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017722', 'AN1752', 'Jara', 'Jara is a German forward. He was a player of Hamburg Jr. Youth in J Boys'' Challenge.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334571-CSFeay3V7bRW.jpg', NULL, NULL, '西谷亮', NULL, 334571, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017723', 'AN1752', 'Karl-Heinz no Haha', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334572-k7uUPNsqHMKL.jpg', NULL, NULL, '竹内順子', NULL, 334572, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017724', 'AN1752', '片桐宗政', 'He first appeared in Captain Tsubasa manga. He''s a retired Japanese footballer and is an employee, primarily a talent scout of the Japan Football Association (JFA). According to World Youth Cup he comes from a very rich family, but broke ties with them for years when he chose soccer over joining the family enterprise.  Katagiri pulls the strings in the background and supports the many talents of the Golden Age, including Tsubasa, Misaki, Hyuga, Aoi, and many others, on their way to the top of th', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334574-aW5gmPgDfdmt.jpg', NULL, NULL, '浪川大輔', NULL, 334574, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017725', 'AN1752', 'Live Commentator', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334575-QhdOeKkyzQop.jpg', NULL, NULL, '前野智昭', NULL, 334575, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017726', 'AN1752', '小玉和男', 'Kazuo Kodama is the captain and a forward from Nishimine.  Kazuo Kodama appears in the one-shot manga, Boku wa Misaki Taro and its follow-up sequel Boku wa Misaki Taro 2. He also makes an appearance on the original series, episode 66, on a flash-back. He wears the number "9" jersey for Nishimine.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334577-829zyTPRZNlG.jpg', NULL, NULL, '小林大紀', NULL, 334577, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017727', 'AN1752', '加藤正則', 'Masanori Kato has played on the same team as Matsuyama since elementary school, guarding the goal mouth and defensive formation.  He first appeared in Captain Tsubasa ch.15 "Now it''s the entire country!".  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334576-9KnQdGAuyuwd.jpg', NULL, NULL, NULL, NULL, 334576, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017728', 'AN1752', '北詰誠', 'Makoto Kitazume was the coach of Toho Academy middle school during the Boys'' Fight arc.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334578-QSaYbiOuJX9I.jpg', NULL, NULL, NULL, NULL, 334578, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017729', 'AN1752', '町田町子', 'Machiko Machida is a friend of Yoshiko Fujisawa. In Boys'' Fight, she was a manager of the football club of Furano Middle School. In Battle of World Youth, she was among the ones who were by Yoshiko''s side at the hospital after the latter suffered a traffic accident.  (Source: Captain Tsubasa Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334580-1oL84EvZzJL4.jpg', NULL, NULL, '木村珠莉', NULL, 334580, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017730', 'AN1752', 'Koji', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334581-nu0ILxEEjvd3.jpg', NULL, NULL, '岩中睦樹', NULL, 334581, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017731', 'AN1752', 'Klaus', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334582-9MYBvxwDAMpg.jpg', NULL, NULL, '伊藤節生', NULL, 334582, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017732', 'AN1752', 'トーマス・マガトゥー', 'Magath translated as Magdt in the German edition, is a defender. He wears the number "5" jersey. He is a very resoluted player in terms of tackle power and sharp defense. He is one of Germany''s main fullbacks.  His name is a reference to former footballer Felix Magath. His first name is Thomas in the Complete special issue, and  Bruno in Captain Tsubasa J: Get in the Tomorrow.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334583-RHjAmYD2rBMr.jpg', NULL, NULL, '伊藤節生', NULL, 334583, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017733', 'AN1752', 'Matteo', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334584-CS2IJ56ZMv9X.jpg', NULL, NULL, '米内佑希', NULL, 334584, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017734', 'AN1752', 'ディモス・マリーニョ', 'Dimos/Marigno is a defender. He wears the jersey #3. He is based on the Italian player Giampiero Marini. His full name is unknown. While in the manga, one of his teammates call him Dimos, in 3109 Perfect Data, he is named Marigno. It is likely that Dimos could be a separate player, such as can be seen in Captain Tsubasa J: Get In The Tomorrow.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334585-NO6HES6J5ui5.jpg', '6月29日', NULL, '西谷亮', NULL, 334585, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017735', 'AN1752', 'ミツル', 'Mitsuru is a substitute midfielder from Nishimine.  Mitsuru appears in the one-shot manga, Boku wa Misaki Taro (1984). He also makes an appearance on the original series, episode 66, on a flash-back. He wears the number "12" jersey for Nishimine.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334586-lguFceYqG9TT.jpg', NULL, NULL, '花江夏樹', NULL, 334586, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017736', 'AN1752', 'デューター・ミューラー', 'Deuter Müller is Germany''s first choice keeper, known as the "Phantom Keeper" and, subsequently, the "Steel Giant".  Muller had earned a legendary status in his home country even before his debut for Germany Jr. Youth in the Junior Youth tournament in France. He has been one of the German side''s main players since.  Due to the severe training on a mountain, Muller is exceptionally strong and tough and remarkably agile for his size. His mere presence in goal gives an impression of impenetrability', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334588-RIanDRCKb3R8.jpg', '8月10日', 'O', '細谷佳正', NULL, 334588, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017737', 'AN1752', 'Mitsuru no Haha', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334589-irlA5SfKd3yo.jpg', NULL, NULL, '佐藤はな', NULL, 334589, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017738', 'AN1752', '西本ゆかり', 'Yukari Nishimoto is a kindergarten teacher. She''s Sanae Ozora''s best friend and used to be a student in Nankatsu.  She is a minor recurring character in Captain Tsubasa. She lives in the city of Nankatsu, Shizuoka, but used to live in Nagasaki. She used to go to Nankatsu school with her close friends Sanae Ozora and Ryo Ishizaki.  (Source: Captain Tsubasa Wiki)', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334590-LTuaz1jqhxOa.jpg', NULL, NULL, '潘めぐみ', NULL, 334590, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017739', 'AN1752', 'Murnau', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334591-Le92ohl966KU.jpg', NULL, NULL, '西谷亮', NULL, 334591, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017740', 'AN1752', '西尾浩司', 'Kouji Nishio is a minor character of the Captain Tsubasa, who appeared in the first original manga.  Nishio was part of Nankatsu SC and Otomo middle school. He wears the number #3 jersey.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334592-VQlOPGStpqaj.jpg', NULL, NULL, NULL, NULL, 334592, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
