INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017742', 'AN1752', '小田強', 'Tsuyoshi Oda is a retired defender of Nankatsu and a university student.  He first appeared in the Captain Tsubasa manga. He used to wear the jersey #4 in middle school.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334594-7RfzE3yXTv4D.jpg', NULL, NULL, '小林大紀', NULL, 334594, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
