INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017747', 'AN1752', 'カルロス・サンターナ', 'Carlos Santana is a Brazilian player. One of the most skillful player in the world. In his past lies a very dark obstacle that he must overcome - he didn''t have a family. He was abandoned as a baby on the field of soccer.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334600-SnL172uCTSkl.jpg', '5月1日', 'O', NULL, NULL, 334600, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
