INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017750', 'AN1752', 'ルディ・フランク・シュナイダー', 'Rudi Frank Schneider Karl Heinz Schneider''s father and coach of several generations of the German National Team and the current coach of FC Bayern Munich.  Rudi and his wife were thinking of divorcing due to their diffences since Rudi''s wife was tired of having the German people being against Frank''s decisions in the club. This also affected Karl''s performance and his younger daughter Marie.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334604-FG7pyp4zJc6o.jpg', NULL, NULL, NULL, NULL, 334604, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017751', 'AN1752', '山村', 'Yamamura is a fan Ichiro Misaki''s paintings. In Boku wa Misaki Taro, he wished that one day Ichiro would paint Mount Fuji. Ichiro eventually painted that in Rising Sun, and Yamamura made sure he was the first one to see it.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334605-kDWY747vG0j0.jpg', NULL, NULL, '大泊貴揮', NULL, 334605, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
