INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017753', 'AN1752', '杉本久美', 'She is the 2nd assistant manager in Nankatsu middle school during the Boys'' Fight arc. She also appears in the Holland Youth Manga Special and was supporting Nankatsu until the Golden Generation ended high school.  Sugimoto first appeared on Captain Tsubasa (1981) chapter 51. She is a kouhai (underclassman) of the rest of the Nankatsu gang, attending first year of Middle School whereas near everyone else in the team attends third year. She has a somewhat naïve and straight-forward personality. I', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334611-KQU8E3gQWuof.jpg', NULL, NULL, '福原綾香', NULL, 334611, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
