INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017757', 'AN1752', '本間実', 'He first appeared in Captain Tsubasa (1981) chapter 26. He''s a member of Musashi''s trio. He played as regular forward for Musashi FC and Musashi middle school. He wears the jersey #10. Later on, he was a substitute in Japan Youth.  Honma is one of the core offensive of the team when Misugi is not playing. He has being chosen as a top forward among 1000 players from Musashino.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334573-BYW1zn8H2su8.jpg', '3月25日', NULL, NULL, NULL, 334573, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017758', 'AN1752', 'ジェンティーレ ゴルバテ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334559-Kx2Kq1DFqwex.jpg', NULL, NULL, '岩中睦樹', NULL, 334559, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017759', 'AN1753', '風見バード', 'He is an amateur blader who came to X City to become a professional.  Although he was the strongest in his hometown, he was defeated by a professional and his partner Beyblade was destroyed. He got abandoned by his old teammates after that and despaired. But then Kamen X suddenly appeared in front of him and together they form a new team called "Persona.'''' At first, he was suspicious of Kamen X. But after seeing his unparalleled strength and the way he truly enjoys Beyblade, he remembers how muc', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305925-caQ7lmrU9Cjq.png', '8月10日', NULL, '梅田修一朗', NULL, 305925, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017760', 'AN1753', '七色マルチ', 'Multi Nanario is a famous influencer and strong blader with her partners wizard arrow and knight shield. She joins team Persona after losing to them in a battle.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305926-QvrpRlC7hrK5.jpg', NULL, NULL, '野口瑠璃子', NULL, 305926, 'MAIN', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017761', 'AN1753', '黒須エクス', 'He is a former member of the X Tower champion team Pendragon. His partner beyblade is DranSword. He is an elusive character who declares that "Beyblades are for fun". He is overwhelmingly strong and has an undefeated record, but disappeared as soon as he reached the ''top'' of X Tower. He does this in order to fight his former teammate and current champion Ryugu Chrome. He forms the team Persona with Bird and Multi and takes on the X Tower.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305924-oohFMlZtXTR2.png', '1月23日', NULL, '斉藤壮馬', NULL, 305924, 'MAIN', 40) ON CONFLICT DO NOTHING;
