INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017797', 'AN1758', '澄空つばさ', 'The protagonist who is a new hire in the A&R department of Gandala Music. She is cheerful and positive, and she does everything honestly and with all her might.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89881-5iyTD5dlMrjS.png', NULL, NULL, '瀬戸麻沙美', NULL, 89881, 'MAIN', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017798', 'AN1758', '寺光唯月', 'Haruhi''s twin older brother; he is of mixed heritage.  He has a quiet, mysterious air about him. He is slightly self-conscious about his handsome face.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137419-iz5wMKvHyLeM.png', '4月9日', 'A', '西山宏太朗', 172, 137419, 'MAIN', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017799', 'AN1758', '北門倫毘沙', 'Gentle and a romantic at heart.  A classic "prince" type raised in a wealthy family. He is mild-mannered and capable, though he is also somewhat out of touch with common sense.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89866-Hb6kJ7Wdusnz.png', '3月29日', 'AB', '小野大輔', 180, 89866, 'MAIN', 98) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017800', 'AN1758', '野目龍広', 'A serious, compassionate, and pure-hearted young man.  He has no immunity towards women and is also shy towards others. He has good athletic nerves and is especially good at sword fighting.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89873-SWYuSzM25zlU.png', '1月11日', 'A', '大河元気', 179, 89873, 'MAIN', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017801', 'AN1758', '倉田永輔', 'A hardcore otaku with exceptional social skills whose hobby is computing.  He has been composing music since junior high and takes pride in his work, but B-ta''s compositions are in a league of their own.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313811-qitBMTsJ3RKZ.png', '9月29日', 'AB', '畠中祐', 170, 313811, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017802', 'AN1758', '是国竜持', 'He has a "little devil" personality—shrewd yet adept at acting the spoiled charmer.  His appearance is so feminine that he is sometimes mistaken for a woman. He loves sweet treats and always keeps Chupa Chups on hand.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89865-MuwPiWxtZwIe.png', '11月11日', 'B', '岸尾だいすけ', 165, 89865, 'MAIN', 99) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017803', 'AN1758', '増長和南', 'A hard worker and a perfectionist.  He is model student who is kind, mild-mannered, and cooperative. He often acts as a mediator within the group.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89870-dpfUsT08NAfA.png', '2月23日', 'O', '上村祐翔', 176, 89870, 'MAIN', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017804', 'AN1758', '柏木文太', 'Interested in music from a young age, he became a well-known figure in the scene after he started posting his songs.  Captivated by A-suke''s singing voice, he formed the group Ultraz.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313812-vNoFAUfFVDvT.png', '6月17日', 'B', '伊東健人', 184, 313812, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017805', 'AN1758', '金城剛士', 'A returnee with a strong artistic mindset and an edgy personality.  Deeply committed to music, he can be stubborn and lack cooperativeness. His special talents include playing the guitar and speaking English.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89867-cexfbWJwpc0d.png', '7月4日', 'O', '豊永利行', 171, 89867, 'MAIN', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017806', 'AN1758', '釈村帝人', 'An intelligent and capable individual, but at heart, an otaku who absolutely loves 2D media.  He is particularly obsessed with "Majokko Mamirin," though he keeps this fact hidden at work.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89874-OiKlOs7UwaPo.png', '1月25日', 'A', '増田俊樹', 177, 89874, 'MAIN', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017807', 'AN1758', '音済百太郎', 'A cool boy raised in the city.  Because he rarely shows his emotions, he is often misunderstood, but he is a serious person who faithfully keeps his promises. He possesses a sixth sense and occasionally makes cryptic remarks.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89871-UBpGIc9nHk7L.png', '9月22日', 'AB', '柿原徹也', 169, 89871, 'MAIN', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017808', 'AN1758', '不動明謙', 'Someone who takes immediate action the moment an idea strikes.  An inherently positive leader who rallies everyone around them. Despite a cute appearance, he possesses a spirited, manly nature. A childhood friend of the Lord.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137422-gg3QT6huSzSY.png', '10月30日', 'O', '千葉翔也', 165, 137422, 'MAIN', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017809', 'AN1758', '愛染健十', 'Proud and narcissistic.  He has a flirtatious nature; hitting on any woman he sees is second nature to him. He is constantly fussing over his bangs.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89869-1GjiHjTrhLq8.png', '8月30日', 'B', '加藤和樹', 181, 89869, 'MAIN', 44) ON CONFLICT DO NOTHING;
